    /// `messages.receipts` (contract 1.190 §4.190 ⑤): one message's
    /// per-recipient receipt ledger, read-only. The message must resolve in
    /// the named conversation (the getText addressing discipline); a message
    /// that predates the ledger — or one no peer ever receipted — answers
    /// the honest empty list, never an error.
    pub fn get_message_receipts(
        &self,
        account_id: &str,
        conversation_id: &str,
        message_id: &str,
    ) -> Result<Vec<crate::store::RecipientReceiptRow>, ServiceError> {
        validate_opaque_id(account_id, "accountId")?;
        validate_opaque_id(conversation_id, "conversationId")?;
        validate_opaque_id(message_id, "messageId")?;
        let Some(_record) = self
            .store
            .message_by_id(account_id, conversation_id, message_id)?
        else {
            return Err(ServiceError::Store(StoreError::MessageNotFound));
        };
        Ok(self.store.message_receipts_for(account_id, message_id)?)
    }

    #[allow(clippy::too_many_arguments)]
    pub fn prepare_send_text(
        &self,
        account_id: &str,
        conversation_id: &str,
        text: &str,
        client_request_id: &str,
        quote_message_id: Option<&str>,
        previews: Option<Vec<SendTextPreviewParams>>,
        mentions: Option<Vec<SendTextMentionParams>>,
        text_styles: Option<Vec<SendTextStyleParams>>,
        story_reply_author: Option<String>,
        story_reply_timestamp: Option<Value>,
    ) -> Result<PreparedSend, ServiceError> {
        let preview = previews_to_upstream(previews, text)?;
        validate_text(text)?;
        validate_opaque_id(client_request_id, "clientRequestId")?;
        if let Some(quote) = quote_message_id {
            validate_opaque_id(quote, "quoteMessageId")?;
        }
        if let Some(existing) = self
            .store
            .message_by_client_request(account_id, client_request_id)?
        {
            return Ok(PreparedSend::Existing(Box::new(existing)));
        }
        let account = self.resolve_account(account_id)?;
        let mentions = self.mentions_to_upstream(&account, mentions)?;
        let text_styles = self.text_styles_to_upstream(text_styles)?;
        let conversation = self.resolve_conversation(account_id, conversation_id)?;
        self.dispatch_send(
            &account,
            &conversation,
            text,
            client_request_id,
            quote_message_id,
            preview,
            mentions,
            text_styles,
            None,
            Vec::new(),
            false,
            story_reply_author,
            story_reply_timestamp,
            None,
        )
    }

    /// Prepare a send addressed by peer (kind + peer_key) instead of an
    /// existing conversation id. When no conversation for the peer exists yet,
    /// it is created here and carries the first outgoing message. Since
    /// contract revision 1.14 a contacts.sync already materializes skeleton
    /// conversations for synced peers (§6.5), so this path mostly attaches the
    /// first message to an existing skeleton; unknown peers still get their
    /// conversation from this send.
    #[allow(clippy::too_many_arguments)]
    pub fn prepare_send_text_to_peer(
        &self,
        account_id: &str,
        peer: &PeerTarget<'_>,
        text: &str,
        client_request_id: &str,
        quote_message_id: Option<&str>,
        previews: Option<Vec<SendTextPreviewParams>>,
        mentions: Option<Vec<SendTextMentionParams>>,
        text_styles: Option<Vec<SendTextStyleParams>>,
        story_reply_author: Option<String>,
        story_reply_timestamp: Option<Value>,
    ) -> Result<PreparedSend, ServiceError> {
        let preview = previews_to_upstream(previews, text)?;
        validate_text(text)?;
        validate_opaque_id(client_request_id, "clientRequestId")?;
        if let Some(quote) = quote_message_id {
            validate_opaque_id(quote, "quoteMessageId")?;
        }
        // contacts.list reports 'contact'; conversations use 'direct'. Both are
        // accepted for the same direct-chat target.
        let kind = match peer.kind {
            "direct" | "contact" => "direct",
            "group" => "group",
            _ => {
                return Err(ServiceError::Api(ApiError::new(
                    "INVALID_REQUEST",
                    "kind must be 'contact', 'direct', or 'group'",
                    false,
                )));
            }
        };
        validate_opaque_id(peer.peer_key, "peerKey")?;
        // 契约 1.269（§4.253 · 批 Z14）：direct 语义的对端键只认协议词形
        // （ACI/PNI UUID 或电话键）——群 master key base64 混进来（宿主把
        // compose 群组行当联系人直发）会 mint 出 peer_key=群 key 的怪
        // direct 行（成员卡三键寻址梯恒 miss 的实案根因）。fail-closed：
        // 群目标必须走 kind="group" 臂。
        if kind == "direct"
            && !crate::engine::is_uuid_shaped(peer.peer_key)
            && !peer.peer_key.starts_with('+')
            && !peer.peer_key.chars().all(|c| c.is_ascii_digit())
        {
            return Err(ServiceError::Api(ApiError::new(
                "INVALID_REQUEST",
                "direct peerKey must be a ServiceId (ACI/PNI) or a phone number — group keys belong to kind=group",
                false,
            )));
        }
        let peer_title = peer
            .peer_title
            .map(str::trim)
            .filter(|title| !title.is_empty())
            .map(|title| title.chars().take(64).collect::<String>());
        if let Some(existing) = self
            .store
            .message_by_client_request(account_id, client_request_id)?
        {
            return Ok(PreparedSend::Existing(Box::new(existing)));
        }
        let account = self.resolve_account(account_id)?;
        let mentions = self.mentions_to_upstream(&account, mentions)?;
        let text_styles = self.text_styles_to_upstream(text_styles)?;
        let title = peer_title.unwrap_or_else(|| {
            if kind == "group" {
                "group".to_string()
            } else {
                mask_address(peer.peer_key)
            }
        });
        let conversation =
            self.store
                .ensure_conversation(account_id, kind, peer.peer_key, &title)?;
        self.dispatch_send(
            &account,
            &conversation,
            text,
            client_request_id,
            quote_message_id,
            preview,
            mentions,
            text_styles,
            None,
            Vec::new(),
            false,
            story_reply_author,
            story_reply_timestamp,
            None,
        )
    }

    /// Validate and normalize the caller-supplied mentions (contract revision
    /// 1.34) into the exact shape the upstream `send` expects. Enforced here —
    /// not at the engine — because the engine answers a malformed or
    /// unresolvable mention entry with a late upstream internal error, which
    /// would surface as an unknown-outcome-shaped send failure instead of
    /// deterministic local behavior.
    ///
    /// Rules (spec §4.29): more than 64 entries are dropped (the §4.20
    /// receive cap mirrored); an empty/whitespace number fails the whole
    /// request closed INVALID_REQUEST; a UUID-shaped number passes through
    /// (the engine resolves ACIs directly); anything else must digit-suffix
    /// match the linked account's own number or the cached contacts — the
    /// engine `resolve_author_aci` rule — and is dropped when nothing matches
    /// (the official behavior for unresolvable mention addresses). Entries
    /// that survive keep their `number` verbatim: the engine re-resolves
    /// against its own store, which stays the single resolution authority.
    fn mentions_to_upstream(
        &self,
        account: &AccountRow,
        mentions: Option<Vec<SendTextMentionParams>>,
    ) -> Result<Option<Vec<UpstreamSendMention>>, ServiceError> {
        let Some(mentions) = mentions else {
            return Ok(None);
        };
        let mut upstream = Vec::with_capacity(mentions.len().min(MAX_SEND_MENTIONS));
        let mut contacts: Option<Vec<String>> = None;
        for entry in mentions.into_iter().take(MAX_SEND_MENTIONS) {
            if entry.number.trim().is_empty() {
                return Err(ServiceError::Api(ApiError::new(
                    "INVALID_REQUEST",
                    "mention number must not be empty",
                    false,
                )));
            }
            let keep = is_uuid_shaped(&entry.number) || {
                let digits = address_digits(&entry.number);
                !digits.is_empty()
                    && (address_digits(&account.signal_account) == digits
                        || contacts
                            .get_or_insert_with(|| {
                                self.store
                                    .contact_peer_keys(&account.id)
                                    .unwrap_or_default()
                            })
                            .iter()
                            .any(|peer_key| {
                                let candidate = address_digits(peer_key);
                                !candidate.is_empty() && candidate.ends_with(&digits)
                            }))
            };
            if keep {
                upstream.push(UpstreamSendMention {
                    number: entry.number,
                    start: entry.start,
                    length: entry.length,
                });
            }
        }
        Ok((!upstream.is_empty()).then_some(upstream))
    }

    /// Validate and normalize the caller-supplied text-style ranges (contract
    /// revision 1.69, §4.62) into the exact shape the upstream `send`
    /// expects. Enforced here — not at the engine — for the same reason the
    /// §4.29 mentions are: the engine answers a malformed entry with a late
    /// upstream internal error, which would surface as an
    /// unknown-outcome-shaped send failure instead of deterministic local
    /// behavior.
    ///
    /// Rules: more than 64 entries are rejected INVALID_REQUEST (the §4.20
    /// receive cap mirrored; the mentions family drops extras, but a style
    /// list is caller-authored formatting, not protocol-received data, so the
    /// deterministic rejection is the honest shape); the style value is one
    /// of the five protocol-renderable upstream enum values (BOLD / ITALIC /
    /// SPOILER / STRIKETHROUGH / MONOSPACE — the pinned `TextStyle.java`
    /// enum minus the no-op `NONE`, which the official composer never emits
    /// and which would silently strip the range); start/length are validated
    /// non-negative by the u32 param types (UTF-16 code-unit offsets, the
    /// official BodyRange semantics). There is deliberately **no
    /// body-length bounds gate**: the pinned upstream carries no such check
    /// (`SendCommand.parseTextStyles` accepts any `\d+:\d+:STYLE` triple) and
    /// the official desktop sender clips ranges to the trimmed body at
    /// composition time (`quill/util.dom.ts getTextAndRangesFromOps`) — a
    /// connector-side rejection would fail sends the pinned face delivers,
    /// and connector-side clipping would hide a caller bug the official face
    /// leaves visible upstream.
    fn text_styles_to_upstream(
        &self,
        text_styles: Option<Vec<SendTextStyleParams>>,
    ) -> Result<Option<Vec<UpstreamSendTextStyle>>, ServiceError> {
        let Some(text_styles) = text_styles else {
            return Ok(None);
        };
        if text_styles.len() > MAX_SEND_TEXT_STYLES {
            return Err(ServiceError::Api(ApiError::new(
                "INVALID_REQUEST",
                "textStyle must contain at most 64 entries",
                false,
            )));
        }
        let mut upstream = Vec::with_capacity(text_styles.len());
        for entry in text_styles {
            let style = match entry.style.as_str() {
                "BOLD" | "ITALIC" | "SPOILER" | "STRIKETHROUGH" | "MONOSPACE" => entry.style,
                _ => {
                    return Err(ServiceError::Api(ApiError::new(
                        "INVALID_REQUEST",
                        "textStyle entry style must be one of BOLD, ITALIC, SPOILER, \
                         STRIKETHROUGH, MONOSPACE",
                        false,
                    )));
                }
            };
            upstream.push(UpstreamSendTextStyle {
                style,
                start: entry.start,
                length: entry.length,
            });
        }
        Ok((!upstream.is_empty()).then_some(upstream))
    }

    /// Send one attachment (optionally with a caption) — implementation-plan
    /// §4.12. Validation runs entirely before the pending row exists, so a
    /// rejected request leaves nothing behind and the same clientRequestId
    /// stays a fresh request. The base64 payload is size-verified against the
    /// declared `sizeBytes` and re-encoded as an RFC 2397 data URI: upstream
    /// decodes it itself (AttachmentHelper, pinned 0.14.7), uploads via CDN,
    /// and owns the transit temp file lifetime. Since contract revision
    /// 1.183 (§4.183) the connector ALSO stashes the plaintext into its
    /// governed attachments directory at dispatch time — the official
    /// outgoing local-retention semantics — best-effort, keyed by the
    /// descriptor's own id, evicted by the same governor passes as inbound
    /// media; the wire and the send outcome never depend on the stash. No
    /// caller-controlled path reaches upstream. The pending row carries the
    /// metadata-only descriptor (same wire shape as inbound, contract 1.15) so
    /// the host renders the outgoing attachment from its first tick.
    #[allow(clippy::too_many_arguments)]
    pub fn prepare_send_attachment(
        &self,
        account_id: &str,
        target: &AttachmentSendTarget<'_>,
        client_request_id: &str,
        data_base64: &str,
        size_bytes: u64,
        filename: Option<&str>,
        content_type: Option<&str>,
        text: Option<&str>,
        quote_message_id: Option<&str>,
        voice_note: bool,
        view_once: bool,
        blur_hash: Option<&str>,
        gif: bool,
    ) -> Result<PreparedSend, ServiceError> {
        let caption = validate_attachment_send_request(
            client_request_id,
            Some(data_base64),
            Some(size_bytes),
            filename,
            content_type,
            text,
            quote_message_id,
            voice_note,
            view_once,
            blur_hash,
        )?;
        if let Some(existing) = self
            .store
            .message_by_client_request(account_id, client_request_id)?
        {
            return Ok(PreparedSend::Existing(Box::new(existing)));
        }
        let account = self.resolve_account(account_id)?;
        let conversation = self.resolve_send_conversation(account_id, target)?;
        let data_uri =
            build_attachment_data_uri(data_base64, filename, content_type, voice_note, gif)?;
        // 契约 1.279（§4.263）：首发前把这条附件的原始 data URI 落进
        // outgoing_attachment_payloads——单附件面写 index 0（契约 1.280 起复合
        // 主键的固定槽位）。失败/unknown 保留、成功删除，于是刷新或重启之后仍能
        // 按同一个 clientRequestId 重试——payload 不再只活在桌面内存里。已有行
        // 保留原 payload（ON CONFLICT DO NOTHING），幂等重放不会把首发的数据
        // 覆盖成后来的请求。写失败即失败：不发送，否则修复会静默退化回
        // 「刷新即丢」。
        self.store.remember_outgoing_attachment_payload(
            account_id,
            &conversation.id,
            client_request_id,
            0,
            &data_uri,
            now_ms(),
        )?;
        // The pending row carries the same metadata-only descriptor the
        // renderer projects (contract 1.15 wire shape), so the desktop bubble
        // and conversation preview exist from the first pending tick instead
        // of collapsing into an invisible empty row. The voice flag rides the
        // descriptor (§4.30), so the sender's own bubble renders the voice UI
        // across restarts.
        let descriptor = NormalizedAttachment {
            locator: None,
            id: stable_hash_id(&[account_id, client_request_id, "attachment", "0"]),
            content_type: content_type.map(str::to_string),
            filename: filename.map(str::to_string),
            size: Some(size_bytes),
            width: None,
            height: None,
            is_voice_note: voice_note,
            caption: None,
            // §4.127: the caller-computed placeholder, shipped verbatim —
            // the sender's bubble renders it from the first pending tick.
            blur_hash: blur_hash.map(str::to_string),
            incremental_mac: None,
            chunk_size: None,
            is_borderless: false,
            // §4.147: the GIF marker rides the descriptor too, so the
            // sender's own bubble renders the GIF UI from the first pending
            // tick (the same statement the `;gif=true` URI parameter makes
            // upstream).
            is_gif: gif,
            // §4.149: the connector never fabricates the waveform pair — the
            // engine generates it upstream at send time (or ships neither on
            // failure); the desktop's own bubble gets it from the engine
            // transcript echo through the receive face.
            waveform: None,
            duration: None,
        };
        self.dispatch_send(
            &account,
            &conversation,
            caption,
            client_request_id,
            quote_message_id,
            None,
            None,
            None,
            Some(vec![json!(data_uri)]),
            vec![descriptor],
            view_once,
            None,
            None,
            None,
        )
    }

    /// Retry one definitively-failed outgoing attachment IN PLACE (contract
    /// revision 1.278, §4.262; payload persistence = 1.279, §4.263; the
    /// multi-attachment rebuild = 1.280, §4.264 — the §4.134 successor): the row
    /// addressed by its ORIGINAL clientRequestId is rearmed failed -> pending,
    /// its content faces take this request's values, and the SAME row id is
    /// re-dispatched, in the shape the original used (singular or plural). The
    /// engine re-uploads the bytes (a retry is a real send, never a replay of a
    /// stored pointer), and settlement lands on the row the bubble already
    /// renders — so the history keeps exactly one row per logical message: no
    /// new clientRequestId, no new row id, no delete-and-recreate.
    ///
    /// The bytes are optional (contract 1.279, §4.263). dataBase64 +
    /// sizeBytes may be omitted together; the connector then reads the
    /// original data URI group it persisted at the first send
    /// (outgoing_attachment_payloads, one row per attachment index), re-derives
    /// each payload and size, takes the descriptor faces (filename, content type,
    /// voice/gif/blur markers) from the row's own descriptors, and re-sends all
    /// of them. This is what makes a failed attachment — singular OR plural —
    /// retryable after a desktop refresh/restart, when the in-memory payload is
    /// gone. A caller that supplies bytes still wins for a SINGLE-attachment row:
    /// the request is validated through the same §4.12 corpus as the first send
    /// and the persisted index-0 row is rewritten with the caller's bytes (so the
    /// next refresh can retry again). A plural row refuses caller bytes
    /// (RETRY_NOT_ALLOWED) because one call cannot restate every entry's byte set;
    /// it retries ids-only from its persisted group. A missing or incomplete
    /// payload group answers RETRY_NOT_ALLOWED — for the singular face with the
    /// explicit "retry with dataBase64+sizeBytes" wording — and the row itself is
    /// untouched.
    ///
    /// Guards, in the §4.172 order (idempotent replay before rebuild):
    /// - no row -> MESSAGE_NOT_FOUND (the original request never arrived);
    /// - another conversation, or an incoming/system row -> INVALID_REQUEST;
    /// - a completed original (sent/delivered/read) -> the persisted terminal
    ///   row, untouched and never re-dispatched;
    /// - unknown -> RETRY_OUTCOME_UNKNOWN (its wire outcome was never settled,
    ///   so a blind resend could double-deliver — §4.172's red line);
    /// - pending -> RETRY_IN_FLIGHT;
    /// - any other state -> RETRY_NOT_ALLOWED (messages.retryText owns text rows;
    ///   the state is judged before the content face, so a row that already
    ///   settled, or whose retry is in flight, is answered by its state and
    ///   never by a content guess);
    /// - a definitively failed row with no attachment descriptor left ->
    ///   RETRY_NOT_ALLOWED with the "no descriptors" wording (never the text-send
    ///   wording: the row is a failed attachment whose descriptor face is gone,
    ///   and retryText refuses it for the same reason);
    /// - caller-supplied bytes on a plural row -> RETRY_NOT_ALLOWED;
    /// - a plural row whose persisted payload group is not exactly one row per
    ///   descriptor -> RETRY_NOT_ALLOWED (a partial group cannot be rebuilt).
    #[allow(clippy::too_many_arguments)]
    pub fn prepare_retry_attachment(
        &self,
        account_id: &str,
        target: &AttachmentSendTarget<'_>,
        client_request_id: &str,
        data_base64: Option<&str>,
        size_bytes: Option<u64>,
        filename: Option<&str>,
        content_type: Option<&str>,
        text: Option<&str>,
        quote_message_id: Option<&str>,
        voice_note: bool,
        view_once: bool,
        blur_hash: Option<&str>,
        gif: bool,
    ) -> Result<PreparedSend, ServiceError> {
        // A caller-supplied payload/size mismatch is rejected before any store
        // read (the first send's own rejection class); the remaining faces are
        // checked once the persisted payload has supplied whatever the caller
        // omitted — nothing is written before that check passes.
        validate_attachment_payload_pair(data_base64, size_bytes)?;
        let account = self.resolve_account(account_id)?;
        let conversation = self.resolve_send_conversation(account_id, target)?;
        let row = self
            .store
            .message_by_client_request(account_id, client_request_id)?
            .ok_or(ServiceError::Store(StoreError::MessageNotFound))?;
        if row.conversation_id != conversation.id {
            return Err(ServiceError::Api(ApiError::new(
                "INVALID_REQUEST",
                "clientRequestId does not belong to this conversation",
                false,
            )));
        }
        if row.direction != "outgoing" {
            return Err(ServiceError::Api(ApiError::new(
                "INVALID_REQUEST",
                "only outgoing messages can be retried",
                false,
            )));
        }
        // §4.172 replay-first: a completed original answers its terminal row
        // projection, untouched and never re-dispatched — the same face the
        // text retry serves, so a desktop that retries a bubble the wire
        // already settled converges instead of double-sending.
        if matches!(row.status, "sent" | "delivered" | "read") {
            let mut replay = row.clone();
            self.store
                .attach_reactions(account_id, std::slice::from_mut(&mut replay))?;
            self.store
                .attach_outgoing_quotes(account_id, std::slice::from_mut(&mut replay))?;
            return Ok(PreparedSend::Existing(Box::new(replay)));
        }
        if row.status == "unknown" {
            return Err(ServiceError::Api(ApiError::new(
                "RETRY_OUTCOME_UNKNOWN",
                "the original send outcome is still unknown; resend is refused to avoid double delivery",
                false,
            )));
        }
        if row.status == "pending" {
            return Err(ServiceError::Api(ApiError::new(
                "RETRY_IN_FLIGHT",
                "retry already in flight",
                false,
            )));
        }
        if row.status != "failed" {
            return Err(ServiceError::Api(ApiError::new(
                "RETRY_NOT_ALLOWED",
                "only a definitively failed send can be retried",
                false,
            )));
        }
        // The status guards settle the row's state before the content face is
        // judged: a failed row that lost its descriptors is still a failed
        // ATTACHMENT (its attachment face was erased, or it predates the
        // persisted descriptor), and answering "this is a text send" would be a
        // lie about a row retryText refuses for the very same reason — there is
        // nothing left to rebuild. Only a definitively failed row reaches here,
        // so this is the honest "no descriptor" answer.
        if row.attachments.is_empty() {
            return Err(ServiceError::Api(ApiError::new(
                "RETRY_NOT_ALLOWED",
                "the clientRequestId no longer carries attachment descriptors; this row cannot be rebuilt as an attachment",
                false,
            )));
        }
        // §4.264: caller-supplied bytes serve the singular form only — a plural
        // message carries one byte set per entry, and one call cannot restate
        // them all. A multi-attachment row is retried from its own persisted
        // payload group (ids-only, still possible after a refresh). The refusal
        // sits after the status guards, so the failed row stays exactly as it
        // was and remains retryable ids-only.
        if row.attachments.len() > 1 && data_base64.is_some() {
            return Err(ServiceError::Api(ApiError::new(
                "RETRY_NOT_ALLOWED",
                "a multi-attachment send is retried from its persisted payloads; omit dataBase64+sizeBytes",
                false,
            )));
        }
        // §4.263 + §4.264: caller bytes win; otherwise the persisted payload
        // group is the resend source. The row's own descriptor is the
        // authoritative fallback for every face the caller did not restate, so a
        // sparse refresh retry preserves the original filename/contentType/voice/
        // gif/blurHash instead of inventing builder defaults. The singular row
        // reads index 0; a plural row reads the whole group by ascending index and
        // refuses when the group is not exactly one entry per descriptor — a
        // partial group is not a rebuildable generation.
        let resolved: Vec<ResolvedAttachmentPayload> = match data_base64.zip(size_bytes) {
            Some((data_base64, size_bytes)) => {
                let descriptor = row.attachments.first();
                vec![ResolvedAttachmentPayload {
                    data_base64: data_base64.to_string(),
                    size_bytes,
                    content_type: content_type
                        .map(str::to_string)
                        .or_else(|| descriptor.and_then(|entry| entry.content_type.clone())),
                    filename: filename
                        .map(str::to_string)
                        .or_else(|| descriptor.and_then(|entry| entry.filename.clone())),
                    voice: voice_note || descriptor.is_some_and(|entry| entry.is_voice_note),
                    gif: gif || descriptor.is_some_and(|entry| entry.is_gif),
                    blur_hash: blur_hash
                        .map(str::to_string)
                        .or_else(|| descriptor.and_then(|entry| entry.blur_hash.clone())),
                }]
            }
            None => {
                let stored = self
                    .store
                    .outgoing_attachment_payloads(account_id, client_request_id)?;
                let complete = stored.len() == row.attachments.len()
                    && stored
                        .iter()
                        .enumerate()
                        .all(|(index, (stored_index, _))| *stored_index == index as u32);
                if !complete {
                    return Err(ServiceError::Api(ApiError::new(
                        "RETRY_NOT_ALLOWED",
                        if row.attachments.len() > 1 {
                            "the original attachment payloads are no longer available; this multi-attachment row cannot be retried"
                        } else {
                            "the original attachment payload is no longer available; retry with dataBase64+sizeBytes"
                        },
                        false,
                    )));
                }
                let mut resolved = Vec::with_capacity(stored.len());
                for ((_, data_uri), descriptor) in stored.iter().zip(row.attachments.iter()) {
                    let parsed = parse_attachment_data_uri(data_uri)?;
                    // Descriptor faces come from the row, never from the URI: the
                    // URI's mime/filename are builder defaults, and a field the
                    // first send genuinely lacked must not be conjured back.
                    resolved.push(ResolvedAttachmentPayload {
                        data_base64: parsed.data_base64,
                        size_bytes: parsed.size_bytes,
                        content_type: descriptor.content_type.clone(),
                        filename: descriptor.filename.clone(),
                        voice: descriptor.is_voice_note,
                        gif: descriptor.is_gif,
                        blur_hash: descriptor.blur_hash.clone(),
                    });
                }
                resolved
            }
        };
        // ids-only retry restores every face the row already owns: caption,
        // quote and the view-once marker are part of the original message, not
        // caller-restated builder defaults. Caller values still win when given.
        let preserved_text = text.or_else(|| row.text.as_deref().filter(|value| !value.is_empty()));
        let preserved_quote = quote_message_id.or(row.quote_message_id.as_deref());
        let preserved_view_once = view_once || row.rich.as_ref().is_some_and(|rich| rich.view_once);
        // A stored voice/gif marker or content type can complete a composition
        // the caller's sparse request did not spell out: re-run the metadata
        // corpus against each resolved entry before anything is written.
        for entry in &resolved {
            validate_attachment_send_metadata(
                client_request_id,
                entry.filename.as_deref(),
                entry.content_type.as_deref(),
                preserved_text,
                preserved_quote,
                entry.voice,
                preserved_view_once,
                entry.blur_hash.as_deref(),
            )?;
        }
        let caption = preserved_text.unwrap_or_default();
        // The descriptor id is the first attempt's own (§4.12 stable-id
        // derivation over the same account + clientRequestId + array position),
        // so the retry replaces the bytes behind the SAME descriptors: §4.183's
        // local stash lands on the same files, and the sender's bubble keys never
        // change.
        let mut data_uris = Vec::with_capacity(resolved.len());
        let mut descriptors = Vec::with_capacity(resolved.len());
        let mut payloads = Vec::with_capacity(resolved.len());
        for (index, entry) in resolved.iter().enumerate() {
            let data_uri = build_attachment_data_uri(
                &entry.data_base64,
                entry.filename.as_deref(),
                entry.content_type.as_deref(),
                entry.voice,
                entry.gif,
            )?;
            payloads.push((index as u32, data_uri.clone()));
            data_uris.push(json!(data_uri));
            descriptors.push(NormalizedAttachment {
                locator: None,
                id: stable_hash_id(&[
                    account_id,
                    client_request_id,
                    "attachment",
                    &index.to_string(),
                ]),
                content_type: entry.content_type.clone(),
                filename: entry.filename.clone(),
                size: Some(entry.size_bytes),
                width: None,
                height: None,
                is_voice_note: entry.voice,
                caption: None,
                blur_hash: entry.blur_hash.clone(),
                incremental_mac: None,
                chunk_size: None,
                is_borderless: false,
                is_gif: entry.gif,
                waveform: None,
                duration: None,
            });
        }
        // §4.263 + §4.264: the payload rows follow the bytes actually re-sent.
        // Caller bytes overwrite index 0; the ids-only arm writes the rebuilt
        // group back (refreshing updated_at, so a long-lived failed row keeps its
        // resend source through the retention window). Write failure aborts the
        // retry before the row is rearmed.
        let payload_refs: Vec<(u32, &str)> = payloads
            .iter()
            .map(|(index, data_uri)| (*index, data_uri.as_str()))
            .collect();
        self.store.update_outgoing_attachment_payloads(
            account_id,
            &conversation.id,
            client_request_id,
            &payload_refs,
            now_ms(),
        )?;
        self.dispatch_send(
            &account,
            &conversation,
            caption,
            client_request_id,
            preserved_quote,
            None,
            None,
            None,
            Some(data_uris),
            descriptors,
            preserved_view_once,
            None,
            None,
            Some(&row),
        )
    }

    /// Send one message carrying several attachments (contract revision
    /// 1.66, §4.59) — the official forward face: a forwarded multi-
    /// attachment message is one upstream message whose array-typed
    /// `attachments` parameter carries every entry's data URI (the engine
    /// has always accepted the array; the singular §4.12 entry point was the
    /// only one-element gate). Validation runs entirely before the pending
    /// row exists. Shape rules, all deterministic INVALID_REQUEST: 1..=32
    /// entries (the engine's own per-message ceiling, `MAX_SEND_ATTACHMENTS`);
    /// the entries' combined raw size stays within the §4.12 100 MiB budget
    /// so the whole request still fits one host frame; voiceNote/viewOnce are
    /// rejected on this form (a voice note is always a single-attachment
    /// message and view-once media is a single unadorned medium — neither
    /// official face produces a multi-attachment message). Per-entry
    /// validation reuses the §4.12 family verbatim (payload, filename,
    /// content type); the caption and quote are message-level and shared.
    /// Settlement is the §4.12 chain unchanged: one pending row carrying one
    /// descriptor per entry, then the shared `dispatch_send` completion, so
    /// the desktop renders every outgoing attachment from the first tick;
    /// §4.183 stashes every entry's bytes the same way (one file per
    /// descriptor id).
    pub fn prepare_send_attachment_multi(
        &self,
        account_id: &str,
        target: &AttachmentSendTarget<'_>,
        client_request_id: &str,
        entries: &[MessagesSendAttachmentEntry],
        text: Option<&str>,
        quote_message_id: Option<&str>,
    ) -> Result<PreparedSend, ServiceError> {
        if entries.is_empty() {
            return Err(ServiceError::Api(ApiError::new(
                "INVALID_REQUEST",
                "attachments must contain at least one entry",
                false,
            )));
        }
        if entries.len() > MAX_SEND_ATTACHMENTS {
            return Err(ServiceError::Api(ApiError::new(
                "INVALID_REQUEST",
                "attachments must contain at most 32 entries",
                false,
            )));
        }
        // The combined raw budget equals the singular §4.12 ceiling: one
        // multi-attachment request is still one host frame (base64 expansion
        // plus JSON envelope under the 160 MiB frame limit), and no entry can
        // exceed the budget the singular form already proves fits.
        let mut total_bytes = 0usize;
        for entry in entries {
            total_bytes =
                total_bytes.saturating_add(usize::try_from(entry.size_bytes).unwrap_or(usize::MAX));
            if total_bytes > MAX_ATTACHMENT_BYTES {
                return Err(ServiceError::Api(ApiError::new(
                    "INVALID_REQUEST",
                    "combined attachment payload exceeds the 100 MiB message budget",
                    false,
                )));
            }
            validate_attachment_send_payload(&entry.data_base64, entry.size_bytes)?;
            validate_attachment_descriptor(entry.filename.as_deref(), "filename")?;
            validate_attachment_content_type(entry.content_type.as_deref())?;
            // §4.127: the plural face carries the blur placeholder per entry.
            validate_blur_hash(entry.blur_hash.as_deref())?;
        }
        if let Some(caption) = text
            && !caption.is_empty()
        {
            validate_text(caption)?;
        }
        validate_opaque_id(client_request_id, "clientRequestId")?;
        if let Some(quote) = quote_message_id {
            validate_opaque_id(quote, "quoteMessageId")?;
        }
        if let Some(existing) = self
            .store
            .message_by_client_request(account_id, client_request_id)?
        {
            return Ok(PreparedSend::Existing(Box::new(existing)));
        }
        let account = self.resolve_account(account_id)?;
        let conversation = self.resolve_send_conversation(account_id, target)?;
        let mut data_uris = Vec::with_capacity(entries.len());
        let mut descriptors = Vec::with_capacity(entries.len());
        // 契约 1.280（§4.264）：多附件消息的每个条目各存一份原始 data URI，
        // index 就是它在 attachments 数组里的位置（0..n-1）。整组在一个事务里
        // 落库，ids-only 重试才能按 index 重建出完整的一代字节。
        let mut payloads = Vec::with_capacity(entries.len());
        for (index, entry) in entries.iter().enumerate() {
            let data_uri = build_attachment_data_uri(
                &entry.data_base64,
                entry.filename.as_deref(),
                entry.content_type.as_deref(),
                false,
                entry.gif,
            )?;
            payloads.push((index as u32, data_uri.clone()));
            data_uris.push(json!(data_uri));
            descriptors.push(NormalizedAttachment {
                locator: None,
                id: stable_hash_id(&[
                    account_id,
                    client_request_id,
                    "attachment",
                    &index.to_string(),
                ]),
                content_type: entry.content_type.clone(),
                filename: entry.filename.clone(),
                size: Some(entry.size_bytes),
                width: None,
                height: None,
                is_voice_note: false,
                caption: None,
                // §4.127: per-entry placeholder, same posture as the
                // singular face.
                blur_hash: entry.blur_hash.clone(),
                incremental_mac: None,
                chunk_size: None,
                is_borderless: false,
                // §4.147: the per-entry GIF marker, same statement posture.
                is_gif: entry.gif,
                // §4.149: never fabricated connector-side (see the singular
                // face) — the engine's transcript echo carries the pair.
                waveform: None,
                duration: None,
            });
        }
        let payload_refs: Vec<(u32, &str)> = payloads
            .iter()
            .map(|(index, data_uri)| (*index, data_uri.as_str()))
            .collect();
        // 写失败即不发送（与单附件面同一纪律）：没有 payload 的多附件失败行
        // 在刷新后无法 ids-only 重试，而它也没有单份 bytes 可以补。
        self.store.remember_outgoing_attachment_payloads(
            account_id,
            &conversation.id,
            client_request_id,
            &payload_refs,
            now_ms(),
        )?;
        self.dispatch_send(
            &account,
            &conversation,
            text.unwrap_or_default(),
            client_request_id,
            quote_message_id,
            None,
            None,
            None,
            Some(data_uris),
            descriptors,
            false,
            None,
            None,
            None,
        )
    }

    /// Shared §4.12 addressing resolution for body-carrying and sticker
    /// sends alike: a conversation id resolves the stored row; kind+peerKey
    /// progressive-fills a skeleton the same way (contacts.list reports
    /// 'contact', conversations use 'direct' — both accepted).
    fn resolve_send_conversation(
        &self,
        account_id: &str,
        target: &AttachmentSendTarget<'_>,
    ) -> Result<ConversationRow, ServiceError> {
        match target {
            AttachmentSendTarget::Conversation(conversation_id) => {
                self.resolve_conversation(account_id, conversation_id)
            }
            AttachmentSendTarget::Peer(peer) => {
                let kind = match peer.kind {
                    "direct" | "contact" => "direct",
                    "group" => "group",
                    _ => {
                        return Err(ServiceError::Api(ApiError::new(
                            "INVALID_REQUEST",
                            "kind must be 'contact', 'direct', or 'group'",
                            false,
                        )));
                    }
                };
                validate_opaque_id(peer.peer_key, "peerKey")?;
                // 契约 1.269（§4.253 · 批 Z14）：同文本发送面的 direct 键词
                // 形闸（群键混入 direct 语义 fail-closed，防怪 direct 行）。
                if kind == "direct"
                    && !crate::engine::is_uuid_shaped(peer.peer_key)
                    && !peer.peer_key.starts_with('+')
                    && !peer.peer_key.chars().all(|c| c.is_ascii_digit())
                {
                    return Err(ServiceError::Api(ApiError::new(
                        "INVALID_REQUEST",
                        "direct peerKey must be a ServiceId (ACI/PNI) or a phone number — group keys belong to kind=group",
                        false,
                    )));
                }
                let peer_title = peer
                    .peer_title
                    .map(str::trim)
                    .filter(|title| !title.is_empty())
                    .map(|title| title.chars().take(64).collect::<String>());
                let title = peer_title.unwrap_or_else(|| {
                    if kind == "group" {
                        "group".to_string()
                    } else {
                        mask_address(peer.peer_key)
                    }
                });
                Ok(self
                    .store
                    .ensure_conversation(account_id, kind, peer.peer_key, &title)?)
            }
        }
    }

    /// messages.sendSticker (contract revision 1.35, §4.31; quote face 1.37,
    /// §4.35): §4.12 settlement discipline with a body-less upstream `send`
    /// carrying the `sticker` object — pending row (sticker metadata + image
    /// descriptor) before the upstream call, then the shared
    /// `dispatch_prepared` completion. Bounds failures reject before the
    /// pending row exists. The optional quote resolves through the same
    /// ladder as `dispatch_send` — after the idempotency short-circuit and
    /// addressing resolution, before the pending row is inserted, so a
    /// rejected quote leaves nothing behind while a replay keeps returning
    /// the existing row without re-resolving.
    #[allow(clippy::too_many_arguments)]
    pub fn prepare_send_sticker(
        &self,
        account_id: &str,
        target: &AttachmentSendTarget<'_>,
        client_request_id: &str,
        pack_id: &str,
        pack_key: &str,
        sticker_id: u32,
        emoji: Option<&str>,
        image: &MessagesSendStickerImage,
        quote_message_id: Option<&str>,
    ) -> Result<PreparedSend, ServiceError> {
        validate_sticker_pack_id(pack_id)?;
        validate_sticker_pack_key(pack_key)?;
        validate_attachment_send_payload(&image.data_base64, image.size_bytes)?;
        validate_attachment_content_type(Some(&image.content_type))?;
        // The official client sniffs image MIME (falling back to image/webp)
        // and refuses video/text; the connector refuses them deterministically
        // so a rejected sticker never leaves a pending row behind.
        if !image.content_type.starts_with("image/") {
            return Err(ServiceError::Api(ApiError::new(
                "INVALID_REQUEST",
                "sticker image contentType must be image/*",
                false,
            )));
        }
        if let Some(emoji) = emoji {
            let count = emoji.chars().count();
            if count == 0 || count > MAX_STICKER_EMOJI_CHARS {
                return Err(ServiceError::Api(ApiError::new(
                    "INVALID_REQUEST",
                    "emoji must contain between 1 and 32 characters",
                    false,
                )));
            }
        }
        validate_opaque_id(client_request_id, "clientRequestId")?;
        if let Some(existing) = self
            .store
            .message_by_client_request(account_id, client_request_id)?
        {
            return Ok(PreparedSend::Existing(Box::new(existing)));
        }
        let account = self.resolve_account(account_id)?;
        let conversation = self.resolve_send_conversation(account_id, target)?;
        // Quote resolution is part of send validation and runs before the
        // pending row exists (§4.35): a rejected quote leaves nothing behind,
        // so the same clientRequestId stays a fresh (re-validated) request.
        let quote = quote_message_id
            .map(|id| self.resolve_quote(&account, &conversation, id))
            .transpose()?;
        // §4.147: the sticker image rides the single-item upload face the
        // engine keeps out of the shared attachment path — the official
        // sticker pointer has no GIF bit, so this URI never carries the flag.
        let data_uri = build_attachment_data_uri(
            &image.data_base64,
            None,
            Some(&image.content_type),
            false,
            false,
        )?;
        // The sent row's descriptor records the sticker image (metadata only)
        // and the row itself records the pack identity, so the sender's bubble
        // renders as a sticker across restarts (§4.31).
        let descriptor = NormalizedAttachment {
            locator: None,
            id: stable_hash_id(&[account_id, client_request_id, "sticker", "0"]),
            content_type: Some(image.content_type.clone()),
            filename: None,
            size: Some(image.size_bytes),
            width: image.width,
            height: image.height,
            is_voice_note: false,
            caption: None,
            blur_hash: None,
            incremental_mac: None,
            chunk_size: None,
            is_borderless: false,
            is_gif: false,
            waveform: None,
            duration: None,
        };
        let sticker = crate::engine::NormalizedSticker {
            pack_id: pack_id.to_string(),
            pack_key: pack_key.to_string(),
            sticker_id,
            emoji: emoji.map(str::to_string),
        };
        let pending_id = stable_hash_id(&[
            account_id,
            conversation.id.as_str(),
            "outgoing",
            client_request_id,
        ]);
        let pending = MessageRecord {
            is_erased: false,
            delete_failed: false,
            required_protocol_version: None,
            author_aci: None,
            id: pending_id.clone(),
            account_id: account_id.to_string(),
            conversation_id: conversation.id.clone(),
            direction: "outgoing",
            sender_id: account_id.to_string(),
            sender_name: None,
            mentions_self: false,
            sent_at: now_ms(),
            received_at: None,
            text: None,
            text_bytes: None,
            text_truncated: false,
            text_retrievable: false,
            status: "pending",
            client_request_id: Some(client_request_id.to_string()),
            quote_message_id: quote_message_id.map(str::to_string),
            quote_snapshot: None,
            quote: None,
            attachments: vec![descriptor],
            edited_at: None,
            rich: None,
            reactions: Vec::new(),
            edits: Vec::new(),
            delivered_at: None,
            read_at: None,
            viewed_at: None,
            send_outcomes: None,
            admin_deleted: false,
            sticker: Some(sticker),
            expire_seconds: None,
            expire_start_at: None,
            server_guid: None,
            server_timestamp: None,
            is_story: false,
            story_message: None,
        };
        let inserted = self
            .store
            .insert_message(&pending, Some(client_request_id), None, false)?;
        if !inserted
            && let Some(existing) = self
                .store
                .message_by_client_request(account_id, client_request_id)?
        {
            return Ok(PreparedSend::Existing(Box::new(existing)));
        }
        // Upstream shape (official `sendStickerMessage`): the sticker object
        // with the image re-encoded as a data URI, plus the shared upstream
        // target — and deliberately no `message` or `attachments` key, the
        // mutual exclusivity the official face enforces.
        let mut sticker_object = json!({
            "packId": pack_id,
            "packKey": pack_key,
            "stickerId": sticker_id,
            "image": data_uri,
        });
        if let Some(emoji) = emoji {
            sticker_object["emoji"] = json!(emoji);
        }
        if let Some(width) = image.width {
            sticker_object["width"] = json!(width);
        }
        if let Some(height) = image.height {
            sticker_object["height"] = json!(height);
        }
        let mut params = json!({
            "account": account.signal_account,
            "sticker": sticker_object,
        });
        set_upstream_target(&mut params, &conversation);
        // The quote keys ride the send top level beside the sticker object —
        // the quote belongs to the send, not to the sticker (§4.35, the same
        // wire keys the text face uses).
        if let Some((quote_timestamp, quote_author)) = quote {
            params["quoteTimestamp"] = json!(quote_timestamp);
            params["quoteAuthor"] = json!(quote_author);
        }
        Ok(PreparedSend::Dispatch {
            pending_id,
            account_id: account_id.to_string(),
            conversation_id: conversation.id.clone(),
            params,
            pending_sent_at: pending.sent_at,
        })
    }

    #[allow(clippy::too_many_arguments)]
    fn dispatch_send(
        &self,
        account: &AccountRow,
        conversation: &ConversationRow,
        text: &str,
        client_request_id: &str,
        quote_message_id: Option<&str>,
        link_preview: Option<UpstreamSendPreview>,
        mentions: Option<Vec<UpstreamSendMention>>,
        text_styles: Option<Vec<UpstreamSendTextStyle>>,
        attachments: Option<Vec<Value>>,
        attachment_descriptors: Vec<NormalizedAttachment>,
        view_once: bool,
        story_reply_author: Option<String>,
        story_reply_timestamp: Option<Value>,
        retry_row: Option<&MessageRecord>,
    ) -> Result<PreparedSend, ServiceError> {
        let account_id = account.id.as_str();
        let conversation_id = conversation.id.as_str();
        // Quote resolution is part of send validation and runs before the
        // pending row exists: a rejected quote leaves nothing behind, so the
        // same clientRequestId stays a fresh (re-validated) request.
        let quote = quote_message_id
            .map(|id| self.resolve_quote(account, conversation, id))
            .transpose()?;
        // §4.262: an in-place retry addresses the ORIGINAL row by its own id —
        // the deterministic first-send id is the same value by construction
        // (same account, conversation and clientRequestId), so this branch
        // only states which write follows, never a second identity.
        let pending_id = match retry_row {
            Some(row) => row.id.clone(),
            None => stable_hash_id(&[account_id, conversation_id, "outgoing", client_request_id]),
        };
        // §4.126: the rich body face (preview card, §4.62 style ranges, §4.36
        // view-once marker) is built once and shared by both write arms.
        let rich = {
            let previews: Vec<crate::engine::NormalizedPreview> = link_preview
                .iter()
                .map(|card| crate::engine::NormalizedPreview {
                    url: card.url.clone(),
                    title: Some(card.title.clone()),
                    description: card.description.clone(),
                    date: card.date,
                    image: None,
                })
                .collect();
            (view_once || text_styles.is_some() || !previews.is_empty()).then(|| {
                crate::engine::NormalizedRich {
                    previews,
                    view_once,
                    text_styles: text_styles
                        .as_deref()
                        .unwrap_or(&[])
                        .iter()
                        .map(|style| crate::engine::NormalizedTextStyle {
                            style: style.style.clone(),
                            start: style.start,
                            length: style.length,
                        })
                        .collect(),
                    ..crate::engine::NormalizedRich::default()
                }
            })
        };
        let pending = MessageRecord {
            is_erased: false,
            delete_failed: false,
            required_protocol_version: None,
            author_aci: None,
            id: pending_id.clone(),
            account_id: account_id.to_string(),
            conversation_id: conversation_id.to_string(),
            direction: "outgoing",
            sender_id: account_id.to_string(),
            sender_name: None,
            mentions_self: false,
            sent_at: now_ms(),
            received_at: None,
            text: Some(text.to_string()),
            text_bytes: Some(text.len() as u32),
            text_truncated: false,
            text_retrievable: true,
            status: "pending",
            client_request_id: Some(client_request_id.to_string()),
            quote_message_id: quote_message_id.map(str::to_string),
            quote_snapshot: None,
            quote: None,
            attachments: attachment_descriptors,
            edited_at: None,
            // §4.36: a view-once send persists the marker on its own pending
            // row, so the sender's bubble renders the view-once UI across
            // restarts; every other send stays a plain row (None).
            // §4.62: a styled text send persists its ranges the same way —
            // the sender's bubble keeps its own formatting across restarts
            // (the official sender echo renders bodyRanges). Mentions stay
            // unpersisted (the 1.34 shape): a styled send carries both, the
            // retry rebuilds neither (documented deviation, §4.29 precedent).
            // §4.126: a preview-bearing send persists the card (url/title/
            // description/date, never the image bytes — the data URI is
            // transit-only material), so the optimistic row renders the same
            // stamp the eventual mirror carries and the retry rebuild
            // restores the card.
            rich: rich.clone(),
            reactions: Vec::new(),
            edits: Vec::new(),
            delivered_at: None,
            read_at: None,
            viewed_at: None,
            send_outcomes: None,
            admin_deleted: false,
            sticker: None,
            expire_seconds: None,
            expire_start_at: None,
            server_guid: None,
            server_timestamp: None,
            is_story: false,
            story_message: None,
        };
        // Preview mirrors the visible row: the caption when present, else the
        // attachment filename — never an empty string for an attachment send.
        let preview = (!text.is_empty()).then(|| text.to_string()).or_else(|| {
            pending
                .attachments
                .iter()
                .find_map(|a| a.filename.as_deref().filter(|f| !f.is_empty()))
                .map(str::to_string)
        });
        match retry_row {
            // §4.262: the in-place retry writes the ORIGINAL row — one
            // guarded \`failed -> pending\` transition carrying this request's
            // faces, never an insert. The store's status guard is the
            // concurrency face: a row a concurrent retry already rearmed (or
            // that settled while this request was travelling) answers
            // RETRY_IN_FLIGHT instead of arming a second dispatch of the same
            // row, so one row can never leave as two upstream sends.
            Some(row) => {
                let (_, changed) = self
                    .store
                    .rearm_failed_attachment_retry(
                        &row.id,
                        text,
                        pending.quote_message_id.as_deref(),
                        &pending.attachments,
                        rich.as_ref(),
                    )?
                    .ok_or(ServiceError::Store(StoreError::MessageNotFound))?;
                if !changed {
                    return Err(ServiceError::Api(ApiError::new(
                        "RETRY_IN_FLIGHT",
                        "retry already in flight",
                        false,
                    )));
                }
            }
            None => {
                let inserted = self.store.insert_message(
                    &pending,
                    Some(client_request_id),
                    preview.as_deref(),
                    false,
                )?;
                if !inserted
                    && let Some(existing) = self
                        .store
                        .message_by_client_request(account_id, client_request_id)?
                {
                    return Ok(PreparedSend::Existing(Box::new(existing)));
                }
            }
        }
        // §4.183: the official outgoing-attachment local retention — while
        // the caller's bytes are still in hand as data URIs, stash them
        // into the governed attachments directory under each descriptor's
        // own id, so the sender's own bubble (and any later download/open
        // of this outgoing row) reads local bytes without a transit
        // pointer. Best-effort: a stash failure logs by class and changes
        // nothing about the send; without the media ingest face there is
        // no local reader, so nothing is written.
        if let (Some(media), Some(attachments)) = (self.media.as_ref(), attachments.as_deref())
            && !attachments.is_empty()
        {
            for (descriptor, data_uri) in pending.attachments.iter().zip(attachments.iter()) {
                if let Some(data_uri) = data_uri.as_str()
                    && let Err(kind) =
                        media.stash_outbound_attachment(account_id, &descriptor.id, data_uri)
                {
                    tracing::warn!(
                        kind = %kind,
                        "outbound attachment stash failed; the send proceeds without local bytes"
                    );
                }
            }
        }

        let params = Self::upstream_text_send_params(
            &account.signal_account,
            text,
            link_preview.as_ref(),
            mentions.as_deref(),
            text_styles.as_deref(),
            attachments,
            quote,
            conversation,
            view_once,
            story_reply_author,
            story_reply_timestamp,
        );
        Ok(PreparedSend::Dispatch {
            pending_id,
            account_id: account_id.to_string(),
            conversation_id: conversation_id.to_string(),
            params: {
                let mut params = params;
                params["dispatchId"] = json!(client_request_id);
                params
            },
            // §4.262: a retry keeps the ORIGINAL row's stamp as the fallback
            // settlement time — the message's position in the timeline is the
            // original send's, not the retry's.
            pending_sent_at: retry_row.map_or(pending.sent_at, |row| row.sent_at),
        })
    }

    /// stickerPacks.getManifest (contract revision 1.36, §4.32): bounds
    /// validation, then the engine call is composed by the supervisor — the
    /// service contributes no state and returns nothing persistent. The
    /// packId/packKey rules are the browse-face shapes (32-hex id, base64
    /// key decoding to exactly 32 bytes), stricter than the 1.35 send
    /// projection on purpose (§4.32).
    pub fn prepare_sticker_pack_manifest(
        &self,
        params: &StickerPackManifestParams,
    ) -> Result<(), ServiceError> {
        validate_sticker_browse_pack_id(&params.pack_id)?;
        validate_sticker_browse_pack_key(&params.pack_key)?;
        Ok(())
    }

    /// stickerPacks.getImage (contract revision 1.36, §4.32): same pack
    /// identity bounds plus the u32 stickerId — the u32 type already fails
    /// non-integer/out-of-range values at params deserialization, so the
    /// prepare step adds no second check.
    pub fn prepare_sticker_pack_image(
        &self,
        params: &StickerPackImageParams,
    ) -> Result<(), ServiceError> {
        validate_sticker_browse_pack_id(&params.pack_id)?;
        validate_sticker_browse_pack_key(&params.pack_key)?;
        Ok(())
    }

    /// conversations.getPinned (contract revision 1.36, §4.33): account
    /// bounds and existence — the pinned list itself lives upstream, the
    /// service reads nothing locally (no persistence on this face).
    pub fn prepare_conversations_get_pinned(
        &self,
        account_id: &str,
    ) -> Result<Value, ServiceError> {
        validate_opaque_id(account_id, "accountId")?;
        let account = self.resolve_account(account_id)?;
        Ok(json!({ "account": account.signal_account }))
    }

    /// conversations.setPinned (contract revision 1.36, §4.33): bounds and
    /// resolution only — the conversation id resolves through the shared
    /// ladder (account, then conversation; CONVERSATION_NOT_FOUND before
    /// any upstream call) and the kind enum is validated here, so the
    /// upstream call carries a resolved reference and a legal kind. No
    /// local row is written: the cloud record is the whole state.
    pub fn prepare_conversations_set_pinned(
        &self,
        account_id: &str,
        conversation_id: &str,
        kind: &str,
        pinned: bool,
    ) -> Result<Value, ServiceError> {
        validate_opaque_id(account_id, "accountId")?;
        if conversation_id.is_empty()
            || conversation_id.chars().count() > MAX_PIN_CONVERSATION_ID_CHARS
        {
            return Err(ServiceError::Api(ApiError::new(
                "INVALID_REQUEST",
                "conversationId must contain between 1 and 256 characters",
                false,
            )));
        }
        validate_pinned_kind(kind)?;
        let account = self.resolve_account(account_id)?;
        // Resolution uses the plain ladder: only conversations already
        // materialized locally resolve. A pinned reference for a conversation
        // this connector has never seen is the engine's CONVERSATION_
        // NOT_RESOLVED answer, not a local guess (§4.33). The upstream key is
        // `conversationId` carrying the resolved upstream conversation
        // reference (peer key, the identity every other group/direct
        // addressing projects), never the host's opaque local id.
        let conversation = self.resolve_conversation(account_id, conversation_id)?;
        Ok(json!({
            "account": account.signal_account,
            "conversationId": conversation.peer_key,
            "kind": kind,
            "pinned": pinned,
        }))
    }

    /// conversations.setExpireTimer (contract revision 1.42, §4.41; group
    /// route re-cut by contract revision 1.45, §4.44; kt-engine gate lifted
    /// by the 2026-10-06 dated note): bounds, resolution, and the upstream
    /// payload under the service lock. A direct conversation routes to the
    /// engine's `setExpirationTimer` — `recipient` (a single string) +
    /// `expirationInSeconds`. A group conversation routes the timer change
    /// through the group-management write it always traveled by upstream:
    /// `updateGroup {account, groupId, expiration}` (the §4.41 group refusal
    /// is overturned) — since the engine batch landed `updateGroup
    /// {expiration}` (engine main @ 216a4c7, compat §3/§5 registration
    /// block), all faces share one group payload. Returns the upstream
    /// method name, the payload, and the resolved timer value the success
    /// path mirrors into the conversation row.
    pub fn prepare_conversations_set_expire_timer(
        &self,
        account_id: &str,
        conversation_id: &str,
        expire_seconds: u32,
    ) -> Result<(&'static str, Value, u64), ServiceError> {
        validate_opaque_id(account_id, "accountId")?;
        if conversation_id.is_empty()
            || conversation_id.chars().count() > MAX_PIN_CONVERSATION_ID_CHARS
        {
            return Err(ServiceError::Api(ApiError::new(
                "INVALID_REQUEST",
                "conversationId must contain between 1 and 256 characters",
                false,
            )));
        }
        if expire_seconds > MAX_EXPIRE_TIMER_SECONDS {
            return Err(ServiceError::Api(ApiError::new(
                "INVALID_REQUEST",
                "expireSeconds exceeds the upstream int face",
                false,
            )));
        }
        let account = self.resolve_account(account_id)?;
        let conversation = self.resolve_conversation(account_id, conversation_id)?;
        if conversation.kind != "direct" {
            return Ok((
                "updateGroup",
                json!({
                    "account": account.signal_account,
                    "groupId": conversation.peer_key,
                    "expiration": expire_seconds,
                }),
                u64::from(expire_seconds),
            ));
        }
        Ok((
            "setExpirationTimer",
            json!({
                "account": account.signal_account,
                "recipient": conversation.peer_key,
                "expirationInSeconds": expire_seconds,
            }),
            u64::from(expire_seconds),
        ))
    }

    /// groups.update (contract revision 1.45, §4.44, capability
    /// group-management; the engine write face wired by contract 1.115,
    /// §4.96): the full local validation + resolution ladder, then the
    /// engine's updateGroup payload. Field bounds mirror the schema; the
    /// change keys are individually optional, at least one must be present
    /// (`resetLink: false` counts as absent), and explicit empty member
    /// arrays are refused — upstream reads absence as "no change" and an
    /// empty set would commit a no-delta group change broadcast. The
    /// conversation id must resolve to a kind='group' row (direct answers
    /// INVALID_REQUEST before any upstream call). The engine carries the
    /// title/member/avatar/link-access subset plus the 1.180 resetLink fold,
    /// the 1.188 send-messages fold, and the 1.252 access-control folds
    /// (§4.238 — add-member / edit-details / member-label permissions onto
    /// the engine words membersPermission / attributesPermission /
    /// memberLabelPermission, the engine composing the official
    /// modifyMemberLabels clears from its own group state); a change set
    /// naming anything outside it (description, admin/ban families, the
    /// member label pair) answers CAPABILITY_UNAVAILABLE naming the keys
    /// (retryable=false) after the local validation completed — the honest
    /// whole-call refusal, never a partial application. Zero local writes:
    /// group state converges through the receive projection.
    pub fn prepare_groups_update(
        &self,
        params: &GroupsUpdateParams,
    ) -> Result<Value, ServiceError> {
        validate_opaque_id(&params.account_id, "accountId")?;
        validate_opaque_id(&params.conversation_id, "conversationId")?;
        if params.conversation_id.chars().count() > MAX_PIN_CONVERSATION_ID_CHARS {
            return Err(ServiceError::Api(ApiError::new(
                "INVALID_REQUEST",
                "conversationId must contain between 1 and 256 characters",
                false,
            )));
        }
        if let Some(operation_id) = params.operation_id.as_deref() {
            validate_opaque_id(operation_id, "operationId")?;
        }
        let bounded = |value: &str, max: usize| !value.is_empty() && value.len() <= max;
        let mut changes: Vec<(&'static str, Value)> = Vec::new();
        if let Some(name) = params.group_name.as_deref() {
            if !bounded(name, GROUP_NAME_MAX_BYTES) {
                return Err(ServiceError::Api(ApiError::new(
                    "INVALID_REQUEST",
                    "groupName must contain between 1 and 256 bytes",
                    false,
                )));
            }
            changes.push(("name", json!(name)));
        }
        if let Some(description) = params.group_description.as_deref() {
            if !bounded(description, GROUP_DESCRIPTION_MAX_BYTES) {
                return Err(ServiceError::Api(ApiError::new(
                    "INVALID_REQUEST",
                    "groupDescription must contain between 1 and 4096 bytes",
                    false,
                )));
            }
            changes.push(("description", json!(description)));
        }
        for (field, list) in [
            ("addMembers", &params.add_members),
            ("removeMembers", &params.remove_members),
            ("promoteAdmins", &params.promote_admins),
            ("demoteAdmins", &params.demote_admins),
            ("banMembers", &params.ban_members),
            ("unbanMembers", &params.unban_members),
        ] {
            let Some(members) = list else {
                continue;
            };
            if members.is_empty() {
                return Err(ServiceError::Api(ApiError::new(
                    "INVALID_REQUEST",
                    "an empty member array carries no change upstream; omit the key instead",
                    false,
                )));
            }
            if members.len() > MAX_GROUP_MEMBERS
                || members.iter().any(|member| {
                    member.is_empty() || member.chars().count() > MAX_GROUP_MEMBER_ID_CHARS
                })
            {
                return Err(ServiceError::Api(ApiError::new(
                    "INVALID_REQUEST",
                    "member arrays carry at most 1001 entries of 1-128 characters",
                    false,
                )));
            }
            let key = match field {
                "addMembers" => "members",
                "promoteAdmins" => "admins",
                "demoteAdmins" => "removeAdmins",
                "banMembers" => "bans",
                "unbanMembers" => "unbans",
                _ => "removeMembers",
            };
            changes.push((key, json!(members)));
        }
        if let Some(link_state) = params.link_state.as_deref() {
            // The engine's addFromInviteLinkAccess vocabulary (contract
            // 1.115, §4.96): the connector's enabled-without-approval is the
            // official "anyone with the link joins" face (ANY),
            // enabled-with-approval is the admin-approval gate
            // (ADMINISTRATOR), and disabled is the upstream UNSATISFIABLE —
            // the state no access level can satisfy (the official
            // buildAccessControlAddFromInviteLinkChange enum, the engine's
            // exact write word).
            let access = match link_state {
                "enabled-with-approval" => "ADMINISTRATOR",
                "enabled-without-approval" => "ANY",
                "disabled" => "UNSATISFIABLE",
                _ => {
                    return Err(ServiceError::Api(ApiError::new(
                        "INVALID_REQUEST",
                        "linkState must be one of enabled-with-approval, enabled-without-approval, disabled",
                        false,
                    )));
                }
            };
            changes.push(("addFromInviteLinkAccess", json!(access)));
        }
        if params.reset_link == Some(true) {
            // Contract 1.180 (§4.180): the official refreshGroupLink — the
            // client mints a fresh 16-byte CSPRNG password locally
            // (conversations.preload.ts:4793-4795
            // generateGroupInviteLinkPassword, the official
            // GROUP_INVITE_LINK_PASSWORD_LENGTH) and commits it as the
            // invite-link-password change; the old link dies with the old
            // password. The connector is the engine's client, so the mint
            // lives here (the §4.98 password face stays the engine-side
            // mint for tooling): the password is single-pass material,
            // never logged or persisted, riding the engine payload as
            // standard base64 exactly the way the engine's updateGroup arm
            // reads it (modify_invite_link_password — the official
            // buildInviteLinkPasswordChange).
            let mut password = [0u8; 16];
            rand::rng().fill_bytes(&mut password);
            changes.push(("inviteLinkPassword", json!(base64_encode(&password))));
        }
        for (value, key) in [
            (
                params.permission_add_member.as_deref(),
                "setPermissionAddMember",
            ),
            (
                params.permission_edit_details.as_deref(),
                "setPermissionEditDetails",
            ),
            (
                params.permission_send_messages.as_deref(),
                "setPermissionSendMessages",
            ),
            (
                params.permission_member_label.as_deref(),
                "setPermissionMemberLabel",
            ),
        ] {
            let Some(value) = value else {
                continue;
            };
            match value {
                // The pinned upstream accepts both spellings per choice
                // (every-member/everyMember); the connector forwards its
                // schema vocabulary verbatim.
                "every-member" | "only-admins" => changes.push((key, json!(value))),
                _ => {
                    return Err(ServiceError::Api(ApiError::new(
                        "INVALID_REQUEST",
                        "permission values must be every-member or only-admins",
                        false,
                    )));
                }
            }
        }
        if let Some(label) = params.member_label.as_deref() {
            if !bounded(label, GROUP_MEMBER_LABEL_MAX_BYTES) {
                return Err(ServiceError::Api(ApiError::new(
                    "INVALID_REQUEST",
                    "memberLabel must contain between 1 and 256 bytes",
                    false,
                )));
            }
            changes.push(("memberLabel", json!(label)));
        }
        if let Some(emoji) = params.member_label_emoji.as_deref() {
            validate_emoji(emoji)?;
            changes.push(("memberLabelEmoji", json!(emoji)));
        }
        // The avatar tri-state (contract 1.89): the accounts.setProfile
        // three states, carried by the dedicated `AvatarUpdate` type (shared
        // with setProfile since 1.90) because serde's `Option<Value>` folds
        // an explicit null into "absent" at the option layer — here the
        // three states are distinct on the real deserialization path. The
        // value rides the changes vec verbatim (the omission discipline: a
        // keep adds no key, an explicit null forwards null), and the
        // Remove/Replace forms count as the change set's avatar member — a
        // lone avatar call is a real change, not an empty set. A non-string,
        // non-null avatar type fails at params deserialization (the §4.45
        // discipline); the data-URI shape gate answers INVALID_REQUEST here,
        // ahead of the capability seam.
        match &params.avatar {
            AvatarUpdate::Keep => {}
            AvatarUpdate::Remove => changes.push(("avatar", Value::Null)),
            AvatarUpdate::Replace(data_uri) => {
                changes.push(("avatar", json!(validate_avatar_data_uri(data_uri)?)));
            }
        }
        if changes.is_empty() {
            return Err(ServiceError::Api(ApiError::new(
                "INVALID_REQUEST",
                "at least one group change is required",
                false,
            )));
        }
        // The account row resolves first (the shared ladder's wire order —
        // ACCOUNT_NOT_FOUND before CONVERSATION_NOT_FOUND).
        let account = self.resolve_account(&params.account_id)?;
        let conversation =
            self.resolve_conversation(&params.account_id, &params.conversation_id)?;
        if conversation.kind != "group" {
            return Err(ServiceError::Api(ApiError::new(
                "INVALID_REQUEST",
                "groups.update addresses a group conversation",
                false,
            )));
        }
        // The engine face (contract 1.115, §4.96): the change set folds onto
        // the engine's updateGroup vocabulary — groupName→title, the member
        // arrays verbatim, the avatar tri-state verbatim, the link access
        // word above, (contract 1.180, §4.180) resetLink→a freshly
        // minted `inviteLinkPassword` (the official refreshGroupLink fold),
        // and (contract 1.188, §4.188) setPermissionSendMessages→the
        // engine's `announcementsOnly` bool. A change set carrying any key
        // outside that subset (groupDescription, the admin and ban
        // families, the remaining permission pair including the contract
        // 1.221 member-label access arm, the member label pair)
        // answers
        // CAPABILITY_UNAVAILABLE naming the keys — the honest whole-call
        // refusal, never a partial application: the engine commits the set
        // as one change broadcast and the official client applies it
        // atomically, so folding a subset would silently shrink what the
        // caller asked for.
        let mut unsupported: Vec<&'static str> = Vec::new();
        let mut payload = serde_json::Map::new();
        payload.insert("account".to_owned(), json!(account.signal_account));
        payload.insert("groupId".to_owned(), json!(conversation.peer_key));
        for (key, value) in changes {
            match key {
                "name" => {
                    payload.insert("title".to_owned(), value);
                }
                "members" => {
                    payload.insert("addMembers".to_owned(), value);
                }
                "removeMembers" => {
                    payload.insert("removeMembers".to_owned(), value);
                }
                "avatar" => {
                    payload.insert("avatar".to_owned(), value);
                }
                "addFromInviteLinkAccess" => {
                    payload.insert("addFromInviteLinkAccess".to_owned(), value);
                }
                "inviteLinkPassword" => {
                    payload.insert("inviteLinkPassword".to_owned(), value);
                }
                // Contract 1.188 (§4.188): the announcements-only write rides
                // the engine's own `announcementsOnly` bool (its updateGroup
                // arm, engine `8ea56f6` — the official
                // modifyAnnouncementsOnly group change action,
                // groups.preload.ts:895-904). The connector's host
                // vocabulary stays the official permission word pair; the
                // value was validated at the params layer, so only the fold
                // maps it: only-admins is the announcements-only group,
                // every-member lifts it — both real write intents, never
                // an absent key.
                "setPermissionSendMessages" => {
                    payload.insert(
                        "announcementsOnly".to_owned(),
                        json!(value.as_str() == Some("only-admins")),
                    );
                }
                // Contract 1.252 (§4.238): the three permission arms ride the
                // engine's access-control write family — every-member = MEMBER,
                // only-admins = ADMINISTRATOR (the official AccessRequired enum
                // words the engine handler parses; the value was validated at
                // the params layer). The engine composes the official
                // modifyMemberLabels clear actions on the member-label
                // MEMBER-to-ADMINISTRATOR switch from its own group state, so
                // the caller's single-parameter intent stays single-parameter.
                "setPermissionAddMember" => {
                    payload.insert(
                        "membersPermission".to_owned(),
                        json!(engine_access_control_word(&value)),
                    );
                }
                "setPermissionEditDetails" => {
                    payload.insert(
                        "attributesPermission".to_owned(),
                        json!(engine_access_control_word(&value)),
                    );
                }
                "setPermissionMemberLabel" => {
                    payload.insert(
                        "memberLabelPermission".to_owned(),
                        json!(engine_access_control_word(&value)),
                    );
                }
                // The refusal names the caller's schema vocabulary, not the
                // internal upstream keys the change vec carries.
                _ => {
                    let host = match key {
                        "description" => "groupDescription",
                        "admins" => "promoteAdmins",
                        "removeAdmins" => "demoteAdmins",
                        "bans" => "banMembers",
                        "unbans" => "unbanMembers",
                        other => other,
                    };
                    unsupported.push(host);
                }
            }
        }
        if !unsupported.is_empty() {
            return Err(ServiceError::Api(ApiError::new(
                "CAPABILITY_UNAVAILABLE",
                format!(
                    "the kt-engine updateGroup face does not carry: {}",
                    unsupported.join(", ")
                ),
                false,
            )));
        }
        Ok(Value::Object(payload))
    }

    /// groups.quit (contract revision 1.45, §4.44, capability
    /// group-management; the engine write face wired by contract 1.115,
    /// §4.96): resolution ladder then the engine's `leaveGroup {account,
    /// groupId}` payload — the engine's method name for the upstream quit
    /// write (its face never carried a `quitGroup` literal). The upstream
    /// --delete local-data flag and the --admin last-admin handoff list are
    /// deliberately not exposed: the official client keeps the conversation
    /// as a non-member after leaving, and a last-admin quit without a
    /// handoff answers the upstream user error verbatim (the deterministic
    /// UPSTREAM_ERROR face, retryable=false). The local conversation row is
    /// kept — non-member state is upstream convergence, like groups.update.
    pub fn prepare_groups_quit(&self, params: &GroupsQuitParams) -> Result<Value, ServiceError> {
        validate_opaque_id(&params.account_id, "accountId")?;
        validate_opaque_id(&params.conversation_id, "conversationId")?;
        if params.conversation_id.chars().count() > MAX_PIN_CONVERSATION_ID_CHARS {
            return Err(ServiceError::Api(ApiError::new(
                "INVALID_REQUEST",
                "conversationId must contain between 1 and 256 characters",
                false,
            )));
        }
        if let Some(operation_id) = params.operation_id.as_deref() {
            validate_opaque_id(operation_id, "operationId")?;
        }
        let account = self.resolve_account(&params.account_id)?;
        let conversation =
            self.resolve_conversation(&params.account_id, &params.conversation_id)?;
        if conversation.kind != "group" {
            return Err(ServiceError::Api(ApiError::new(
                "INVALID_REQUEST",
                "groups.quit addresses a group conversation",
                false,
            )));
        }
        Ok(json!({
            "account": account.signal_account,
            "groupId": conversation.peer_key,
        }))
    }

    /// groups.terminate (contract revision 1.52, §4.50, capability
    /// group-terminate): resolution ladder then the upstream `terminateGroup
    /// {account, groupId}` payload — the pinned 0.14.8 JSON-RPC face
    /// (`TerminateGroupCommand`, a `JsonRpcLocalCommand`) wrapping
    /// `GroupHelper.terminateGroup` → `GroupV2Helper.terminateGroup` →
    /// libsignal `createTerminateGroup()`. The upstream command answers
    /// `GroupSendingNotAllowedException` (non-admin, the GroupsV2
    /// UNAUTHORIZED face) and `NotAGroupMemberException` /
    /// `GroupNotFoundException` as user errors — all forward verbatim as the
    /// UPSTREAM_ERROR family; the v1-group refusal ("only supported for
    /// Signal group v2 groups") rides the same family. Zero local writes: the
    /// terminated state converges through the receive projection like every
    /// group change (the §4.44 discipline).
    pub fn prepare_groups_terminate(
        &self,
        params: &GroupsTerminateParams,
    ) -> Result<Value, ServiceError> {
        validate_opaque_id(&params.account_id, "accountId")?;
        validate_opaque_id(&params.conversation_id, "conversationId")?;
        if params.conversation_id.chars().count() > MAX_PIN_CONVERSATION_ID_CHARS {
            return Err(ServiceError::Api(ApiError::new(
                "INVALID_REQUEST",
                "conversationId must contain between 1 and 256 characters",
                false,
            )));
        }
        if let Some(operation_id) = params.operation_id.as_deref() {
            validate_opaque_id(operation_id, "operationId")?;
        }
        let account = self.resolve_account(&params.account_id)?;
        let conversation =
            self.resolve_conversation(&params.account_id, &params.conversation_id)?;
        if conversation.kind != "group" {
            return Err(ServiceError::Api(ApiError::new(
                "INVALID_REQUEST",
                "groups.terminate addresses a group conversation",
                false,
            )));
        }
        Ok(json!({
            "account": account.signal_account,
            "groupId": conversation.peer_key,
        }))
    }

    /// groups.approveJoinRequests (contract revision 1.58, §4.53, capability
    /// group-join-approve): the local validation + resolution ladder, then
    /// the honest refusal. `prepare` owns every fail-closed gate that needs
    /// no engine call: member-array bounds (the §4.44 discipline — an empty
    /// array carries no change upstream, so it is refused by shape), the
    /// group-row resolution (direct answers INVALID_REQUEST before any
    /// upstream call), and the audit id shape. The engine face has no
    /// updateGroup member-family method (the engine's updateGroup takes the
    /// expiration family only — its compat §5 batch boundary) and answers
    /// CAPABILITY_UNAVAILABLE (retryable=false) after the local validation
    /// completed — the groups.update/groups.quit engine-batch debt
    /// precedent, honest by design: answering the fold instead would
    /// disguise "the engine cannot approve" as "nobody is requesting".
    pub fn prepare_groups_approve_join_requests(
        &self,
        params: &GroupsApproveJoinRequestsParams,
    ) -> Result<(String, Vec<String>, bool), ServiceError> {
        validate_opaque_id(&params.account_id, "accountId")?;
        validate_opaque_id(&params.conversation_id, "conversationId")?;
        if params.conversation_id.chars().count() > MAX_PIN_CONVERSATION_ID_CHARS {
            return Err(ServiceError::Api(ApiError::new(
                "INVALID_REQUEST",
                "conversationId must contain between 1 and 256 characters",
                false,
            )));
        }
        if let Some(operation_id) = params.operation_id.as_deref() {
            validate_opaque_id(operation_id, "operationId")?;
        }
        if params.members.is_empty() {
            return Err(ServiceError::Api(ApiError::new(
                "INVALID_REQUEST",
                "an empty member array carries no change upstream; omit the call instead",
                false,
            )));
        }
        if params.members.len() > MAX_GROUP_MEMBERS
            || params.members.iter().any(|member| {
                member.is_empty() || member.chars().count() > MAX_GROUP_MEMBER_ID_CHARS
            })
        {
            return Err(ServiceError::Api(ApiError::new(
                "INVALID_REQUEST",
                "members carries at most 1001 entries of 1-128 characters",
                false,
            )));
        }
        // The account row resolves first (the shared ladder's wire order —
        // ACCOUNT_NOT_FOUND before CONVERSATION_NOT_FOUND).
        self.resolve_account(&params.account_id)?;
        let conversation =
            self.resolve_conversation(&params.account_id, &params.conversation_id)?;
        if conversation.kind != "group" {
            return Err(ServiceError::Api(ApiError::new(
                "INVALID_REQUEST",
                "groups.approveJoinRequests addresses a group conversation",
                false,
            )));
        }
        Err(ServiceError::Api(ApiError::new(
            "CAPABILITY_UNAVAILABLE",
            "the kt-engine face has no updateGroup member-family method yet",
            false,
        )))
    }

    /// groups.revokeInvites (contract revision 1.64, §4.57, capability
    /// group-invite-revoke): the local validation + resolution ladder, then
    /// the honest refusal. The `prepare_groups_approve_join_requests`
