    #[test]
    fn adjacent_media_probe_ladders_and_keeps_the_unread_badge() {
        let (_temp, service) = service();
        let account = service
            .store_ref()
            .upsert_account_from_signal("+15555550100", Some(1), crate::DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let conversation = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        // Unknown account and unknown conversation both fail their
        // deterministic ladder rung before any scan runs.
        let no_account = service.list_adjacent_media(
            "no-such-account",
            &conversation.id,
            "m-anchor",
            crate::store::AdjacentMediaDirection::Older,
            1,
        );
        assert!(matches!(
            no_account,
            Err(ServiceError::Store(StoreError::AccountNotFound))
        ));
        let no_conversation = service.list_adjacent_media(
            &account.id,
            "no-such-conversation",
            "m-anchor",
            crate::store::AdjacentMediaDirection::Older,
            1,
        );
        assert!(matches!(
            no_conversation,
            Err(ServiceError::Store(StoreError::ConversationNotFound))
        ));
        // A media row plus an unread badge on the conversation: the probe
        // answers the row and the badge stays put — probing the lightbox's
        // neighbors is not viewing the thread (the messages.list clear is
        // deliberately not mirrored).
        let mut media = expire_record_fixture(&account.id, &conversation.id, "m-media");
        media.sent_at = 5;
        media.attachments = vec![NormalizedAttachment {
            id: "a-media".into(),
            content_type: Some("image/jpeg".into()),
            filename: None,
            size: Some(1024),
            width: None,
            height: None,
            is_voice_note: false,
            caption: None,
            blur_hash: None,
            incremental_mac: None,
            chunk_size: None,
            is_borderless: false,
            is_gif: false,
            locator: None,
            waveform: None,
            duration: None,
        }];
        service
            .store_ref()
            .insert_message(&media, None, None, true)
            .unwrap();
        let anchor = expire_record_fixture(&account.id, &conversation.id, "m-anchor");
        service
            .store_ref()
            .insert_message(&anchor, None, None, true)
            .unwrap();
        let before = service
            .store_ref()
            .conversation_summary(&account.id, &conversation.id)
            .unwrap()
            .map(|summary| summary.unread_count);
        let items = service
            .list_adjacent_media(
                &account.id,
                &conversation.id,
                "m-anchor",
                crate::store::AdjacentMediaDirection::Older,
                1,
            )
            .unwrap();
        assert_eq!(items.len(), 1);
        assert_eq!(items[0].id, "m-media");
        let after = service
            .store_ref()
            .conversation_summary(&account.id, &conversation.id)
            .unwrap()
            .map(|summary| summary.unread_count);
        assert_eq!(before, after, "the probe never clears the unread badge");
        assert!(after.unwrap_or(0) > 0, "the badge was live to begin with");
        // A vanished anchor maps to the deterministic invalid-cursor rung.
        let gone = service.list_adjacent_media(
            &account.id,
            &conversation.id,
            "m-gone",
            crate::store::AdjacentMediaDirection::Newer,
            1,
        );
        assert!(matches!(
            gone,
            Err(ServiceError::Store(StoreError::InvalidCursor))
        ));
    }

    /// The backfill-response consume arm (contract revision 1.175, §4.175;
    /// the settled face 1.193, §4.193): the primary's fresh transit pointers
    /// merge into the target row's empty live-locator slots — the row the
    /// receive arm never filled (or the optimistic outgoing row the echo
    /// could not overwrite) becomes downloadable — and the resolved answer
    /// reports its whole index-aligned face to the desktop. The error arm
    /// changes nothing and emits only its own event.
    #[test]
    fn backfill_response_merges_locators_into_the_target_row() {
        let (_temp, mut service) = service();
        let summary = service
            .store_ref()
            .upsert_account_from_signal("+15555550100", Some(1), crate::DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let account = service
            .store_ref()
            .account_by_id(&summary.id)
            .unwrap()
            .expect("account row");
        let conversation = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        let descriptor = |id: &str| NormalizedAttachment {
            id: id.into(),
            content_type: Some("image/png".into()),
            filename: None,
            size: Some(2048),
            width: None,
            height: None,
            is_voice_note: false,
            caption: None,
            blur_hash: None,
            incremental_mac: None,
            chunk_size: None,
            is_borderless: false,
            is_gif: false,
            locator: None,
            waveform: None,
            duration: None,
        };
        let mut row = expire_record_fixture(&account.id, &conversation.id, "m-backfill");
        row.sent_at = 1726999999000;
        row.attachments = vec![descriptor("att-a"), descriptor("att-b")];
        service
            .store_ref()
            .insert_message(&row, None, None, true)
            .unwrap();
        // The insert stored all-default faces index-aligned — the merge's
        // empty slots.
        let initial = service
            .store_ref()
            .live_attachment_locators(&account.id, "m-backfill")
            .unwrap();
        assert_eq!(initial.len(), 2);
        assert!(
            initial
                .iter()
                .all(|face| face == &crate::store::HistoryAttachmentLocator::default())
        );

        let face = |cdn: &str| crate::store::HistoryAttachmentLocator {
            key: Some("a2F0LWtleQ==".into()),
            cdn_key: Some(cdn.into()),
            cdn_number: Some(3),
            upload_timestamp: Some(1700000000000),
            digest: None,
            plaintext_hash: None,
        };
        let response = crate::engine::SyncAttachmentBackfillResponse {
            author: "peer".into(),
            sent_timestamp: 1726999999000,
            conversation_service_id: None,
            conversation_group_id: None,
            conversation_e164: Some("+15555550101".into()),
            error: None,
            entries: vec![
                BackfillEntry::Locator(Some(face("cdn-a"))),
                BackfillEntry::Status(BackfillStatus::Pending),
            ],
            long_text: None,
        };
        let events = service
            .apply_sync_attachment_backfill_response(&account, &response)
            .unwrap();
        // Contract 1.193 (§4.193): the pointer arm now reports the resolved
        // face — the pointer entry is available, the status entry pending.
        let [event] = events.as_slice() else {
            panic!("the pointer arm reports its settled face exactly once, got {events:?}");
        };
        let HostSideEvent::MessageAttachmentBackfillSettled {
            account_id,
            conversation_id,
            message_id,
            attachments,
            long_text_pending,
            long_text_terminal,
        } = event
        else {
            panic!("the pointer arm emits MessageAttachmentBackfillSettled, got {event:?}");
        };
        assert_eq!(account_id, &account.id);
        assert_eq!(conversation_id, &conversation.id);
        assert_eq!(message_id, "m-backfill");
        assert!(
            !*long_text_pending && !*long_text_terminal,
            "no longText entry means no longText state"
        );
        assert_eq!(
            attachments,
            &vec![
                AttachmentBackfillSettledEntry {
                    index: 0,
                    status: "available",
                },
                AttachmentBackfillSettledEntry {
                    index: 1,
                    status: "pending",
                },
            ]
        );
        let faces = service
            .store_ref()
            .live_attachment_locators(&account.id, "m-backfill")
            .unwrap();
        assert_eq!(faces.len(), 2);
        assert_eq!(faces[0], face("cdn-a"));
        assert_eq!(faces[1], crate::store::HistoryAttachmentLocator::default());

        // The error arm (contract 1.192, §4.192): the phone's terminal answer
        // names the resolved row to the desktop (the official NotFound face)
        // and never moves a face. It never emits the settled event — the
        // destructuring above already pins the single-event face.
        let response = crate::engine::SyncAttachmentBackfillResponse {
            author: "peer".into(),
            sent_timestamp: 1726999999000,
            conversation_service_id: None,
            conversation_group_id: None,
            conversation_e164: Some("+15555550101".into()),
            error: Some("MESSAGE_NOT_FOUND".into()),
            entries: Vec::new(),
            long_text: None,
        };
        let events = service
            .apply_sync_attachment_backfill_response(&account, &response)
            .unwrap();
        let [event] = events.as_slice() else {
            panic!("the error arm names the row exactly once");
        };
        let HostSideEvent::MessageAttachmentBackfillError {
            account_id,
            conversation_id,
            message_id,
            error,
        } = event
        else {
            panic!("the error arm emits MessageAttachmentBackfillError, got {event:?}");
        };
        assert_eq!(account_id, &account.id);
        assert_eq!(conversation_id, &conversation.id);
        assert_eq!(message_id, "m-backfill");
        assert_eq!(error, "MESSAGE_NOT_FOUND");
        let faces = service
            .store_ref()
            .live_attachment_locators(&account.id, "m-backfill")
            .unwrap();
        assert_eq!(faces[0], face("cdn-a"), "error arm never moves a face");

        // An error arm whose target matches no row stays the quiet warn —
        // no event, the official handleResponse drop.
        let response = crate::engine::SyncAttachmentBackfillResponse {
            author: "peer".into(),
            sent_timestamp: 1726999999001,
            conversation_service_id: None,
            conversation_group_id: None,
            conversation_e164: Some("+15555550101".into()),
            error: Some("MESSAGE_NOT_FOUND".into()),
            entries: Vec::new(),
            long_text: None,
        };
        let events = service
            .apply_sync_attachment_backfill_response(&account, &response)
            .unwrap();
        assert!(
            events.is_empty(),
            "an unresolvable error target stays quiet (rows_by_sent_at misses)"
        );
    }

    /// Contract 1.193 (§4.193): the pointer/status arm's settle face maps
    /// every entry to its official word — pointer → `available`,
    /// `TERMINAL_ERROR` → `terminal`, `PENDING` → `pending`, an unknown
    /// status word → `pending` (the official `missingCaseError` crash at
    /// attachmentBackfill.preload.ts:303 is not a face KT copies) — with the
    /// wire index ascending and aligned to the remote list. An unresolvable
    /// target stays the quiet warn: zero events, the official
    /// `handleResponse` conversation/message-not-found early returns
    /// (:131-140). An empty entry list still settles (the official
    /// `pendingCount === 0` timer cancel, :324-327).
    #[test]
    fn attachment_backfill_settled_event_names_every_attachment_state() {
        let (_temp, mut service) = service();
        let summary = service
            .store_ref()
            .upsert_account_from_signal("+15555550100", Some(1), crate::DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let account = service
            .store_ref()
            .account_by_id(&summary.id)
            .unwrap()
            .expect("account row");
        let conversation = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        let descriptor = |id: &str| NormalizedAttachment {
            id: id.into(),
            content_type: Some("image/png".into()),
            filename: None,
            size: Some(2048),
            width: None,
            height: None,
            is_voice_note: false,
            caption: None,
            blur_hash: None,
            incremental_mac: None,
            chunk_size: None,
            is_borderless: false,
            is_gif: false,
            locator: None,
            waveform: None,
            duration: None,
        };
        let mut row = expire_record_fixture(&account.id, &conversation.id, "m-states");
        row.sent_at = 1726999999100;
        row.attachments = vec![descriptor("att-a"), descriptor("att-b")];
        service
            .store_ref()
            .insert_message(&row, None, None, true)
            .unwrap();

        let face = |cdn: &str| crate::store::HistoryAttachmentLocator {
            key: Some("a2F0LWtleQ==".into()),
            cdn_key: Some(cdn.into()),
            cdn_number: Some(3),
            upload_timestamp: Some(1700000000000),
            digest: None,
            plaintext_hash: None,
        };
        let response = crate::engine::SyncAttachmentBackfillResponse {
            author: "peer".into(),
            sent_timestamp: 1726999999100,
            conversation_service_id: None,
            conversation_group_id: None,
            conversation_e164: Some("+15555550101".into()),
            error: None,
            entries: vec![
                BackfillEntry::Locator(Some(face("cdn-a"))),
                BackfillEntry::Status(BackfillStatus::Terminal),
                BackfillEntry::Status(BackfillStatus::Unknown),
                BackfillEntry::Locator(None),
            ],
            long_text: None,
        };
        let events = service
            .apply_sync_attachment_backfill_response(&account, &response)
            .unwrap();
        let [event] = events.as_slice() else {
            panic!("the settled face rides exactly one event, got {events:?}");
        };
        let HostSideEvent::MessageAttachmentBackfillSettled {
            account_id,
            conversation_id,
            message_id,
            attachments,
            long_text_pending,
            long_text_terminal,
        } = event
        else {
            panic!("expected MessageAttachmentBackfillSettled, got {event:?}");
        };
        assert_eq!(account_id, &account.id);
        assert_eq!(conversation_id, &conversation.id);
        assert_eq!(message_id, "m-states");
        assert!(
            !*long_text_pending && !*long_text_terminal,
            "no longText entry means no longText state"
        );
        assert_eq!(
            attachments,
            &vec![
                AttachmentBackfillSettledEntry {
                    index: 0,
                    status: "available",
                },
                AttachmentBackfillSettledEntry {
                    index: 1,
                    status: "terminal",
                },
                AttachmentBackfillSettledEntry {
                    index: 2,
                    status: "pending",
                },
                AttachmentBackfillSettledEntry {
                    index: 3,
                    status: "available",
                },
            ],
            "index ascending, one entry per remote position, unknown folded to pending"
        );
        let faces = service
            .store_ref()
            .live_attachment_locators(&account.id, "m-states")
            .unwrap();
        assert_eq!(faces[0], face("cdn-a"));
        assert_eq!(
            faces[1],
            crate::store::HistoryAttachmentLocator::default(),
            "status entries never move a face"
        );

        // An empty list still settles: the official pendingCount === 0 branch
        // cancels the request timer, and the desktop needs the same signal.
        let response = crate::engine::SyncAttachmentBackfillResponse {
            author: "peer".into(),
            sent_timestamp: 1726999999100,
            conversation_service_id: None,
            conversation_group_id: None,
            conversation_e164: Some("+15555550101".into()),
            error: None,
            entries: Vec::new(),
            long_text: None,
        };
        let events = service
            .apply_sync_attachment_backfill_response(&account, &response)
            .unwrap();
        let [HostSideEvent::MessageAttachmentBackfillSettled { attachments, .. }] =
            events.as_slice()
        else {
            panic!("the empty list settles too, got {events:?}");
        };
        assert!(attachments.is_empty());

        // An unresolvable target (no row at that stamp) stays the quiet warn:
        // zero events, the official handleResponse drop.
        let response = crate::engine::SyncAttachmentBackfillResponse {
            author: "peer".into(),
            sent_timestamp: 1726999999999,
            conversation_service_id: None,
            conversation_group_id: None,
            conversation_e164: Some("+15555550101".into()),
            error: None,
            entries: vec![BackfillEntry::Status(BackfillStatus::Terminal)],
            long_text: None,
        };
        let events = service
            .apply_sync_attachment_backfill_response(&account, &response)
            .unwrap();
        assert!(
            events.is_empty(),
            "an unresolvable settle target stays quiet (rows_by_sent_at misses)"
        );
    }

    /// Contract 1.195 (§4.195): the official `response.longText` state
    /// (attachmentBackfill.preload.ts:247-283) rides the settled event as two
    /// optional booleans because KT has no body-attachment slot:
    /// `PENDING`/an unknown word → `long_text_pending`, `TERMINAL_ERROR` →
    /// `long_text_terminal`, a pointer or absence → both false. An empty
    /// attachment list beside a longText state still settles — the official
    /// `pendingCount` includes the long-text body (:191), which is exactly
    /// the timer-arm signal the desktop needs.
    #[test]
    fn attachment_backfill_settled_event_reports_long_text_state() {
        let (_temp, mut service) = service();
        let summary = service
            .store_ref()
            .upsert_account_from_signal("+15555550100", Some(1), crate::DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let account = service
            .store_ref()
            .account_by_id(&summary.id)
            .unwrap()
            .expect("account row");
        let conversation = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        let mut row = expire_record_fixture(&account.id, &conversation.id, "m-long-text");
        row.sent_at = 1726999999200;
        service
            .store_ref()
            .insert_message(&row, None, None, true)
            .unwrap();

        let apply = |service: &mut ConnectorService, long_text: Option<BackfillEntry>| {
            let response = crate::engine::SyncAttachmentBackfillResponse {
                author: "peer".into(),
                sent_timestamp: 1726999999200,
                conversation_service_id: None,
                conversation_group_id: None,
                conversation_e164: Some("+15555550101".into()),
                error: None,
                entries: Vec::new(),
                long_text,
            };
            let events = service
                .apply_sync_attachment_backfill_response(&account, &response)
                .unwrap();
            let [event] = events.as_slice() else {
                panic!("the longText settle rides exactly one event, got {events:?}");
            };
            let HostSideEvent::MessageAttachmentBackfillSettled {
                attachments,
                long_text_pending,
                long_text_terminal,
                ..
            } = event
            else {
                panic!("expected MessageAttachmentBackfillSettled, got {event:?}");
            };
            (attachments.clone(), *long_text_pending, *long_text_terminal)
        };

        // PENDING contributes to the official pendingCount: the attachment
        // list is empty yet the long-text half is still pending.
        assert_eq!(
            apply(
                &mut service,
                Some(BackfillEntry::Status(BackfillStatus::Pending))
            ),
            (Vec::new(), true, false)
        );
        // An unknown status word folds to pending (the same non-crash face
        // the attachment entries use).
        assert_eq!(
            apply(
                &mut service,
                Some(BackfillEntry::Status(BackfillStatus::Unknown))
            ),
            (Vec::new(), true, false)
        );
        // TERMINAL_ERROR is the terminal long-text face — the other key only.
        assert_eq!(
            apply(
                &mut service,
                Some(BackfillEntry::Status(BackfillStatus::Terminal))
            ),
            (Vec::new(), false, true)
        );
        // A pointer longText has nothing to wait on and nothing to report;
        // absence is the same no-key face. Neither contributes a list entry.
        assert_eq!(
            apply(&mut service, Some(BackfillEntry::Locator(None))),
            (Vec::new(), false, false)
        );
        assert_eq!(apply(&mut service, None), (Vec::new(), false, false));
    }

    /// attachments.requestBackfill prepare (contract revision 1.175, §4.175;
    /// author faces widened by 1.191, §4.191): the official target triple
    /// derives from the resolved row — a direct leg carries the peer key with
    /// the protocol identity ladder as author (the captured ACI first, the
    /// peer key itself second), an outgoing row names the account itself, the
    /// group leg carries the master key with the captured member ACI as
    /// author (a capture-less pre-1.191 row refuses honestly), and a
    /// zero-stamp row fails closed before any engine traffic. The ingest
    /// privacy hash never rides the author seat in any arm.
    #[test]
    fn prepare_request_attachment_backfill_derives_the_official_target() {
        let (_temp, service) = service();
        let account = service
            .store_ref()
            .upsert_account_from_signal("+15555550100", Some(1), crate::DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let conversation = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        let group = service
            .store_ref()
            .ensure_conversation(&account.id, "group", "ZmFrZS1ncm91cA==", "Group")
            .unwrap();
        let mut incoming = expire_record_fixture(&account.id, &conversation.id, "m-in");
        incoming.sent_at = 1726999999000;
        service
            .store_ref()
            .insert_message(&incoming, None, None, true)
            .unwrap();
        let mut outgoing = expire_record_fixture(&account.id, &conversation.id, "m-out");
        outgoing.direction = "outgoing";
        outgoing.sent_at = 1726999999001;
        service
            .store_ref()
            .insert_message(&outgoing, None, None, false)
            .unwrap();
        let mut group_row = expire_record_fixture(&account.id, &group.id, "m-group");
        group_row.sent_at = 1726999999002;
        group_row.author_aci = Some("9d4f1c58-11aa-4c0e-9a4e-5b6a7c8d9e0f".into());
        service
            .store_ref()
            .insert_message(&group_row, None, None, true)
            .unwrap();

        // The direct leg: no §4.37 identity captured yet, so the ladder falls
        // to the peer key itself — the E.164 face the engine resolves through
        // its own-number/contacts arms. The ingest hash ("peer") never
        // appears.
        let prepared = service
            .prepare_request_attachment_backfill(&AttachmentBackfillRequestParams {
                account_id: account.id.clone(),
                conversation_id: conversation.id.clone(),
                message_id: "m-in".into(),
            })
            .unwrap();
        assert_eq!(prepared["account"], json!("+15555550100"));
        assert_eq!(prepared["recipient"], json!("+15555550101"));
        assert_eq!(prepared["author"], json!("+15555550101"));
        assert_eq!(prepared["sentTimestamp"], json!(1726999999000u64));
        assert!(prepared.get("groupId").is_none());

        // The ladder's first arm: the §4.37 capture names the peer's ACI and
        // the backfill sends it verbatim (the engine's service-id arm).
        service
            .store_ref()
            .upsert_peer_identity(
                &account.id,
                "f00dfeed-22bb-4d1f-8b5f-6c7d8e9f0a1b",
                "+15555550101",
            )
            .unwrap();
        let prepared = service
            .prepare_request_attachment_backfill(&AttachmentBackfillRequestParams {
                account_id: account.id.clone(),
                conversation_id: conversation.id.clone(),
                message_id: "m-in".into(),
            })
            .unwrap();
        assert_eq!(
            prepared["author"],
            json!("f00dfeed-22bb-4d1f-8b5f-6c7d8e9f0a1b")
        );

        // The outgoing row names the account itself as the author.
        let prepared = service
            .prepare_request_attachment_backfill(&AttachmentBackfillRequestParams {
                account_id: account.id.clone(),
                conversation_id: conversation.id.clone(),
                message_id: "m-out".into(),
            })
            .unwrap();
        assert_eq!(prepared["author"], json!("+15555550100"));
        assert_eq!(prepared["sentTimestamp"], json!(1726999999001u64));

        // The group leg rides the master key with the captured member ACI as
        // the author — the row-level §4.191 capture, the only face that names
        // a group member.
        let prepared = service
            .prepare_request_attachment_backfill(&AttachmentBackfillRequestParams {
                account_id: account.id.clone(),
                conversation_id: group.id.clone(),
                message_id: "m-group".into(),
            })
            .unwrap();
        assert_eq!(prepared["groupId"], json!("ZmFrZS1ncm91cA=="));
        assert_eq!(
            prepared["author"],
            json!("9d4f1c58-11aa-4c0e-9a4e-5b6a7c8d9e0f")
        );
        assert!(prepared.get("recipient").is_none());

        // A pre-1.191 group row (no capture) answers honestly instead of
        // spending an engine call on an author the engine must refuse — the
        // row's `sender_id` hash is not an identity the protocol speaks.
        let mut uncaptured = expire_record_fixture(&account.id, &group.id, "m-group-legacy");
        uncaptured.sent_at = 1726999999003;
        uncaptured.author_aci = None;
        service
            .store_ref()
            .insert_message(&uncaptured, None, None, true)
            .unwrap();
        let refused =
            service.prepare_request_attachment_backfill(&AttachmentBackfillRequestParams {
                account_id: account.id.clone(),
                conversation_id: group.id.clone(),
                message_id: "m-group-legacy".into(),
            });
        assert!(
            matches!(refused, Err(ServiceError::Api(ref error)) if error.code == "INVALID_REQUEST"),
            "a capture-less group row refuses before any engine traffic"
        );

        // The id ladder still runs first.
        let unknown =
            service.prepare_request_attachment_backfill(&AttachmentBackfillRequestParams {
                account_id: account.id.clone(),
                conversation_id: conversation.id.clone(),
                message_id: "m-absent".into(),
            });
        assert!(matches!(
            unknown,
            Err(ServiceError::Store(StoreError::MessageNotFound))
        ));

        // A zero-stamp row never went upstream and cannot be backfilled.
        let mut zero = expire_record_fixture(&account.id, &conversation.id, "m-zero");
        zero.sent_at = 0;
        service
            .store_ref()
            .insert_message(&zero, None, None, true)
            .unwrap();
        let zero = service.prepare_request_attachment_backfill(&AttachmentBackfillRequestParams {
            account_id: account.id.clone(),
            conversation_id: conversation.id.clone(),
            message_id: "m-zero".into(),
        });
        assert!(matches!(
            zero,
            Err(ServiceError::Api(ref error)) if error.code == "INVALID_REQUEST"
        ));
    }

    /// §4.191: the receive arm captures the envelope's `sourceUuid` onto the
    /// row (the member ACI — the author's protocol identity), and the
    /// backfill request for that landed group row names it verbatim. The
    /// row's `sender_id` ingest hash never appears in the prepared frame,
    /// and the direct receive captures its peer identity the same way.
    #[test]
    fn group_receive_captures_the_member_aci_and_the_backfill_names_it() {
        let (_temp, mut service) = service();
        let account = service
            .store_ref()
            .upsert_account_from_signal("+15555550100", Some(1), crate::DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let member_aci = "c3b07a1e-55cc-4a44-9e11-8a2b3c4d5e6f";
        let receive = NormalizedReceive {
            required_protocol_version: None,
            timestamp: Some(1726999999004),
            content_kind: "dataMessage",
            direction: "incoming",
            account_present: true,
            account: Some("+15555550100".into()),
            source: Some("+15555550101".into()),
            source_uuid: Some(member_aci.to_string()),
            peer_name: Some("Peer".into()),
            group_id: Some("ZmFrZS1ncm91cA==".into()),
            text: Some("photo".into()),
            text_bytes: None,
            text_truncated: false,
            quote: None,
            attachments: Vec::new(),
            rich: None,
            sticker: None,
            expire_seconds: None,
            expire_start_at: None,
            control: None,
            server_guid: None,
            reporting_token: None,
            server_timestamp: None,
        };
        let mut source_only = receive.clone();
        let events = service
            .ingest_receive(receive, crate::DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let landed = events
            .iter()
            .find_map(|event| match event {
                HostSideEvent::MessageUpserted(record) => Some(record.clone()),
                _ => None,
            })
            .expect("the group row lands");
        let conversation = service
            .store_ref()
            .ensure_conversation(&account.id, "group", "ZmFrZS1ncm91cA==", "Group")
            .unwrap();
        let row = service
            .list_messages(&account.id, &conversation.id, 10, None)
            .unwrap()
            .items
            .into_iter()
            .next()
            .unwrap();
        assert_eq!(row.author_aci.as_deref(), Some(member_aci));

        let prepared = service
            .prepare_request_attachment_backfill(&AttachmentBackfillRequestParams {
                account_id: account.id.clone(),
                conversation_id: conversation.id.clone(),
                message_id: row.id.clone(),
            })
            .unwrap();
        assert_eq!(prepared["author"], json!(member_aci));

        // Some engines carry the author ACI only in `source` (no sourceUuid).
        // The fallback must still capture it, otherwise group names resolve to
        //「未知联系人」even though every contact is present.
        source_only.timestamp = Some(1726999999005);
        source_only.source_uuid = None;
        source_only.source = Some(member_aci.to_string());
        source_only.text = Some("photo2".into());
        service
            .ingest_receive(source_only, crate::DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let rows = service
            .list_messages(&account.id, &conversation.id, 10, None)
            .unwrap()
            .items;
        let fallback_row = rows
            .iter()
            .find(|row| row.text.as_deref() == Some("photo2"))
            .expect("the source-only group row lands");
        assert_eq!(fallback_row.author_aci.as_deref(), Some(member_aci));
        assert_eq!(prepared["groupId"], json!("ZmFrZS1ncm91cA=="));
        assert_eq!(prepared["sentTimestamp"], json!(1726999999004u64));
        assert_ne!(
            prepared["author"],
            json!(row.sender_id),
            "the ingest hash never rides the author seat"
        );
        assert_ne!(prepared["author"], json!(landed.sender_id));
    }
    #[test]
    fn cancelled_link_cannot_complete_or_create_an_account() {
        let (_temp, mut service) = service();
        let started = service
            .begin_link("KT".into(), "sgnl://link?test".into())
            .unwrap();
        let link_session_id = started["linkSessionId"].as_str().unwrap().to_string();

        service.cancel_link(&link_session_id).unwrap();
        let late = service.complete_link_session(
            &link_session_id,
            "+15555550100",
            crate::DEFAULT_PROXY_GROUP_ID,
            None,
        );

        assert!(matches!(late, Err(ServiceError::Api(_))));
        assert!(
            service
                .list_accounts_in_group(crate::DEFAULT_PROXY_GROUP_ID)
                .unwrap()
                .is_empty()
        );
    }

    /// Contract 1.276 (§4.260): a repeated finish with the same
    /// linkSessionId replays the committed account instead of asking the
    /// phone again or minting a second binding.
    #[test]
    fn repeated_finish_same_link_session_replays_committed_account() {
        let (_temp, mut service) = service();
        let group = crate::DEFAULT_PROXY_GROUP_ID;
        let started = service
            .begin_link("KT".into(), "sgnl://link?test".into())
            .unwrap();
        let link_session_id = started["linkSessionId"].as_str().unwrap().to_string();

        let first = service
            .complete_link_session(&link_session_id, "+15555550100", group, None)
            .unwrap();
        let second = service
            .complete_link_session(&link_session_id, "+15555550100", group, None)
            .unwrap();

        assert_eq!(first.id, second.id);
        assert_eq!(service.list_accounts_in_group(group).unwrap().len(), 1);
    }

    /// Contract 1.286 (§4.272): `link.start` keeps the pre-rotate wire
    /// (linkSessionId = slot 0's id, qrPayload = its code) and adds the
    /// attempt face. A pre-rotate host that only reads linkSessionId/qrPayload
    /// keeps working unchanged.
    #[test]
    fn begin_link_answers_the_attempt_face_beside_the_single_slot() {
        let (_temp, mut service) = service();
        let started = service
            .begin_link("KT".into(), "sgnl://link?uuid=slot0".into())
            .unwrap();
        let link_session_id = started["linkSessionId"].as_str().unwrap();
        assert!(!link_session_id.is_empty());
        assert!(
            started["linkAttemptId"]
                .as_str()
                .is_some_and(|attempt| !attempt.is_empty()),
            "the attempt id always rides the answer: {started}"
        );
        assert_ne!(started["linkAttemptId"].as_str(), Some(link_session_id));
        assert_eq!(started["qrPayload"], "sgnl://link?uuid=slot0");
        assert_eq!(started["deviceLinkUri"], "sgnl://link?uuid=slot0");
        assert_eq!(
            started["slots"],
            serde_json::json!([{ "deviceLinkUri": "sgnl://link?uuid=slot0", "slot": 0 }])
        );
        assert!(
            service.has_link_session(link_session_id),
            "slot 0 is addressable by the historical id"
        );
    }

    /// Contract 1.286 (§4.272): two rotations fill both live slots; the third
    /// retires the oldest code, which stays addressable but is no longer
    /// scannable.
    #[test]
    fn a_third_rotation_retires_the_oldest_live_slot() {
        let (_temp, mut service) = service();
        let (attempt, first) = service.plant_link_attempt_for_test(
            "KT",
            Some("engine-attempt-1"),
            crate::link::LINK_SESSION_TTL,
        );
        let second = service
            .attach_rotated_slot(&attempt, "sgnl://link?second".into(), now_ms())
            .unwrap();
        assert_eq!(second.slot, 1);
        assert_eq!(second.retired, None);
        assert_eq!(second.slots.len(), 2);
        let second_session = second.link_session_id.clone();

        let third = service
            .attach_rotated_slot(&attempt, "sgnl://link?third".into(), now_ms())
            .unwrap();
        assert_eq!(third.slot, 2);
        assert_eq!(third.retired, Some(0), "slot 0 is the oldest live code");
        assert_eq!(third.slots.len(), 2, "never more than two live codes");
        let live = service.live_link_slots_for_test();
        assert_eq!(
            live.iter().map(|(slot, _)| *slot).collect::<Vec<_>>(),
            vec![1, 2]
        );
        assert_eq!(live[0].1, second_session);
        assert!(
            service.has_link_session(&first),
            "a retired slot keeps routing (the finish answers LINK_LOST, not              LINK_NOT_FOUND)"
        );
        assert_eq!(
            service.live_slots_uri_for_test(),
            vec![
                "sgnl://link?second".to_string(),
                "sgnl://link?third".to_string()
            ]
        );
    }

    /// Contract 1.286 (§4.272): any live slot finishes the attempt and the
    /// commit happens exactly once; the other codes then replay the same
    /// account instead of minting a second binding.
    #[test]
    fn any_slot_finishes_and_the_attempt_commits_once() {
        let (_temp, mut service) = service();
        let group = crate::DEFAULT_PROXY_GROUP_ID;
        let (attempt, first) = service.plant_link_attempt_for_test(
            "KT",
            Some("engine-attempt-1"),
            crate::link::LINK_SESSION_TTL,
        );
        let second = service
            .attach_rotated_slot(&attempt, "sgnl://link?second".into(), now_ms())
            .unwrap();

        let committed = service
            .complete_link_session_with_id(
                &second.link_session_id,
                "+15555550100",
                group,
                None,
                None,
            )
            .unwrap();
        assert_eq!(service.list_accounts_in_group(group).unwrap().len(), 1);

        // The attempt stays addressable: every code replays the commit.
        let replay = service
            .complete_link_session_with_id(&first, "+15555550100", group, None, None)
            .unwrap();
        assert_eq!(replay.id, committed.id);
        let replay_from_rotated = service
            .complete_link_session_with_id(
                &second.link_session_id,
                "+15555550100",
                group,
                None,
                None,
            )
            .unwrap();
        assert_eq!(replay_from_rotated.id, committed.id);
        assert_eq!(
            service.list_accounts_in_group(group).unwrap().len(),
            1,
            "the attempt committed once"
        );
        // Every code was retired by the commit.
        assert!(service.live_link_slots_for_test().is_empty());
        // A committed attempt has nothing left to rotate.
        let refused = service
            .begin_rotate(&attempt)
            .expect_err("a committed attempt cannot rotate");
        assert!(
            matches!(refused, ServiceError::Api(ref error) if error.code == "INVALID_REQUEST"),
            "got {refused:?}"
        );
        // Cancelling a committed attempt is a no-op that keeps the replay.
        service.cancel_link(&first).unwrap();
        assert_eq!(
            service
                .replay_link_commit(&first)
                .unwrap()
                .map(|row| row.id),
            Some(committed.id)
        );
    }

    /// Contract 1.286 (§4.272): rotation degrades to the single slot on an
    /// engine that never stated a rotate key, and answers the attempt-not-found
    /// code for an attempt this connector does not hold.
    #[test]
    fn rotate_is_gated_by_the_engine_key_and_the_attempt_id() {
        let (_temp, mut service) = service();
        let (attempt, _slot) =
            service.plant_link_attempt_for_test("KT", None, crate::link::LINK_SESSION_TTL);
        assert_eq!(
            service.begin_rotate(&attempt).unwrap(),
            None,
            "no engine rotate key: the caller answers NOT_SUPPORTED and the single slot stays"
        );

        let missing = service
            .begin_rotate("no-such-attempt")
            .expect_err("an unknown attempt answers LINK_ATTEMPT_NOT_FOUND");
        assert!(
            matches!(missing, ServiceError::Api(ref error) if error.code == "LINK_ATTEMPT_NOT_FOUND"),
            "got {missing:?}"
        );

        // An attempt minted by a rotate-capable engine hands its key through.
        let (rotatable, _slot) = service.plant_link_attempt_for_test(
            "KT-2",
            Some("engine-attempt-9"),
            crate::link::LINK_SESSION_TTL,
        );
        assert_eq!(
            service.begin_rotate(&rotatable).unwrap().as_deref(),
            Some("engine-attempt-9")
        );
    }

    /// Contract 1.286 (§4.272): a slot the engine reported lost keeps routing
    /// so finish answers the definite LINK_LOST, while the attempt's other live
    /// slot can still commit.
    #[test]
    fn a_lost_slot_keeps_routing_and_the_other_slot_still_commits() {
        let (_temp, mut service) = service();
        let group = crate::DEFAULT_PROXY_GROUP_ID;
        let (attempt, first) = service.plant_link_attempt_for_test(
            "KT",
            Some("engine-attempt-1"),
            crate::link::LINK_SESSION_TTL,
        );
        let second = service
            .attach_rotated_slot(&attempt, "sgnl://link?second".into(), now_ms())
            .unwrap();
        assert!(service.mark_link_lost(&first));

        let lost = service
            .peek_link_for_finish(&first)
            .expect_err("a lost slot answers LINK_LOST");
        assert!(
            matches!(lost, ServiceError::Api(ref error) if error.code == "LINK_LOST" && error.retryable),
            "got {lost:?}"
        );
        assert!(service.has_link_session(&first), "still routable");
        assert!(service.has_pending_link(), "the second slot is still live");

        let committed = service
            .complete_link_session_with_id(
                &second.link_session_id,
                "+15555550100",
                group,
                None,
                None,
            )
            .unwrap();
        assert_eq!(committed.state, "ready");
    }

    /// Review must-fix (contract 1.286, §4.272): the commit face and the
    /// dispatch face answer differently for a Retired code. A slot the
    /// engine reported dead refuses the commit (LINK_LOST, no account row),
    /// while a slot this connector's own rotation retired still commits — the
    /// engine's success outlives the code — and the attempt then replays that
    /// account from every one of its codes, the retired one included.
    #[test]
    fn the_commit_face_refuses_a_lost_slot_and_accepts_a_retired_one() {
        let (_temp, mut service) = service();
        let group = crate::DEFAULT_PROXY_GROUP_ID;
        let (attempt, first) = service.plant_link_attempt_for_test(
            "KT",
            Some("engine-attempt-1"),
            crate::link::LINK_SESSION_TTL,
        );
        let second = service
            .attach_rotated_slot(&attempt, "sgnl://link?second".into(), now_ms())
            .unwrap();
        let third = service
            .attach_rotated_slot(&attempt, "sgnl://link?third".into(), now_ms())
            .unwrap();
        assert_eq!(third.retired, Some(0), "the rotation retired slot 0");
        // The engine reported the attempt's other early code dead.
        assert!(service.mark_link_lost(&second.link_session_id));

        let lost = service
            .complete_link_session_with_id(
                &second.link_session_id,
                "+15555550100",
                group,
                None,
                None,
            )
            .expect_err("a lost slot never commits");
        assert!(
            matches!(lost, ServiceError::Api(ref error) if error.code == "LINK_LOST" && error.retryable),
            "got {lost:?}"
        );
        assert!(
            service.list_accounts_in_group(group).unwrap().is_empty(),
            "the refused commit writes no account row"
        );

        // The retired slot 0 commits: a rotation dropped the code while the
        // engine was still completing the finish, so the result must not be
        // thrown away by the dispatch gate.
        let committed = service
            .complete_link_session_with_id(&first, "+15555550100", group, None, None)
            .expect("a retired slot still commits the engine's result");
        assert_eq!(service.list_accounts_in_group(group).unwrap().len(), 1);

        // The retired code itself replays the commit (journaled per slot id),
        // and so does the attempt's remaining code.
        for link_session_id in [&first, &third.link_session_id] {
            let replay = service
                .complete_link_session_with_id(link_session_id, "+15555550100", group, None, None)
                .unwrap();
            assert_eq!(replay.id, committed.id, "replay from {link_session_id}");
        }
        assert_eq!(
            service.list_accounts_in_group(group).unwrap().len(),
            1,
            "the attempt committed once"
        );
    }

    /// [KT 适配] §9.10 item 7: a relink of the number whose local-data delete
    /// is still in progress is refused at commit; once the delete completes
    /// the same number links. The official app has no multi-account delete
    /// face, so this gate has no upstream anchor.
    #[test]
    fn relink_is_refused_while_the_same_numbers_delete_is_unfinished() {
        let (_temp, mut service) = service();
        let group = crate::DEFAULT_PROXY_GROUP_ID;
        let account = service
            .sync_accounts_from_numbers(&[("+15555550100".into(), None)], group)
            .unwrap()
            .remove(0);
        let plan = service
            .prepare_account_delete(&account.id, "relink-delete-op")
            .unwrap();
        assert!(matches!(plan, AccountDeletePlan::Dispatch { .. }));

        let started = service
            .begin_link("KT".into(), "sgnl://link?test".into())
            .unwrap();
        let link_session_id = started["linkSessionId"].as_str().unwrap().to_string();
        let refused = service
            .complete_link_session(&link_session_id, "+15555550100", group, None)
            .expect_err("an unfinished delete refuses the relink");
        let ServiceError::Api(error) = refused else {
            panic!("expected an API error");
        };
        assert_eq!(error.code, "ACCOUNT_DELETE_IN_PROGRESS");
        assert!(!error.retryable);
        // The spent session is consumed; a replay is LINK_NOT_FOUND, not a
        // second commit attempt.
        let replay = service
            .complete_link_session(&link_session_id, "+15555550100", group, None)
            .expect_err("the session was consumed");
        assert!(matches!(replay, ServiceError::Api(ref error) if error.code == "LINK_NOT_FOUND"));

        // The explicit delete retry settles the cleanup; then the link lands.
        assert!(
            service
                .complete_account_delete(&account.id, Some("relink-delete-op"))
                .unwrap()
        );
        let started = service
            .begin_link("KT".into(), "sgnl://link?second".into())
            .unwrap();
        let link_session_id = started["linkSessionId"].as_str().unwrap().to_string();
        service
            .complete_link_session(&link_session_id, "+15555550100", group, None)
            .expect("the same number links after the delete settled");
        assert_eq!(service.list_accounts_in_group(group).unwrap().len(), 1);
    }

    /// [KT 适配] §9.10 item 7: an unknown delete outcome is not retryable in
    /// the background (§6.2) — the relink gate asks for an explicit delete
    /// retry and only then lets the number link again.
    #[test]
    fn relink_after_unknown_delete_outcome_asks_for_a_delete_retry() {
        let (_temp, mut service) = service();
        let group = crate::DEFAULT_PROXY_GROUP_ID;
        let account = service
            .sync_accounts_from_numbers(&[("+15555550100".into(), None)], group)
            .unwrap()
            .remove(0);
        let _ = service
            .prepare_account_delete(&account.id, "unknown-delete-op")
            .unwrap();
        service
            .mark_account_delete_unknown("unknown-delete-op")
            .unwrap();

        let started = service
            .begin_link("KT".into(), "sgnl://link?test".into())
            .unwrap();
        let link_session_id = started["linkSessionId"].as_str().unwrap().to_string();
        let refused = service
            .complete_link_session(&link_session_id, "+15555550100", group, None)
            .expect_err("an unknown delete outcome refuses the relink");
        let ServiceError::Api(error) = refused else {
            panic!("expected an API error");
        };
        assert_eq!(error.code, "ACCOUNT_DELETE_OUTCOME_UNKNOWN");
        assert!(!error.retryable);

        assert!(
            service
                .complete_account_delete(&account.id, Some("unknown-delete-op"))
                .unwrap()
        );
        let started = service
            .begin_link("KT".into(), "sgnl://link?after".into())
            .unwrap();
        let link_session_id = started["linkSessionId"].as_str().unwrap().to_string();
        service
            .complete_link_session(&link_session_id, "+15555550100", group, None)
            .expect("the explicit delete retry settled the cleanup");
    }

    /// Per-engine account ceiling (optimization-plan §6.4 M3.3, decision D3):
    /// the eighth account in a group links; the ninth is refused with
    /// ACCOUNT_LIMIT_REACHED naming the group, and the refusal leaves the
    /// store untouched.
    #[test]
    fn eighth_account_links_but_a_ninth_is_refused_at_the_ceiling() {
        let (_temp, mut service) = service();
        let group = crate::DEFAULT_PROXY_GROUP_ID;
        let link_next = |service: &mut ConnectorService| {
            let number = format!(
                "+1556555{:04}",
                service.list_accounts_in_group(group).unwrap().len() + 1
            );
            let started = service
                .begin_link("KT".into(), "sgnl://link?test".into())
                .unwrap();
            let id = started["linkSessionId"].as_str().unwrap().to_string();
            service.complete_link_session(&id, &number, group, None)
        };

        for index in 1..=8 {
            let account =
                link_next(&mut service).unwrap_or_else(|e| panic!("link {index} failed: {e}"));
            assert_eq!(account.proxy_group, group);
        }
        assert_eq!(service.list_accounts_in_group(group).unwrap().len(), 8);
        assert!(service.group_at_account_ceiling(group).unwrap());

        let refused = link_next(&mut service).unwrap_err();
        let ServiceError::Api(api) = refused else {
            panic!("expected an api error at the ceiling");
        };
        assert_eq!(api.code, "ACCOUNT_LIMIT_REACHED");
        assert!(!api.retryable);
        assert!(
            api.message.contains(group),
            "message must name the group: {}",
            api.message
        );
        assert_eq!(service.list_accounts_in_group(group).unwrap().len(), 8);
    }

    /// The ceiling refuses additions, not updates: at a full group, finishing
    /// a link for a number already bound there completes as an upsert instead
    /// of an ACCOUNT_LIMIT_REACHED (store-level guard, M3.3).
    #[test]
    fn relinking_an_existing_number_at_the_ceiling_still_completes() {
        let (_temp, mut service) = service();
        let group = "team-a";
        for index in 1..=8 {
            let started = service
                .begin_link("KT".into(), "sgnl://link?test".into())
                .unwrap();
            let id = started["linkSessionId"].as_str().unwrap().to_string();
            service
                .complete_link_session(&id, &format!("+1556555{index:04}"), group, None)
                .unwrap();
        }

        let started = service
            .begin_link("KT".into(), "sgnl://link?test".into())
            .unwrap();
        let id = started["linkSessionId"].as_str().unwrap().to_string();
        let relinked = service
            .complete_link_session(&id, "+15565550008", group, None)
            .expect("relink of an existing number is an update, not an addition");
        assert_eq!(relinked.proxy_group, group);
        assert_eq!(service.list_accounts_in_group(group).unwrap().len(), 8);
    }

    /// Contract 1.142 (§4.138): the finish path persists the engine's own-ACI
    /// answer in the canonical dashed lowercase form; an absent or unparseable
    /// face is honest absence — no error, no invention, and no erasure of a
    /// stored identity (the §4.24 posture: the connector never stands in for
    /// the engine on identity facts).
    #[test]
    fn complete_link_session_persists_the_answered_aci_and_absence_is_honest() {
        let (_temp, mut service) = service();
        let group = crate::DEFAULT_PROXY_GROUP_ID;

        // A face with the key: bare uppercase hex lands dashed lowercase, and
        // the summary read back after the write already carries it.
        let started = service
            .begin_link("KT".into(), "sgnl://link?test".into())
            .unwrap();
        let id = started["linkSessionId"].as_str().unwrap().to_string();
        let linked = service
            .complete_link_session(
                &id,
                "+15555550100",
                group,
                Some("5A1CC2CDB36453D48D711EC62B8EB72B"),
            )
            .unwrap();
        assert_eq!(
            linked.aci.as_deref(),
            Some("5a1cc2cd-b364-53d4-8d71-1ec62b8eb72b")
        );

        // A re-link whose face carries no key keeps the stored identity.
        let started = service
            .begin_link("KT".into(), "sgnl://link?test".into())
            .unwrap();
        let id = started["linkSessionId"].as_str().unwrap().to_string();
        let relinked = service
            .complete_link_session(&id, "+15555550100", group, None)
            .unwrap();
        assert_eq!(
            relinked.aci.as_deref(),
            Some("5a1cc2cd-b364-53d4-8d71-1ec62b8eb72b")
        );

        // A garbage face is not an ACI: it is not persisted, does not fail
        // the finish, and does not erase the stored identity.
        let started = service
            .begin_link("KT".into(), "sgnl://link?test".into())
            .unwrap();
        let id = started["linkSessionId"].as_str().unwrap().to_string();
        let garbage = service
            .complete_link_session(&id, "+15555550100", group, Some("not-a-uuid"))
            .unwrap();
        assert_eq!(
            garbage.aci.as_deref(),
            Some("5a1cc2cd-b364-53d4-8d71-1ec62b8eb72b")
        );
    }

    /// Contract 1.142 (§4.138): the account-sync entries each carry their own
    /// engine answer — canonicalized and persisted per account — and an
    /// entry without the key stays absent while the sibling identities
    /// survive (per-account attribution, never a shared guess).
    #[test]
    fn sync_accounts_persists_each_entry_own_aci() {
        let (_temp, service) = service();
        let group = crate::DEFAULT_PROXY_GROUP_ID;

        let first = service
            .sync_accounts_from_numbers(
                &[(
                    "+15555550100".into(),
                    Some("5A1CC2CD-B364-53D4-8D71-1EC62B8EB72B".into()),
                )],
                group,
            )
            .unwrap();
        assert_eq!(first.len(), 1);
        assert_eq!(
            first[0].aci.as_deref(),
            Some("5a1cc2cd-b364-53d4-8d71-1ec62b8eb72b")
        );

        let second = service
            .sync_accounts_from_numbers(
                &[(
                    "+15555550101".into(),
                    Some("18e2e00b2ac755eca25dd5646a80c042".into()),
                )],
                group,
            )
            .unwrap();
        assert_eq!(second.len(), 2);
        // Both identities ride — the freshly answered one and the earlier
        // answer the second sync's read-back must not have disturbed.
        assert!(
            second
                .iter()
                .any(|account| account.aci.as_deref()
                    == Some("18e2e00b-2ac7-55ec-a25d-d5646a80c042"))
        );
        assert!(
            second
                .iter()
                .any(|account| account.aci.as_deref()
                    == Some("5a1cc2cd-b364-53d4-8d71-1ec62b8eb72b"))
        );

        // An entry without the key stays absent; the earlier identities
        // survive the group-wide read.
        let third = service
            .sync_accounts_from_numbers(&[("+15555550102".into(), None)], group)
            .unwrap();
        assert_eq!(third.len(), 3);
        assert_eq!(
            third.iter().filter(|account| account.aci.is_some()).count(),
            2
        );
    }

    /// Contract 1.194 (§4.194): the engine's live capability answer rides the
    /// matching account summary and stays absent for an account the engine did
    /// not answer for — the desktop gate reads `=== true`, so absent is the
    /// honest unknown rather than a fabricated false.
    #[test]
    fn sync_accounts_carries_the_live_capability_bits_per_account() {
        let (_temp, service) = service();
        let group = crate::DEFAULT_PROXY_GROUP_ID;

        let rows = service
            .sync_accounts_from_numbers_with_capabilities(
                &[
                    (
                        "+15555550100".into(),
                        None,
                        Some(crate::store::AccountCapabilities {
                            attachment_backfill: true,
                        }),
                    ),
                    ("+15555550101".into(), None, None),
                ],
                group,
            )
            .unwrap();
        assert_eq!(rows.len(), 2);
        let with_caps = rows
            .iter()
            .find(|row| row.masked_address.ends_with("00"))
            .expect("first account");
        assert_eq!(
            with_caps.capabilities,
            Some(crate::store::AccountCapabilities {
                attachment_backfill: true
            })
        );
        let without_caps = rows
            .iter()
            .find(|row| row.masked_address.ends_with("01"))
            .expect("second account");
        assert_eq!(without_caps.capabilities, None);
    }

    #[test]
    fn active_link_is_rejected_before_requesting_another_upstream_uri() {
        let (_temp, mut service) = service();
        service
            .begin_link("KT".into(), "sgnl://link?test".into())
            .unwrap();

        assert!(matches!(
            service.ensure_link_available(),
            Err(ServiceError::Api(_))
        ));
    }

    /// An expired session answers the definite LINK_EXPIRED (retryable=false,
    /// same class as every other definite finish failure) and is consumed by
    /// that answer; only afterwards does the id read back as LINK_NOT_FOUND.
    #[test]
    fn expired_finish_answers_link_expired_once_then_reports_not_found() {
        let (_temp, mut service) = service();
        let link_session_id = service.plant_link_session_for_test("KT-Expired", Duration::ZERO);

        let error = service.peek_link_for_finish(&link_session_id).unwrap_err();
        let ServiceError::Api(api) = error else {
            panic!("expected an api error for the expired finish");
        };
        assert_eq!(api.code, "LINK_EXPIRED");
        assert!(!api.retryable);

        let again = service.peek_link_for_finish(&link_session_id).unwrap_err();
        let ServiceError::Api(api) = again else {
            panic!("expected an api error for the consumed session");
        };
        assert_eq!(api.code, "LINK_NOT_FOUND");

        // begin_link over an expired session must also succeed (expiry frees
        // the slot), keeping one deterministic terminal state per session.
        service
            .begin_link("KT-Again".into(), "sgnl://link?next".into())
            .expect("an expired session must not block a fresh link");
    }

    /// QR B1 (issue #951): a lost session is terminal but stays addressable.
    /// It no longer suppresses the watchdog (has_pending_link=false), a
    /// finish for its id answers the definite LINK_LOST (retryable=true), and
    /// the next begin_link replaces it instead of answering LINK_IN_PROGRESS.
    #[test]
    fn lost_link_session_is_addressable_but_never_blocks_a_fresh_link() {
        let (_temp, mut service) = service();
        let started = service
            .begin_link("KT-Lost".into(), "sgnl://link?lost".into())
            .unwrap();
        let lost_id = started["linkSessionId"].as_str().unwrap().to_string();
        assert!(
            service.has_pending_link(),
            "the live QR suppresses the watchdog"
        );

        assert!(service.mark_link_lost(&lost_id));
        let session = service.link.as_ref().expect("the lost session stays");
        assert_eq!(session.state, crate::link::LinkSessionState::Lost);
        assert!(session.lost_at.is_some(), "the loss instant is recorded");
        assert!(
            !service.has_pending_link(),
            "a lost session must not suppress the watchdog"
        );
        assert!(
            service.has_link_session(&lost_id),
            "router attribution must survive loss so finish answers LINK_LOST"
        );

        let error = service.peek_link_for_finish(&lost_id).unwrap_err();
        let ServiceError::Api(api) = error else {
            panic!("expected the definite LINK_LOST api error");
        };
        assert_eq!(api.code, "LINK_LOST");
        assert!(api.retryable, "a fresh link.start is the remedy");

        // The next begin replaces the lost session (ensure_link_available is
        // the supervisor's pre-mint gate and must agree).
        service
            .ensure_link_available()
            .expect("a lost session does not block the next start");
        let next = service
            .begin_link("KT-Next".into(), "sgnl://link?next".into())
            .expect("a lost session must not answer LINK_IN_PROGRESS");
        let next_id = next["linkSessionId"].as_str().unwrap().to_string();
        assert_ne!(next_id, lost_id);
        assert!(service.has_pending_link());
        assert!(!service.has_link_session(&lost_id));
        assert!(!service.mark_link_lost("no-such-session"));
    }

    /// The finish budget (370 s) outlives the advertised QR lifetime (300 s),
    /// so an in-flight finish pins the session: a phone approval that lands
    /// after the QR's own lifetime must still commit — the engine already
    /// linked the device, and LINK_EXPIRED would strand a real link. The
    /// advertised `expiresAt` is untouched; only the in-memory deadline moves.
    #[test]
    fn an_in_flight_finish_pins_the_link_session_past_the_qr_lifetime() {
        let (_temp, mut service) = service();
        let started = service
            .begin_link("KT-Pin".into(), "sgnl://link?pin".into())
            .unwrap();
        let link_session_id = started["linkSessionId"].as_str().unwrap().to_string();
        let advertised = started["expiresAt"].as_u64().unwrap();
        assert_eq!(
            service.link_session_deadline_for_test(&link_session_id),
            Some(advertised),
            "begin_link advertises the session's own deadline"
        );

        let budget = Duration::from_secs(370);
        service
            .pin_link_for_finish(&link_session_id, budget)
            .expect("a live session is pinnable");
        let pinned = service
            .link_session_deadline_for_test(&link_session_id)
            .expect("the pinned session is still the active one");
        assert!(
            pinned > advertised,
            "the finish window must outlive the advertised QR lifetime: {pinned} vs {advertised}"
        );
        assert!(
            pinned - advertised >= Duration::from_secs(60).as_millis() as u64,
            "the pin covers the finish budget, not a token extension"
        );

        // The commit still lands: pinning never consumes or re-keys the
        // session.
        let account = service
            .complete_link_session(
                &link_session_id,
                "+15555550100",
                crate::DEFAULT_PROXY_GROUP_ID,
                None,
            )
            .expect("a pinned session commits");
        assert_eq!(account.state, "ready");
        assert!(!account.id.is_empty());

        // Unknown ids keep their own definite answer; an expired session is
        // refused before anything is extended (the pin is not a resurrection).
        let missing = service
            .pin_link_for_finish("no-such-session", budget)
            .unwrap_err();
        let ServiceError::Api(api) = missing else {
            panic!("expected an api error for an unknown session");
        };
        assert_eq!(api.code, "LINK_NOT_FOUND");

        let expired = service.plant_link_session_for_test("KT-Expired-Pin", Duration::ZERO);
        let error = service.pin_link_for_finish(&expired, budget).unwrap_err();
        let ServiceError::Api(api) = error else {
            panic!("expected an api error for an expired session");
        };
        assert_eq!(api.code, "LINK_EXPIRED");
    }

    #[test]
    fn deleting_an_account_does_not_cancel_another_session_link() {
        let (_temp, mut service) = service();
        let account = service
            .sync_accounts_from_numbers(
                &[("+15555550100".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap()
            .remove(0);
        let started = service
            .begin_link("KT-B".into(), "sgnl://link?second".into())
            .unwrap();
        let link_session_id = started["linkSessionId"].as_str().unwrap().to_string();

        assert!(
            service
                .store_ref()
                .delete_account_cascade(&account.id)
                .unwrap()
        );
        assert!(
            !service
                .store_ref()
                .delete_account_cascade(&account.id)
                .unwrap()
        );
        assert!(service.cancel_link(&link_session_id).is_ok());
    }

    /// Contract 1.21: marking an unlinked device persists `device_unlinked`
    /// and surfaces an account.changed event; unknown numbers are a no-op.
    #[test]
    fn mark_account_device_unlinked_persists_and_emits_account_changed() {
        let (_temp, service) = service();
        let group = crate::DEFAULT_PROXY_GROUP_ID;
        let account = service
            .sync_accounts_from_numbers(&[("+15555550100".into(), None)], group)
            .unwrap()
            .remove(0);

        let events = service
            .mark_account_device_unlinked("+15555550100")
            .unwrap();
        assert_eq!(events.len(), 1);
        let HostSideEvent::AccountChanged(changed) = &events[0] else {
            panic!("expected an account.changed event");
        };
        assert_eq!(changed.id, account.id);
        assert_eq!(changed.state, "device_unlinked");

        let listed = service
            .list_accounts_in_group(group)
            .unwrap()
            .into_iter()
            .find(|item| item.id == account.id)
            .unwrap();
        assert_eq!(listed.state, "device_unlinked");

        // A number with no account row is a silent no-op.
        assert!(
            service
                .mark_account_device_unlinked("+15555559999")
                .unwrap()
                .is_empty()
        );
    }

    /// Runtime state authority: a 401 during an active link/re-key window is
    /// provisioning noise; the terminal write is deferred until the window
    /// closes.
    #[test]
    fn account_unlink_write_is_deferred_while_a_link_session_is_pending() {
        let (_temp, mut service) = service();
        let link = service.plant_link_session_for_test("KT Desktop", Duration::from_secs(60));
        assert!(!service.should_persist_account_unlink());

        service.cancel_link(&link).unwrap();
        assert!(service.should_persist_account_unlink());
    }

    /// The wire error for a rejected credential is ACCOUNT_UNLINKED
    /// (retryable=false) — distinct from the generic retryable upstream
    /// error, so hosts can distinguish "device was unlinked" from noise.
    #[test]
    fn unauthorized_engine_errors_map_to_account_unlinked() {
        let api = ServiceError::Engine(EngineError::Unauthorized).into_api();
        assert_eq!(api.code, "ACCOUNT_UNLINKED");
        assert!(!api.retryable);
    }

    /// Send-chain transport families (contract 1.99, §4.80) joined by the
    /// identity gate (contract 1.114, §4.95): the engine classes map onto
    /// their host codes with the contract-fixed retryability — the
    /// server-unavailable family may succeed on a later attempt, while the
    /// rate-limit, proof-challenge, and identity-trust faces are per-attempt
    /// answers the caller re-drives (a mutating send is never auto-retried;
    /// the flag is display-side only).
    #[test]
    fn send_chain_transport_errors_map_to_send_error_codes() {
        for (error, code, retryable) in [
            (
                EngineError::RateLimited {
                    retry_after_secs: None,
                },
                "SEND_RATE_LIMITED",
                false,
            ),
            (EngineError::ProofRequired, "SEND_PROOF_REQUIRED", false),
            (
                EngineError::ServerUnavailable,
                "SEND_SERVER_UNAVAILABLE",
                true,
            ),
            (
                EngineError::IdentityUnverified,
                "SEND_IDENTITY_UNVERIFIED",
                false,
            ),
        ] {
            let api = ServiceError::Engine(error).into_api();
            assert_eq!(api.code, code);
            assert_eq!(api.retryable, retryable, "{code} retryable face");
            assert!(api.data.is_none(), "{code} carries no data object");
        }
    }

    /// Contract 1.285 §4.269: the engine's resource faces map onto their own
    /// host codes with the contract-fixed retryability — the two busy faces
    /// proved the request never executed (retryable), and the attachment
    /// budget face is never retried automatically. The read-only dispatch
    /// timeout keeps ENGINE_TIMEOUT; a mutating cancellation folds to the
    /// pre-existing unknown outcome before it reaches this mapping (asserted
    /// below), so the send row settles unknown. The engine's `data`
    /// object rides verbatim when present; the content-free face answers
    /// without one, and the family flag always wins over the `with_data`
    /// derivation (the engine's advisory `retryable` bit stays inside
    /// `data`).
    #[test]
    fn engine_resource_faces_map_to_structured_codes() {
        for (error, code, retryable) in [
            (EngineError::EngineBusy { data: None }, "ENGINE_BUSY", true),
            (
                EngineError::EngineRequestTimeout { data: None },
                "ENGINE_TIMEOUT",
                false,
            ),
            (
                EngineError::AttachmentBusy { data: None },
                "ATTACHMENT_BUSY",
                true,
            ),
            (
                EngineError::AttachmentBudget { data: None },
                "ATTACHMENT_BUDGET",
                false,
            ),
        ] {
            let api = ServiceError::Engine(error).into_api();
            assert_eq!(api.code, code);
            assert_eq!(api.retryable, retryable, "{code} retryable face");
            assert!(api.data.is_none(), "{code} stays content-free without data");
        }

        // The dispatch payloads ride verbatim.
        let busy_data = json!({
            "reason": "ENGINE_BUSY",
            "retryable": true,
            "inFlightLimit": 8
        });
        let api = ServiceError::Engine(EngineError::EngineBusy {
            data: Some(busy_data.clone()),
        })
        .into_api();
        assert_eq!(api.code, "ENGINE_BUSY");
        assert!(api.retryable);
        assert_eq!(api.data, Some(busy_data));

        let timeout_data = json!({
            "reason": "REQUEST_TIMEOUT",
            "retryable": false,
            "timeoutMs": 60000
        });
        let api = ServiceError::Engine(EngineError::EngineRequestTimeout {
            data: Some(timeout_data.clone()),
        })
        .into_api();
        assert_eq!(api.code, "ENGINE_TIMEOUT");
        assert!(
            !api.retryable,
            "the read-only dispatch was cancelled; never auto-retried"
        );
        assert_eq!(api.data, Some(timeout_data));

        // The send-chain dispatch-timeout face never reaches ENGINE_TIMEOUT:
        // the classifier folds a mutating cancellation to the existing
        // unknown outcome, whose host answer stays SEND_OUTCOME_UNKNOWN and
        // is never auto-retried.
        let api = ServiceError::Engine(EngineError::UnknownOutcome).into_api();
        assert_eq!((api.code, api.retryable), ("SEND_OUTCOME_UNKNOWN", false));
        assert!(api.data.is_none(), "the unknown face is content-free");

        // A data-carrying attachment refusal keeps its facts; the fixed
        // family flag is not swayed by the advisory bit inside them.
        let api = ServiceError::Engine(EngineError::AttachmentBusy {
            data: Some(json!({ "retryable": false, "slots": 2 })),
        })
        .into_api();
        assert_eq!(api.code, "ATTACHMENT_BUSY");
        assert!(api.retryable, "nothing was delivered, a retry is safe");
        assert_eq!(api.data, Some(json!({ "retryable": false, "slots": 2 })));

        let api = ServiceError::Engine(EngineError::AttachmentBudget {
            data: Some(json!({ "retryable": true, "budgetBytes": 335544320u64 })),
        })
        .into_api();
        assert_eq!(api.code, "ATTACHMENT_BUDGET");
        assert!(!api.retryable, "the same batch can stay over budget");
        assert_eq!(
            api.data,
            Some(json!({ "retryable": true, "budgetBytes": 335544320u64 }))
        );

        // No regression on the pre-1.285 faces: the generic upstream answer
        // and the connector's own deadline keep their codes and flags.
        let api = ServiceError::Engine(EngineError::Upstream {
            cause: None,
            code: Some(-32603),
        })
        .into_api();
        assert_eq!((api.code, api.retryable), ("UPSTREAM_ERROR", true));
        let api = ServiceError::Engine(EngineError::Timeout).into_api();
        assert_eq!((api.code, api.retryable), ("UPSTREAM_TIMEOUT", true));
    }

    /// Structured engine error mapping (contract 1.36, §4.32/§4.33): each
    /// allowlisted engine code maps to the same-named connector code with
    /// the contract-fixed retryability; the mapping is total over the
    /// engine.rs allowlist, so no allowlisted code can fall through to the
    /// generic answer.
    #[test]
    fn structured_engine_errors_map_to_same_named_connector_codes() {
        let deterministic = [
            "STICKER_PACK_KEY_INVALID",
            "STICKER_IMAGE_TOO_LARGE",
            "CONVERSATION_NOT_RESOLVED",
            // §4.47: the honest no-avatar answer and the deterministic
            // over-cap refusal are answers, not failures.
            "AVATAR_UNAVAILABLE",
            "AVATAR_TOO_LARGE",
        ];
        for code in deterministic {
            let api =
                ServiceError::Engine(EngineError::UpstreamCode { code, data: None }).into_api();
            assert_eq!(api.code, code, "{code}");
            assert!(!api.retryable, "{code}");
        }
        let retryable = [
            "STICKER_PACK_FETCH_FAILED",
            "STICKER_PACK_MALFORMED",
            "STORAGE_UNAVAILABLE",
            "STORAGE_WRITE_FAILED",
            "STORAGE_READ_FAILED",
            // §4.47: a network/download/decrypt failure may succeed on a
            // later attempt.
            "AVATAR_FETCH_FAILED",
            // QR B1: the dead QR is repaired by a fresh link.start, never a
            // blind finish retry; retryable=true is the start-over face.
            "LINK_LOST",
        ];
        for code in retryable {
            let api =
                ServiceError::Engine(EngineError::UpstreamCode { code, data: None }).into_api();
            assert_eq!(api.code, code, "{code}");
            assert!(api.retryable, "{code}");
        }
        // The two allowlists must stay in lockstep: every code the engine
        // layer can emit must map to itself here.
        for code in crate::engine::ENGINE_STRUCTURED_ERROR_CODES_FOR_TESTS {
            let api =
                ServiceError::Engine(EngineError::UpstreamCode { code, data: None }).into_api();
            assert_eq!(api.code, *code, "unmapped engine code {code}");
        }
        // The username write face (contract 1.75, §4.66): the retryability
        // faces are part of the contract — taken/reservation-gone are
        // deterministic (a new name / a fresh reserve is the only way
        // forward), rate-limited/server-failed may succeed on a later
        // attempt.
        for (code, retryable) in [
            ("USERNAME_TAKEN", false),
            ("USERNAME_RESERVATION_GONE", false),
            ("USERNAME_RATE_LIMITED", true),
            ("USERNAME_SERVER_FAILED", true),
        ] {
            let api =
                ServiceError::Engine(EngineError::UpstreamCode { code, data: None }).into_api();
            assert_eq!(api.code, code);
            assert_eq!(api.retryable, retryable, "{code} retryable face");
        }
        // The §4.69 cloud-restore families (contract 1.83): the contract-fixed
        // retryability per family — three deterministic refusals, transport/
        // download retriable, decrypt/export terminal.
        for (code, retryable) in [
            ("BACKUP_NOT_PROVISIONED", false),
            ("BACKUP_AUTH_FAILED", false),
            ("BACKUP_RUNNING", false),
            ("BACKUP_TRANSPORT_FAILED", true),
            ("BACKUP_DOWNLOAD_FAILED", true),
            ("BACKUP_DECRYPT_FAILED", false),
            ("BACKUP_EXPORT_FAILED", false),
        ] {
            let api =
                ServiceError::Engine(EngineError::UpstreamCode { code, data: None }).into_api();
            assert_eq!(api.code, code, "{code}");
            assert_eq!(api.retryable, retryable, "{code} retryable face");
            assert!(api.data.is_none(), "{code} stays content-free without data");
        }
        // The §4.103 device-plane faces (contract 1.122): the server-rejection
        // family is deterministic (retryable=false) and the transport family
        // may succeed on a later attempt.
        for (code, retryable) in [("DEVICES_FAILED", false), ("DEVICES_UNAVAILABLE", true)] {
            let api =
                ServiceError::Engine(EngineError::UpstreamCode { code, data: None }).into_api();
            assert_eq!(api.code, code, "{code}");
            assert_eq!(api.retryable, retryable, "{code} retryable face");
            assert!(api.data.is_none(), "{code} stays content-free without data");
        }
    }

    /// §4.103 device faces (contract 1.122): DEVICES_FAILED passes the
    /// engine's `data.status` verbatim (the honest HTTP pass-through, the
    /// CALL_CREDENTIALS_FAILED channel); without data it stays content-free.
    #[test]
    fn device_failed_carries_the_server_status_verbatim() {
        let api = ServiceError::Engine(EngineError::UpstreamCode {
            code: "DEVICES_FAILED",
            data: Some(json!({ "status": 409 })),
        })
        .into_api();
        assert_eq!(api.code, "DEVICES_FAILED");
        assert!(!api.retryable);
        assert_eq!(api.data, Some(json!({ "status": 409 })));
        let api = ServiceError::Engine(EngineError::UpstreamCode {
            code: "DEVICES_FAILED",
            data: None,
        })
        .into_api();
        assert_eq!(api.code, "DEVICES_FAILED");
        assert!(api.data.is_none());
    }

    /// §4.103 projection (contract 1.122): entries ride in order under the
    /// 32-entry cap; a non-numeric deviceId drops the entry; a projected
    /// deviceId of 0 fails INVALID_REQUEST; a missing/non-array devices is a
    /// protocol defect; the optional server fields stay optional.
    #[test]
    fn device_list_projection_caps_drops_and_refuses() {
        let result = device_list_from_engine(&json!({
            "devices": [
                { "deviceId": 1, "name": null, "registrationId": 111,
                  "lastSeenMs": 1728000000000u64, "createdAtCiphertext": "abc" },
                { "deviceId": "2", "name": "ghost" },
                { "deviceId": 3, "name": "Linked" },
            ]
        }))
        .unwrap();
        assert_eq!(result.devices.len(), 2);
        assert_eq!(result.devices[0].device_id, 1);
        assert_eq!(result.devices[0].name, None);
        assert_eq!(result.devices[0].registration_id, Some(111));
        assert_eq!(result.devices[0].last_seen_ms, Some(1728000000000));
        assert_eq!(
            result.devices[0].created_at_ciphertext.as_deref(),
            Some("abc")
        );
        assert_eq!(result.devices[1].device_id, 3);
        assert_eq!(result.devices[1].name.as_deref(), Some("Linked"));
        assert!(result.devices[1].registration_id.is_none());

        let zero = device_list_from_engine(&json!({ "devices": [{ "deviceId": 0 }] }))
            .err()
            .unwrap();
        assert_eq!(zero.into_api().code, "INVALID_REQUEST");
        assert!(device_list_from_engine(&json!({})).is_err());
        assert!(device_list_from_engine(&json!({ "devices": "no" })).is_err());

        let over: Vec<Value> = (1..=40).map(|id| json!({ "deviceId": id })).collect();
        let capped = device_list_from_engine(&json!({ "devices": over })).unwrap();
        assert_eq!(capped.devices.len(), MAX_DEVICE_LIST_ENTRIES);
        assert_eq!(capped.devices[31].device_id, 32);
    }

    /// §4.104 migrate prepare (contract 1.123): the local shape ladder —
    /// the legacy id's base64 gate, the non-empty title bound, the roster
    /// bounds — and the upstream frame (optional keys absent stay absent,
    /// the avatar tri-state rides). The result parse answers the engine's
    /// {groupId, revision}; a protocol-shaped defect answers Protocol.
    #[test]
    fn group_migrate_prepare_ladder_and_result_parse() {
        let (_temp, mut service) = service();
        let (account, _direct) = linked_account_and_conversation(&mut service);
        let params = |group_id: &str, members: Vec<String>| GroupsMigrateParams {
            account_id: account.id.clone(),
            group_id: group_id.to_string(),
            title: None,
            expiration: None,
            avatar: AvatarUpdate::Keep,
            members,
        };

        let upstream = service
            .prepare_groups_migrate(&params(
                "MTIzNDU2Nzg5MGFiY2RlZg==",
                vec!["+15555550101".into()],
            ))
            .unwrap();
        assert_eq!(upstream["account"], "+15555550100");
        assert_eq!(upstream["groupId"], "MTIzNDU2Nzg5MGFiY2RlZg==");
        assert!(upstream.get("title").is_none());
        assert!(upstream.get("expiration").is_none());
        assert!(upstream.get("avatar").is_none());
        assert_eq!(upstream["members"], json!(["+15555550101"]));

        let error = service
            .prepare_groups_migrate(&params("not base64!!", vec!["+15555550101".into()]))
            .unwrap_err();
        assert_eq!(error.into_api().code, "INVALID_REQUEST");
        let error = service
            .prepare_groups_migrate(&params("", vec!["+15555550101".into()]))
            .unwrap_err();
        assert_eq!(error.into_api().code, "INVALID_REQUEST");
        let error = service
            .prepare_groups_migrate(&params("MTIzNDU2Nzg5MGFiY2RlZg==", vec![]))
            .unwrap_err();
        assert_eq!(error.into_api().code, "INVALID_REQUEST");
        let error = service
            .prepare_groups_migrate(&params(
                "MTIzNDU2Nzg5MGFiY2RlZg==",
                vec!["+15555550101".into(); MAX_GROUP_MEMBERS + 1],
            ))
            .unwrap_err();
        assert_eq!(error.into_api().code, "INVALID_REQUEST");

        let result = group_migrate_result_from_engine(&json!({
            "groupId": "YWJjZGVmZ2hpamtsbW5vcHFyc3R1dnd4",
            "revision": 3
        }))
        .unwrap();
        assert_eq!(result.group_id, "YWJjZGVmZ2hpamtsbW5vcHFyc3R1dnd4");
        assert_eq!(result.revision, 3);
        assert!(group_migrate_result_from_engine(&json!({ "groupId": "x" })).is_err());
        assert!(group_migrate_result_from_engine(&json!({ "revision": 3 })).is_err());

        // The server-rejection family (contract 1.123): deterministic,
        // data.status rides verbatim when the engine carried one.
        let api = ServiceError::Engine(EngineError::UpstreamCode {
            code: "GROUP_MIGRATION_FAILED",
            data: Some(json!({ "status": 409 })),
        })
        .into_api();
        assert_eq!(api.code, "GROUP_MIGRATION_FAILED");
        assert!(!api.retryable);
        assert_eq!(api.data, Some(json!({ "status": 409 })));
    }

    /// §4.107 create prepare (contract 1.126): the local shape ladder —
    /// the required non-empty title bound, the optional roster's bounds
    /// (an explicit empty array is the engine's own refusal, mirrored) —
    /// and the upstream frame (optional keys absent stay absent, the avatar
    /// tri-state rides). The result parse answers the engine's
    /// {groupId, revision}; a protocol-shaped defect answers Protocol.
    #[test]
    fn group_create_prepare_ladder_and_result_parse() {
        let (_temp, mut service) = service();
        let (account, _direct) = linked_account_and_conversation(&mut service);
        let params = |title: &str, members: Option<Vec<String>>| GroupsCreateParams {
            account_id: account.id.clone(),
            title: title.to_string(),
            expiration: None,
            avatar: AvatarUpdate::Keep,
            members,
        };

        let upstream = service
            .prepare_groups_create(&params("kt group", Some(vec!["+15555550101".into()])))
            .unwrap();
        assert_eq!(upstream["account"], "+15555550100");
        assert_eq!(upstream["title"], "kt group");
        assert!(upstream.get("expiration").is_none());
        assert!(upstream.get("avatar").is_none());
        assert_eq!(upstream["members"], json!(["+15555550101"]));

        let bare = service
            .prepare_groups_create(&params("kt group", None))
            .unwrap();
        assert!(bare.get("members").is_none());

        let error = service
            .prepare_groups_create(&params("", Some(vec!["+15555550101".into()])))
            .unwrap_err();
        assert_eq!(error.into_api().code, "INVALID_REQUEST");
        let error = service
            .prepare_groups_create(&params(&"x".repeat(257), None))
            .unwrap_err();
        assert_eq!(error.into_api().code, "INVALID_REQUEST");
        let error = service
            .prepare_groups_create(&params("kt group", Some(vec![])))
            .unwrap_err();
        assert_eq!(error.into_api().code, "INVALID_REQUEST");
        let error = service
            .prepare_groups_create(&params(
                "kt group",
                Some(vec!["+15555550101".into(); MAX_GROUP_MEMBERS + 1]),
            ))
            .unwrap_err();
        assert_eq!(error.into_api().code, "INVALID_REQUEST");

        let result = group_create_result_from_engine(&json!({
            "groupId": "YWJjZGVmZ2hpamtsbW5vcHFyc3R1dnd4",
            "revision": 0
        }))
        .unwrap();
        assert_eq!(result.group_id, "YWJjZGVmZ2hpamtsbW5vcHFyc3R1dnd4");
        assert_eq!(result.revision, 0);
        assert!(group_create_result_from_engine(&json!({ "groupId": "x" })).is_err());
        assert!(group_create_result_from_engine(&json!({ "revision": 3 })).is_err());

        // The server-rejection family (contract 1.126): deterministic,
        // data.status rides verbatim when the engine carried one.
        let api = ServiceError::Engine(EngineError::UpstreamCode {
            code: "GROUP_CREATE_FAILED",
            data: Some(json!({ "status": 400 })),
        })
        .into_api();
        assert_eq!(api.code, "GROUP_CREATE_FAILED");
        assert!(!api.retryable);
        assert_eq!(api.data, Some(json!({ "status": 400 })));
    }

    /// §4.105 contact-send prepare (contract 1.124): the card ladder — the
    /// all-empty refusal, the type vocabularies (number/email four words,
    /// address three), the entry and scalar bounds, the avatar data-URI
    /// gate — and the leg routing (the direct row's peer reference, the
    /// group row's groupId; the calls.sendSignal addressing precedent),
    /// with the empty-string organization folding out of the frame.
    #[test]
    fn contact_send_prepare_ladder_and_leg_routing() {
        let (_temp, mut service) = service();
        let (account, direct) = linked_account_and_conversation(&mut service);
        let group = service
            .store_ref()
            .ensure_conversation(&account.id, "group", "ZmFrZS1ncm91cC0x", "Fixture Group")
            .unwrap();
        let params_for =
            |conversation_id: String, contact: ContactPayload| MessagesSendContactParams {
                account_id: account.id.clone(),
                conversation_id,
                contact,
            };
        let full_card = ContactPayload {
            name: Some(ContactName {
                given_name: Some("Ada".into()),
                ..Default::default()
            }),
            number: vec![ContactField {
                value: "+15551230000".into(),
                r#type: Some("MOBILE".into()),
                label: Some("cell".into()),
            }],
            email: vec![ContactField {
                value: "ada@example.test".into(),
                r#type: Some("WORK".into()),
                label: None,
            }],
            address: vec![ContactAddress {
                r#type: Some("HOME".into()),
                city: Some("London".into()),
                ..Default::default()
            }],
            organization: Some("".into()),
            avatar: Some("data:image/png;base64,iVBORw0KGgoAAAANSUhEUg==".into()),
        };

        // The direct leg: the row's peer reference is the recipient; the
        // empty-string organization is the official falsy-absent and drops.
        let upstream = service
            .prepare_messages_send_contact(&params_for(direct.id.clone(), full_card.clone()))
            .unwrap();
        assert_eq!(upstream["account"], "+15555550100");
        assert_eq!(upstream["recipient"], direct.peer_key);
        assert!(upstream.get("groupId").is_none());
        assert_eq!(upstream["contact"]["name"]["givenName"], "Ada");
        assert_eq!(upstream["contact"]["number"][0]["type"], "MOBILE");
        assert_eq!(upstream["contact"]["email"][0]["value"], "ada@example.test");
        assert_eq!(upstream["contact"]["address"][0]["city"], "London");
        assert_eq!(
            upstream["contact"]["avatar"],
            "data:image/png;base64,iVBORw0KGgoAAAANSUhEUg=="
        );
        assert!(upstream["contact"].get("organization").is_none());

        // The group leg: the row's peer reference is the groupId.
        let upstream = service
            .prepare_messages_send_contact(&params_for(group.id.clone(), full_card))
            .unwrap();
        assert_eq!(upstream["groupId"], "ZmFrZS1ncm91cC0x");
        assert!(upstream.get("recipient").is_none());

        // The ladder: every refusal lands before any upstream frame.
        let refused = |contact: ContactPayload| {
            service
                .prepare_messages_send_contact(&params_for(direct.id.clone(), contact))
                .unwrap_err()
                .into_api()
                .code
        };
        let field = |value: &str, kind: Option<&str>| ContactField {
            value: value.into(),
            r#type: kind.map(Into::into),
            label: None,
        };
        assert_eq!(refused(ContactPayload::default()), "INVALID_REQUEST");
        assert_eq!(
            refused(ContactPayload {
                organization: Some("".into()),
                ..Default::default()
            }),
            "INVALID_REQUEST"
        );
        assert_eq!(
            refused(ContactPayload {
                number: vec![field("+1", Some("CELL"))],
                ..Default::default()
            }),
            "INVALID_REQUEST"
        );
        assert_eq!(
            refused(ContactPayload {
                address: vec![ContactAddress {
                    r#type: Some("MOBILE".into()),
                    city: Some("x".into()),
                    ..Default::default()
                }],
                ..Default::default()
            }),
            "INVALID_REQUEST"
        );
        assert_eq!(
            refused(ContactPayload {
                number: vec![field(&"x".repeat(129), None)],
                ..Default::default()
            }),
            "INVALID_REQUEST"
        );
        assert_eq!(
            refused(ContactPayload {
                number: (0..MAX_CONTACT_FIELD_ENTRIES + 1)
                    .map(|_| field("+1", None))
                    .collect(),
                ..Default::default()
            }),
            "INVALID_REQUEST"
        );
        assert_eq!(
            refused(ContactPayload {
                avatar: Some("not-a-data-uri".into()),
                ..Default::default()
            }),
            "INVALID_REQUEST"
        );

        // The unknown account and the conversation-id bounds refuse too.
        let error = service
            .prepare_messages_send_contact(&MessagesSendContactParams {
                account_id: "no-such-account".into(),
                conversation_id: direct.id.clone(),
                contact: ContactPayload {
                    name: Some(ContactName {
                        given_name: Some("Ada".into()),
                        ..Default::default()
                    }),
                    ..Default::default()
                },
            })
            .unwrap_err();
        assert_eq!(error.into_api().code, "ACCOUNT_NOT_FOUND");
        let error = service
            .prepare_messages_send_contact(&params_for(
                String::new(),
                ContactPayload {
                    name: Some(ContactName {
                        given_name: Some("Ada".into()),
                        ..Default::default()
                    }),
                    ..Default::default()
                },
            ))
            .unwrap_err();
        assert_eq!(error.into_api().code, "INVALID_REQUEST");
    }

    /// §4.106 poll-send prepare (contract 1.125): the group-only leg, the
    /// official content/selection bounds, the anchor gates, and the
    /// optional-keys-absent-stay-absent frames.
    #[test]
    fn poll_send_prepare_ladder_and_group_leg() {
        let (_temp, mut service) = service();
        let (account, direct) = linked_account_and_conversation(&mut service);
        let group = service
            .store_ref()
            .ensure_conversation(&account.id, "group", "ZmFrZS1ncm91cC0x", "Fixture Group")
            .unwrap();

        let upstream = service
            .prepare_messages_send_poll_create(&MessagesSendPollCreateParams {
                account_id: account.id.clone(),
                conversation_id: group.id.clone(),
                question: "Lunch?".into(),
                options: vec!["Ramen".into(), "Tacos".into()],
                allow_multiple: Some(true),
            })
            .unwrap();
        assert_eq!(upstream["account"], "+15555550100");
        assert_eq!(upstream["groupId"], "ZmFrZS1ncm91cC0x");
        assert_eq!(upstream["question"], "Lunch?");
        assert_eq!(upstream["options"], json!(["Ramen", "Tacos"]));
        assert_eq!(upstream["allowMultiple"], true);

        let upstream = service
            .prepare_messages_send_poll_create(&MessagesSendPollCreateParams {
                account_id: account.id.clone(),
                conversation_id: group.id.clone(),
                question: "Lunch?".into(),
                options: vec!["Ramen".into(), "Tacos".into()],
                allow_multiple: None,
            })
            .unwrap();
        assert!(upstream.get("allowMultiple").is_none());

        let upstream = service
            .prepare_messages_send_poll_vote(&MessagesSendPollVoteParams {
                account_id: account.id.clone(),
                conversation_id: group.id.clone(),
                target_author: "+15555550101".into(),
                target_timestamp: 1727000000000,
                option_indexes: vec![0, 1],
                vote_count: Some(2),
            })
            .unwrap();
        assert_eq!(upstream["targetAuthor"], "+15555550101");
        assert_eq!(upstream["targetTimestamp"], 1727000000000_u64);
        assert_eq!(upstream["optionIndexes"], json!([0, 1]));
        assert_eq!(upstream["voteCount"], 2);

        let upstream = service
            .prepare_messages_send_poll_terminate(&MessagesSendPollTerminateParams {
                account_id: account.id.clone(),
                conversation_id: group.id.clone(),
                target_timestamp: 1727000000000,
            })
            .unwrap();
        assert_eq!(upstream["targetTimestamp"], 1727000000000_u64);

        // The ladder: the content bounds, the selection domain, the zero
        // anchor, and the direct-conversation refusal — every refusal before
        // any upstream frame.
        let create = |conversation_id: &str, question: String, options: Vec<String>| {
            service
                .prepare_messages_send_poll_create(&MessagesSendPollCreateParams {
                    account_id: account.id.clone(),
                    conversation_id: conversation_id.into(),
                    question,
                    options,
                    allow_multiple: None,
                })
                .unwrap_err()
                .into_api()
                .code
        };
        assert_eq!(
            create(
                &group.id,
                "x".repeat(MAX_POLL_QUESTION_CHARS + 1),
                vec!["A".into(), "B".into()]
            ),
            "INVALID_REQUEST"
        );
        assert_eq!(
            create(&group.id, "Q".into(), vec!["A".into()]),
            "INVALID_REQUEST"
        );
        let error = service
            .prepare_messages_send_poll_vote(&MessagesSendPollVoteParams {
                account_id: account.id.clone(),
                conversation_id: group.id.clone(),
                target_author: "+15555550101".into(),
                target_timestamp: 1727000000000,
                option_indexes: vec![10],
                vote_count: None,
            })
            .unwrap_err();
        assert_eq!(error.into_api().code, "INVALID_REQUEST");
        let error = service
            .prepare_messages_send_poll_vote(&MessagesSendPollVoteParams {
                account_id: account.id.clone(),
                conversation_id: group.id.clone(),
                target_author: "+15555550101".into(),
                target_timestamp: 0,
                option_indexes: vec![],
                vote_count: None,
            })
            .unwrap_err();
        assert_eq!(error.into_api().code, "INVALID_REQUEST");
        let error = service
            .prepare_messages_send_poll_terminate(&MessagesSendPollTerminateParams {
                account_id: account.id.clone(),
                conversation_id: group.id.clone(),
                target_timestamp: 0,
            })
            .unwrap_err();
        assert_eq!(error.into_api().code, "INVALID_REQUEST");
        assert_eq!(
            create(&direct.id, "Q".into(), vec!["A".into(), "B".into()]),
            "INVALID_REQUEST"
        );
        let error = service
            .prepare_messages_send_poll_create(&MessagesSendPollCreateParams {
                account_id: "no-such-account".into(),
                conversation_id: group.id.clone(),
                question: "Q".into(),
                options: vec!["A".into(), "B".into()],
                allow_multiple: None,
            })
            .unwrap_err();
        assert_eq!(error.into_api().code, "ACCOUNT_NOT_FOUND");
    }

    /// §4.69: the four message-carrying cloud-restore families pass the
    /// engine's `data.detail` verbatim (the promised contract face) with the
    /// family retryability reasserted over the `with_data` default; the three
    /// state families drop any data (nothing was promised for them).
    #[test]
    fn cloud_restore_detail_data_rides_verbatim_on_message_families() {
        let detail = json!({ "detail": "cdn 502" });
        for (code, retryable) in [
            ("BACKUP_TRANSPORT_FAILED", true),
            ("BACKUP_DOWNLOAD_FAILED", true),
            ("BACKUP_DECRYPT_FAILED", false),
            ("BACKUP_EXPORT_FAILED", false),
        ] {
            let api = ServiceError::Engine(EngineError::UpstreamCode {
                code,
                data: Some(detail.clone()),
            })
            .into_api();
            assert_eq!(api.code, code, "{code}");
            assert_eq!(api.retryable, retryable, "{code} retryable face");
            assert_eq!(api.data, Some(detail.clone()), "{code} detail face");
        }
        for code in [
            "BACKUP_NOT_PROVISIONED",
            "BACKUP_AUTH_FAILED",
            "BACKUP_RUNNING",
        ] {
            let api = ServiceError::Engine(EngineError::UpstreamCode {
                code,
                data: Some(detail.clone()),
            })
            .into_api();
            assert_eq!(api.code, code, "{code}");
            assert!(!api.retryable, "{code} stays deterministic");
            assert!(
                api.data.is_none(),
                "{code} never leaks unpromised engine data: {api:?}"
            );
        }
    }

    /// §4.72 cloud-upload faces (contract 1.87, engine cloud-backup-contract
    /// §6.2): the two new code positions map to themselves with the
    /// contract-fixed retryability (the re-entry gate deterministic
    /// content-free; the CDN uplink family retryable with `data.detail`
    /// verbatim), and the per-face divergence on the shared codes holds —
    /// BACKUP_IO_FAILED is retryable=true content-free on the §4.46 export
    /// face but retryable=false with detail on the upload face, and
    /// BACKUP_TRANSPORT_FAILED keeps its restore text globally while the
    /// upload face carries the upload text. The shared state families pass
    /// the upload mapping through to their global faces unchanged.
    #[test]
    fn cloud_upload_code_faces_match_the_contract_table() {
        // The global faces of the two new codes (UPLOAD_FAILED's global arm
        // IS the upload face — only the upload path emits it).
        let api = ServiceError::Engine(EngineError::UpstreamCode {
            code: "BACKUP_UPLOAD_ALREADY_RUNNING",
            data: Some(json!({ "detail": "must not ride" })),
        })
        .into_api();
        assert_eq!(api.code, "BACKUP_UPLOAD_ALREADY_RUNNING");
        assert!(!api.retryable);
        assert!(
            api.data.is_none(),
            "the re-entry gate never leaks unpromised engine data: {api:?}"
        );

        // The upload-face mapping: message families carry the detail
        // verbatim with the contract-fixed retryability.
        for (code, retryable) in [
            ("BACKUP_TRANSPORT_FAILED", true),
            ("BACKUP_UPLOAD_FAILED", true),
            ("BACKUP_IO_FAILED", false),
        ] {
            let api = cloud_upload_face_error(code, Some(json!({ "detail": "cdn 502" })));
            assert_eq!(api.code, code, "{code}");
            assert_eq!(api.retryable, retryable, "{code} retryable face");
            assert_eq!(
                api.data,
                Some(json!({ "detail": "cdn 502" })),
                "{code} detail face"
            );
            // A data-less older-engine face keeps the fixed content-free
            // answer with the same retryability.
            let api = cloud_upload_face_error(code, None);
            assert_eq!(api.code, code, "{code}");
            assert_eq!(api.retryable, retryable, "{code} retryable face");
            assert!(api.data.is_none(), "{code} content-free without data");
        }

        // The per-face divergence is real: the export face of
        // BACKUP_IO_FAILED stays retryable=true and content-free, and the
        // global transport text stays the restore face's.
        let export_face = ServiceError::Engine(EngineError::UpstreamCode {
            code: "BACKUP_IO_FAILED",
            data: Some(json!({ "detail": "export never promised detail" })),
        })
        .into_api();
        assert_eq!(export_face.code, "BACKUP_IO_FAILED");
        assert!(export_face.retryable, "the export face stays transient");
        assert!(
            export_face.data.is_none(),
            "the export face stays content-free: {export_face:?}"
        );
        let upload_face = cloud_upload_face_error(
            "BACKUP_IO_FAILED",
            Some(json!({ "detail": "temp archive write" })),
        );
        assert_eq!(upload_face.code, "BACKUP_IO_FAILED");
        assert!(!upload_face.retryable, "the upload face is terminal");
        assert_eq!(
            upload_face.data,
            Some(json!({ "detail": "temp archive write" }))
        );
        let restore_transport = ServiceError::Engine(EngineError::UpstreamCode {
            code: "BACKUP_TRANSPORT_FAILED",
            data: None,
        })
        .into_api();
        let upload_transport = cloud_upload_face_error("BACKUP_TRANSPORT_FAILED", None);
        assert_ne!(
            restore_transport.message, upload_transport.message,
            "the two faces name their own chain"
        );
        assert_eq!(
            upload_transport.message,
            "the cloud backup upload transport failed"
        );

        // The shared state families pass through to their global faces.
        for code in [
            "BACKUP_AUTH_FAILED",
            "BACKUP_NOT_PROVISIONED",
            "BACKUP_ARTIFACT_MISSING",
            "BACKUP_ARTIFACT_INVALID",
            "BACKUP_UPLOAD_ALREADY_RUNNING",
        ] {
            let api = cloud_upload_face_error(code, Some(json!({ "detail": "unpromised" })));
            assert_eq!(api.code, code, "{code}");
            assert!(!api.retryable, "{code} stays deterministic");
            assert!(
                api.data.is_none(),
                "{code} never leaks unpromised engine data: {api:?}"
            );
        }
    }

    #[test]
    fn profile_upload_failed_carries_engine_data_verbatim() {
        // Contract 1.50: the partial-success data object rides through and
        // drives the retryable bit (the engine's truth, not the connector's).
        let api = ServiceError::Engine(EngineError::UpstreamCode {
            code: "PROFILE_UPLOAD_FAILED",
            data: Some(json!({ "retryable": true, "textSaved": true })),
        })
        .into_api();
        assert_eq!(api.code, "PROFILE_UPLOAD_FAILED");
        assert!(api.retryable);
        assert_eq!(
            api.data,
            Some(json!({ "retryable": true, "textSaved": true }))
        );

        // textSaved=false keeps the payload (the desktop's plain-error
        // branch reads it) — retryable re-read from the data object.
        let api = ServiceError::Engine(EngineError::UpstreamCode {
            code: "PROFILE_UPLOAD_FAILED",
            data: Some(json!({ "retryable": true, "textSaved": false })),
        })
        .into_api();
        assert_eq!(
            api.data,
            Some(json!({ "retryable": true, "textSaved": false }))
        );

        // A data-less older-engine face: the fixed retryable=true face, no
        // data member.
        let api = ServiceError::Engine(EngineError::UpstreamCode {
            code: "PROFILE_UPLOAD_FAILED",
            data: None,
        })
        .into_api();
        assert_eq!(api.code, "PROFILE_UPLOAD_FAILED");
        assert!(api.retryable);
        assert!(api.data.is_none());

        // Any other code never gains a data member even when the engine
        // sent one — the payload face is PROFILE_UPLOAD_FAILED-only.
        let api = ServiceError::Engine(EngineError::UpstreamCode {
            code: "STICKER_PACK_FETCH_FAILED",
            data: Some(json!({ "secret": 1 })),
        })
        .into_api();
        assert_eq!(api.code, "STICKER_PACK_FETCH_FAILED");
        assert!(api.data.is_none());
    }

    /// The group-faced partial-success sibling (contract 1.89): the
    /// engine's {retryable, textSaved} data object rides verbatim and
    /// drives the retryable bit (retryable=true per the family), and a
    /// data-less older-engine face maps to the fixed retryable=true face
    /// with no data member — the PROFILE_UPLOAD_FAILED channel verbatim.
    #[test]
    fn group_avatar_upload_failed_carries_engine_data_verbatim() {
        let api = ServiceError::Engine(EngineError::UpstreamCode {
            code: "GROUP_AVATAR_UPLOAD_FAILED",
            data: Some(json!({ "retryable": true, "textSaved": true })),
        })
        .into_api();
        assert_eq!(api.code, "GROUP_AVATAR_UPLOAD_FAILED");
        assert!(api.retryable);
        assert_eq!(
            api.data,
            Some(json!({ "retryable": true, "textSaved": true }))
        );

        // textSaved=false keeps the payload (the desktop's plain-error
        // branch reads it) — retryable re-read from the data object.
        let api = ServiceError::Engine(EngineError::UpstreamCode {
            code: "GROUP_AVATAR_UPLOAD_FAILED",
            data: Some(json!({ "retryable": true, "textSaved": false })),
        })
        .into_api();
        assert_eq!(
            api.data,
            Some(json!({ "retryable": true, "textSaved": false }))
        );

        // A data-less older-engine face: the fixed retryable=true face, no
        // data member.
        let api = ServiceError::Engine(EngineError::UpstreamCode {
            code: "GROUP_AVATAR_UPLOAD_FAILED",
            data: None,
        })
        .into_api();
        assert_eq!(api.code, "GROUP_AVATAR_UPLOAD_FAILED");
        assert!(api.retryable);
        assert!(api.data.is_none());
    }

    #[test]
    fn text_limit_is_enforced_by_utf8_bytes() {
        assert!(validate_text(&"a".repeat(MAX_TEXT_BYTES)).is_ok());
        assert!(validate_text(&"a".repeat(MAX_TEXT_BYTES + 1)).is_err());

        assert!(validate_text(&"界".repeat(21_845)).is_ok());
        assert!(validate_text(&"界".repeat(21_846)).is_err());

        assert!(validate_text(&"😀".repeat(16_384)).is_ok());
        assert!(validate_text(&format!("{}a", "😀".repeat(16_384))).is_err());
        assert!(validate_text("").is_err());
    }

    #[test]
    fn inbound_long_text_is_projected_and_fetched_on_demand() {
        let (_temp, mut service) = service();
        let account = service
            .sync_accounts_from_numbers(
                &[("+15555550100".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap()
            .remove(0);
        let full_text = "界".repeat(4_000);
        let events = service
            .ingest_receive(
                NormalizedReceive {
                    required_protocol_version: None,
                    timestamp: Some(10),
                    content_kind: "dataMessage",
                    direction: "incoming",
                    account_present: true,
                    account: Some("+15555550100".into()),
                    source: Some("+15555550101".into()),
                    source_uuid: None,
                    peer_name: Some("Peer".into()),
                    group_id: None,
                    text: Some(full_text.clone()),
                    text_bytes: None,
                    text_truncated: false,
                    quote: None,
                    attachments: Vec::new(),
                    rich: None,
                    sticker: None,
                    expire_seconds: None,
                    expire_start_at: None,
                    control: None,
                    server_guid: None,
                    reporting_token: None,
                    server_timestamp: None,
                },
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap();
        let projected = events
            .iter()
            .find_map(|event| match event {
                HostSideEvent::MessageUpserted(message) => Some(message),
                _ => None,
            })
            .unwrap();
        assert!(projected.text.as_ref().unwrap().len() <= MAX_HOST_TEXT_PREVIEW_BYTES);
        assert!(projected.text_truncated);
        assert!(projected.text_retrievable);

        let fetched = service
            .get_message_text(&account.id, &projected.conversation_id, &projected.id)
            .unwrap();
        assert_eq!(fetched.text, full_text);
        assert_eq!(fetched.text_bytes, 12_000);

        let other_account = service
            .sync_accounts_from_numbers(
                &[("+15555550100".into(), None), ("+15555550102".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap()
            .into_iter()
            .find(|candidate| candidate.id != account.id)
            .unwrap();
        assert!(matches!(
            service.get_message_text(&other_account.id, &projected.conversation_id, &projected.id,),
            Err(ServiceError::Store(StoreError::MessageNotFound))
        ));
        assert!(matches!(
            service.get_message_text(&"x".repeat(129), "conversation", "message"),
            Err(ServiceError::Api(error)) if error.code == "INVALID_REQUEST"
        ));
    }

