    #[test]
    fn send_text_projects_first_preview_onto_upstream_params() {
        let (_temp, service) = service();
        let account = service
            .sync_accounts_from_numbers(
                &[("+15555550100".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap()
            .remove(0);
        let conversation = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        let dispatch = match service
            .prepare_send_text(
                &account.id,
                &conversation.id,
                "look at https://example.com/a now",
                "req-preview-ok",
                None,
                Some(vec![
                    SendTextPreviewParams {
                        url: "https://example.com/a".into(),
                        title: "Example".into(),
                        description: Some("A page".into()),
                        image_data_uri: Some("data:image/jpeg;base64,QUJD".into()),
                        date: None,
                    },
                    // extras are ignored upstream (List.of(one) on the pinned
                    // signal-cli) — the connector only forwards the first.
                    SendTextPreviewParams {
                        url: "https://example.com/b".into(),
                        title: "Second".into(),
                        description: None,
                        image_data_uri: None,
                        date: None,
                    },
                ]),
                None,
                None,
                None,
                None,
            )
            .unwrap()
        {
            PreparedSend::Dispatch { params, .. } => params,
            PreparedSend::Existing(_) => panic!("new client request must dispatch"),
        };
        assert!(
            dispatch["dispatchId"]
                .as_str()
                .is_some_and(|value| !value.is_empty())
        );
        assert_eq!(dispatch["previewUrl"], json!("https://example.com/a"));
        assert_eq!(dispatch["previewTitle"], json!("Example"));
        assert_eq!(dispatch["previewDescription"], json!("A page"));
        assert_eq!(
            dispatch["previewImage"],
            json!("data:image/jpeg;base64,QUJD")
        );
    }

    /// messages.sendText story-reply context (contract 1.156, §4.154): the
    /// two optional keys ride the upstream frame verbatim — each only when
    /// the caller sent it, absence never becoming null — with no pair gate
    /// (a single-sided presence forwards as-is; the engine's storyContext
    /// parse owns the discipline) and no value-domain gate (a raw
    /// string-form timestamp forwards untouched, the 1.151 timestamp
    /// posture). The keyless body stays byte-identical to the pre-1.156
    /// shape.
    #[test]
    fn send_text_story_reply_context_rides_the_upstream_frame_verbatim() {
        let (_temp, service) = service();
        let account = service
            .sync_accounts_from_numbers(
                &[("+15555550100".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap()
            .remove(0);
        let conversation = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        let prepare =
            |text: &str, request: &str, author: Option<&str>, timestamp: Option<Value>| {
                match service
                    .prepare_send_text(
                        &account.id,
                        &conversation.id,
                        text,
                        request,
                        None,
                        None,
                        None,
                        None,
                        author.map(str::to_string),
                        timestamp,
                    )
                    .unwrap()
                {
                    PreparedSend::Dispatch { params, .. } => params,
                    PreparedSend::Existing(_) => panic!("new client request must dispatch"),
                }
            };

        // Both keys: the full story-reply context, byte-verbatim.
        assert_eq!(
            prepare(
                "story reply body",
                "req-story-reply-both",
                Some("22222222-2222-2222-2222-222222222222"),
                Some(json!(1_727_000_000_000u64)),
            ),
            json!({
                "account": "+15555550100",
                "message": "story reply body",
                "recipient": ["+15555550101"],
                "storyReplyAuthor": "22222222-2222-2222-2222-222222222222",
                "storyReplyTimestamp": 1_727_000_000_000u64,
                "dispatchId": "req-story-reply-both",
            })
        );

        // Author only: the single-sided presence forwards as-is (the
        // pair-discipline refusal is the engine's face).
        let author_only = prepare(
            "author only",
            "req-story-reply-author",
            Some("22222222-2222-2222-2222-222222222222"),
            None,
        );
        assert_eq!(
            author_only["storyReplyAuthor"],
            json!("22222222-2222-2222-2222-222222222222")
        );
        assert!(author_only.get("storyReplyTimestamp").is_none());

        // Timestamp only, in a shape the engine refuses (a string stamp):
        // the raw value forwards untouched.
        let timestamp_only = prepare(
            "timestamp only",
            "req-story-reply-stamp",
            None,
            Some(json!("1727000000000")),
        );
        assert!(timestamp_only.get("storyReplyAuthor").is_none());
        assert_eq!(
            timestamp_only["storyReplyTimestamp"],
            json!("1727000000000")
        );

        // Neither key: the pre-1.156 wire shape, byte-identical.
        assert_eq!(
            prepare("plain body", "req-story-reply-plain", None, None),
            json!({
                "account": "+15555550100",
                "message": "plain body",
                "recipient": ["+15555550101"],
                "dispatchId": "req-story-reply-plain",
            })
        );
    }

    #[test]
    fn send_text_preview_rejects_deterministic_shape_violations() {
        let (_temp, service) = service();
        let account = service
            .sync_accounts_from_numbers(
                &[("+15555550100".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap()
            .remove(0);
        let conversation = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        let preview = |url: &str, title: &str| SendTextPreviewParams {
            url: url.into(),
            title: title.into(),
            description: None,
            image_data_uri: None,
            date: None,
        };
        // signal-cli requires the preview url to appear in the message body —
        // enforced here so the failure is a deterministic INVALID_REQUEST
        // instead of a late upstream send error.
        let url_absent = service
            .prepare_send_text(
                &account.id,
                &conversation.id,
                "no link in here",
                "req-preview-absent",
                None,
                Some(vec![preview("https://example.com/a", "Example")]),
                None,
                None,
                None,
                None,
            )
            .unwrap_err();
        assert!(matches!(url_absent, ServiceError::Api(error) if error.code == "INVALID_REQUEST"));
        // A preview image is a data:image/ URI only — never a caller path.
        let path_image = service
            .prepare_send_text(
                &account.id,
                &conversation.id,
                "see https://example.com/a",
                "req-preview-path",
                None,
                Some(vec![SendTextPreviewParams {
                    url: "https://example.com/a".into(),
                    title: "Example".into(),
                    description: None,
                    image_data_uri: Some("/etc/passwd".into()),
                    date: None,
                }]),
                None,
                None,
                None,
                None,
            )
            .unwrap_err();
        assert!(matches!(path_image, ServiceError::Api(error) if error.code == "INVALID_REQUEST"));
        // Title is mandatory upstream.
        let empty_title = service
            .prepare_send_text(
                &account.id,
                &conversation.id,
                "see https://example.com/a",
                "req-preview-title",
                None,
                Some(vec![preview("https://example.com/a", "   ")]),
                None,
                None,
                None,
                None,
            )
            .unwrap_err();
        assert!(matches!(empty_title, ServiceError::Api(error) if error.code == "INVALID_REQUEST"));
        // A rejected preview leaves no pending row behind.
        assert!(
            service
                .store_ref()
                .message_by_client_request(&account.id, "req-preview-absent")
                .unwrap()
                .is_none()
        );
    }

    /// §4.126: the preview date rides the wire three ways — the upstream
    /// params carry `previewDate` (0 folds to absent, the official falsy
    /// posture), the pending row's rich persists the card metadata-only
    /// (never the image bytes), and the retry rebuild restores the card
    /// without the image.
    #[test]
    fn send_text_preview_date_rides_wire_row_and_retry() {
        let (_temp, service) = service();
        let account = service
            .sync_accounts_from_numbers(
                &[("+15555550100".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap()
            .remove(0);
        let conversation = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        let pending_id = match service
            .prepare_send_text(
                &account.id,
                &conversation.id,
                "see https://example.com/a",
                "req-preview-date",
                None,
                Some(vec![SendTextPreviewParams {
                    url: "https://example.com/a".into(),
                    title: "Example".into(),
                    description: Some("A page".into()),
                    image_data_uri: Some("data:image/jpeg;base64,QUJD".into()),
                    date: Some(1_600_000_000_000),
                }]),
                None,
                None,
                None,
                None,
            )
            .unwrap()
        {
            PreparedSend::Dispatch {
                pending_id, params, ..
            } => {
                assert_eq!(params["previewDate"], json!(1_600_000_000_000_u64));
                pending_id
            }
            PreparedSend::Existing(_) => panic!("new client request must dispatch"),
        };
        let row = service
            .store_ref()
            .message_by_client_request(&account.id, "req-preview-date")
            .unwrap()
            .unwrap();
        let rich = row.rich.as_ref().expect("a preview send arms the row rich");
        assert_eq!(rich.previews.len(), 1);
        assert_eq!(rich.previews[0].url, "https://example.com/a");
        assert_eq!(rich.previews[0].title.as_deref(), Some("Example"));
        assert_eq!(rich.previews[0].description.as_deref(), Some("A page"));
        assert_eq!(rich.previews[0].date, Some(1_600_000_000_000));
        assert!(
            rich.previews[0].image.is_none(),
            "the image data uri is transit-only, never a stored byte"
        );

        // The retry rebuild restores the card, metadata-only.
        service.complete_send_failed(&pending_id).unwrap();
        let params = match service
            .prepare_retry_text(&account.id, &conversation.id, "req-preview-date")
            .unwrap()
        {
            PreparedSend::Dispatch { params, .. } => params,
            PreparedSend::Existing(_) => panic!("retry must re-dispatch the same row"),
        };
        assert_eq!(params["previewUrl"], json!("https://example.com/a"));
        assert_eq!(params["previewDate"], json!(1_600_000_000_000_u64));
        assert!(
            params.get("previewImage").is_none(),
            "the retried card re-sends metadata-only; previewImage is independently optional"
        );

        // A zero stamp folds to absent everywhere (the falsy posture).
        let params = match service
            .prepare_send_text(
                &account.id,
                &conversation.id,
                "see https://example.com/a",
                "req-preview-date-zero",
                None,
                Some(vec![SendTextPreviewParams {
                    url: "https://example.com/a".into(),
                    title: "Example".into(),
                    description: None,
                    image_data_uri: None,
                    date: Some(0),
                }]),
                None,
                None,
                None,
                None,
            )
            .unwrap()
        {
            PreparedSend::Dispatch { params, .. } => params,
            PreparedSend::Existing(_) => panic!("new client request must dispatch"),
        };
        assert!(
            params.get("previewDate").is_none(),
            "0 folds to absent — the key stays off the frame"
        );
        let row = service
            .store_ref()
            .message_by_client_request(&account.id, "req-preview-date-zero")
            .unwrap()
            .unwrap();
        assert_eq!(row.rich.as_ref().unwrap().previews[0].date, None);

        // The u64 type fails negative, fractional, and non-integer stamps at
        // params deserialization (fail-closed); 0 parses and folds later.
        let base = json!({
            "url": "https://example.com/a",
            "title": "Example",
        });
        for (label, date) in [
            ("negative", json!(-1)),
            ("fractional", json!(1.5)),
            ("string", json!("soon")),
        ] {
            let mut value = base.clone();
            value["date"] = date;
            assert!(
                serde_json::from_value::<SendTextPreviewParams>(value).is_err(),
                "{label} date must fail deserialization"
            );
        }
        let zero = serde_json::from_value::<SendTextPreviewParams>(json!({
            "url": "https://example.com/a",
            "title": "Example",
            "date": 0,
        }))
        .unwrap();
        assert_eq!(zero.date, Some(0));
    }

    /// §4.127: the blur placeholder rides the pending descriptor (singular
    /// and plural), fails closed on empty and over-bound values, and never
    /// reaches the upstream params — the engine's data-URI attachment
    /// channel has no blurHash key, so the placeholder is the sender's own
    /// bubble face only.
    #[test]
    fn send_attachment_blur_hash_rides_descriptor_and_stays_off_upstream() {
        let (_temp, service) = service();
        let account = service
            .sync_accounts_from_numbers(
                &[("+15555550100".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap()
            .remove(0);
        let conversation = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        let b64 = "YXR0YWNobWVudCBieXRlcw=="; // 16 raw bytes
        let placeholder = "LEHV6nWB2yk8pyo0adR*.7kCMdnj";

        // Singular: the descriptor carries it, the upstream frame does not.
        let prepared = service
            .prepare_send_attachment(
                &account.id,
                &AttachmentSendTarget::Conversation(&conversation.id),
                "req-blur-1",
                b64,
                16,
                Some("notes.txt"),
                Some("text/plain"),
                Some("see attachment"),
                None,
                false,
                false,
                Some(placeholder),
                false,
            )
            .unwrap();
        match &prepared {
            PreparedSend::Dispatch { params, .. } => {
                assert!(
                    params.get("blurHash").is_none(),
                    "the upstream data-URI channel has no blurHash key"
                );
            }
            PreparedSend::Existing(_) => panic!("new client request must dispatch"),
        }
        let row = service
            .store_ref()
            .message_by_client_request(&account.id, "req-blur-1")
            .unwrap()
            .unwrap();
        assert_eq!(row.attachments[0].blur_hash.as_deref(), Some(placeholder));

        // Plural: the per-entry key rides its own descriptor.
        let entries = vec![MessagesSendAttachmentEntry {
            data_base64: b64.to_string(),
            size_bytes: 16,
            filename: Some("notes.txt".into()),
            content_type: Some("text/plain".into()),
            blur_hash: Some("abc123".into()),
            gif: false,
        }];
        let prepared = service
            .prepare_send_attachment_multi(
                &account.id,
                &AttachmentSendTarget::Conversation(&conversation.id),
                "req-blur-2",
                &entries,
                None,
                None,
            )
            .unwrap();
        assert!(matches!(prepared, PreparedSend::Dispatch { .. }));
        let row = service
            .store_ref()
            .message_by_client_request(&account.id, "req-blur-2")
            .unwrap()
            .unwrap();
        assert_eq!(row.attachments[0].blur_hash.as_deref(), Some("abc123"));

        // Fail closed before the pending row: empty and over-bound values.
        for (label, value) in [("empty", Some("")), ("over-bound", Some(&"x".repeat(129)))] {
            let error = service
                .prepare_send_attachment(
                    &account.id,
                    &AttachmentSendTarget::Conversation(&conversation.id),
                    "req-blur-bad",
                    b64,
                    16,
                    Some("notes.txt"),
                    Some("text/plain"),
                    None,
                    None,
                    false,
                    false,
                    value,
                    false,
                )
                .unwrap_err();
            assert!(
                matches!(error, ServiceError::Api(ref e) if e.code == "INVALID_REQUEST"),
                "{label} blurHash must answer INVALID_REQUEST"
            );
            assert!(
                service
                    .store_ref()
                    .message_by_client_request(&account.id, "req-blur-bad")
                    .unwrap()
                    .is_none(),
                "{label} blurHash leaves no row behind"
            );
        }
        // The plural face fails closed the same way.
        let bad_entries = vec![MessagesSendAttachmentEntry {
            data_base64: b64.to_string(),
            size_bytes: 16,
            filename: None,
            content_type: None,
            blur_hash: Some(String::new()),
            gif: false,
        }];
        let error = service
            .prepare_send_attachment_multi(
                &account.id,
                &AttachmentSendTarget::Conversation(&conversation.id),
                "req-blur-bad-multi",
                &bad_entries,
                None,
                None,
            )
            .unwrap_err();
        assert!(matches!(error, ServiceError::Api(ref e) if e.code == "INVALID_REQUEST"));
    }

    /// §4.123: the automatic queue enrolls exactly the definitive-error
    /// network classes, each arm on its own beat. `ServerUnavailable` /
    /// `Upstream` arm the curve in the same settlement; `RateLimited`
    /// (contract 1.143, §4.139) arms the Retry-After beat — the server
    /// answered "wait", so the row waits the official default minute, not
    /// the 190 ms curve head that would hammer again almost immediately.
    /// Every other engine error class settles the row plain `failed` with
    /// no schedule — the proof / identity families are the server stopping
    /// the send with a product judgment attached, the structured-code
    /// families mix deterministic refusals, and the unknown outcome (whose
    /// funnel arm never schedules) is the red line itself.
    #[test]
    fn retry_queue_enrolls_only_the_eligible_error_classes() {
        let (_temp, service) = service();
        let account = service
            .sync_accounts_from_numbers(
                &[("+15555550100".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap()
            .remove(0);
        let conversation = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        let face = |service: &ConnectorService, id: &str| {
            service
                .store_ref()
                .conn()
                .query_row(
                    "SELECT status, first_send_attempted_at, retry_attempt_count,
                            next_attempt_at
                     FROM messages WHERE id=?1",
                    params![id],
                    |row| {
                        Ok((
                            row.get::<_, String>(0)?,
                            row.get::<_, Option<i64>>(1)?,
                            row.get::<_, i64>(2)?,
                            row.get::<_, Option<i64>>(3)?,
                        ))
                    },
                )
                .unwrap()
        };
        let enrollable = [
            EngineError::ServerUnavailable,
            EngineError::Upstream {
                cause: None,
                code: None,
            },
        ];
        for (index, error) in enrollable.iter().enumerate() {
            let request = format!("req-enroll-{index}");
            let pending_id = match service
                .prepare_send_text(
                    &account.id,
                    &conversation.id,
                    "hello",
                    &request,
                    None,
                    None,
                    None,
                    None,
                    None,
                    None,
                )
                .unwrap()
            {
                PreparedSend::Dispatch { pending_id, .. } => pending_id,
                PreparedSend::Existing(_) => panic!("new request must dispatch"),
            };
            let events = service
                .complete_send_failed_for_engine(&pending_id, error)
                .unwrap();
            assert_eq!(events.len(), 1, "the failed transition emits");
            let (status, first, count, next) = face(&service, &pending_id);
            assert_eq!(status, "failed");
            assert!(
                first.is_some() && next.is_some() && count == 1,
                "{error:?} must arm the schedule"
            );
        }
        // The rate-limit arm: enrolled, but on the Retry-After beat — the
        // official one-minute default this wire falls back to, decisively
        // not the 190 ms curve head.
        {
            let pending_id = match service
                .prepare_send_text(
                    &account.id,
                    &conversation.id,
                    "hello",
                    "req-enroll-ratelimit",
                    None,
                    None,
                    None,
                    None,
                    None,
                    None,
                )
                .unwrap()
            {
                PreparedSend::Dispatch { pending_id, .. } => pending_id,
                PreparedSend::Existing(_) => panic!("new request must dispatch"),
            };
            let settled_at = now_ms();
            let events = service
                .complete_send_failed_for_engine(
                    &pending_id,
                    &EngineError::RateLimited {
                        retry_after_secs: None,
                    },
                )
                .unwrap();
            assert_eq!(events.len(), 1, "the failed transition emits");
            let (status, first, count, next) = face(&service, &pending_id);
            assert_eq!(status, "failed");
            assert!(first.is_some(), "the rate-limit arm stamps the window");
            assert_eq!(count, 1);
            let next = next.expect("the rate-limit arm arms the schedule");
            assert!(
                next >= (settled_at + crate::store::RATE_LIMIT_RETRY_AFTER_MS - 1_000) as i64
                    && next
                        <= (settled_at + crate::store::RATE_LIMIT_RETRY_AFTER_MS + 1_000) as i64,
                "the beat is the Retry-After default, not the curve: {next}"
            );
        }
        let refused = [
            EngineError::ProofRequired,
            EngineError::IdentityUnverified,
            EngineError::UpstreamCode {
                code: "STICKER_PACK_INVALID",
                data: None,
            },
            EngineError::Timeout,
            EngineError::NotRunning,
            EngineError::Unauthorized,
            EngineError::UnknownOutcome,
        ];
        for (index, error) in refused.iter().enumerate() {
            let request = format!("req-refuse-{index}");
            let pending_id = match service
                .prepare_send_text(
                    &account.id,
                    &conversation.id,
                    "hello",
                    &request,
                    None,
                    None,
                    None,
                    None,
                    None,
                    None,
                )
                .unwrap()
            {
                PreparedSend::Dispatch { pending_id, .. } => pending_id,
                PreparedSend::Existing(_) => panic!("new request must dispatch"),
            };
            service
                .complete_send_failed_for_engine(&pending_id, error)
                .unwrap();
            let (status, first, count, next) = face(&service, &pending_id);
            assert_eq!(status, "failed");
            assert_eq!(
                (first, count, next),
                (None, 0, None),
                "{error:?} must settle plain failed with no schedule"
            );
        }
    }

    /// Contract 1.143 (§4.139): the three-arm classification itself — the
    /// rate-limit family on the Retry-After beat, the transport family on
    /// the curve, and every other class (the deterministic structured
    /// refusals, the proof/identity gates, the timeout family, and the
    /// unknown red line) plain `None`.
    #[test]
    fn auto_retry_schedule_classifies_the_three_arms() {
        use crate::store::SendRetrySchedule;
        assert_eq!(
            ConnectorService::auto_retry_schedule(&EngineError::RateLimited {
                retry_after_secs: None
            }),
            SendRetrySchedule::RateLimit
        );
        assert_eq!(
            ConnectorService::auto_retry_schedule(&EngineError::ServerUnavailable),
            SendRetrySchedule::Backoff
        );
        assert_eq!(
            ConnectorService::auto_retry_schedule(&EngineError::Upstream {
                cause: None,
                code: None,
            }),
            SendRetrySchedule::Backoff
        );
        // Contract 1.285 §4.269: the two provably-unexecuted resource faces
        // keep the curve — before their anchors were claimed they degraded to
        // the generic upstream face and rode it, so the automatic follow-up
        // is preserved rather than narrowed.
        for error in [
            EngineError::EngineBusy { data: None },
            EngineError::AttachmentBusy { data: None },
        ] {
            assert_eq!(
                ConnectorService::auto_retry_schedule(&error),
                SendRetrySchedule::Backoff,
                "{error:?} never ran, so a retry is safe"
            );
        }
        for error in [
            EngineError::ProofRequired,
            EngineError::IdentityUnverified,
            EngineError::UpstreamCode {
                code: "STICKER_PACK_INVALID",
                data: None,
            },
            EngineError::Timeout,
            EngineError::NotRunning,
            EngineError::Unauthorized,
            EngineError::UnknownOutcome,
            // Contract 1.285 §4.269: a cancelled dispatch may already have
            // been written (the red line), and the same attachment batch can
            // stay over budget.
            EngineError::EngineRequestTimeout { data: None },
            EngineError::AttachmentBudget { data: None },
        ] {
            assert_eq!(
                ConnectorService::auto_retry_schedule(&error),
                SendRetrySchedule::None,
                "{error:?} carries no automatic follow-up"
            );
        }
    }

    /// The unknown red line at the store layer: an unknown settlement
    /// retires any schedule the row might carry, so an unknown row can
    /// never be claimed (AGENTS.md: unknown outcomes are never retried
    /// automatically).
    #[test]
    fn unknown_outcome_retires_any_stale_retry_schedule() {
        let (_temp, service) = service();
        let account = service
            .sync_accounts_from_numbers(
                &[("+15555550100".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap()
            .remove(0);
        let conversation = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        let pending_id = match service
            .prepare_send_text(
                &account.id,
                &conversation.id,
                "hello",
                "req-unknown-face",
                None,
                None,
                None,
                None,
                None,
                None,
            )
            .unwrap()
        {
            PreparedSend::Dispatch { pending_id, .. } => pending_id,
            PreparedSend::Existing(_) => panic!("new request must dispatch"),
        };
        // A stale schedule on a pending row (a hand-edited or restarted-over
        // store shape): the unknown settlement must sweep it.
        service
            .store_ref()
            .conn()
            .execute(
                "UPDATE messages SET first_send_attempted_at=?2, retry_attempt_count=3,
                        next_attempt_at=?3
                 WHERE id=?1",
                params![pending_id, 1_000i64, 2_000i64],
            )
            .unwrap();
        service.complete_send_unknown(&pending_id).unwrap();
        let row = service
            .store_ref()
            .message_by_client_request(&account.id, "req-unknown-face")
            .unwrap()
            .unwrap();
        assert_eq!(row.status, "unknown");
        let face = service
            .store_ref()
            .conn()
            .query_row(
                "SELECT first_send_attempted_at, retry_attempt_count, next_attempt_at
                 FROM messages WHERE id=?1",
                params![pending_id],
                |row| {
                    Ok((
                        row.get::<_, Option<i64>>(0)?,
                        row.get::<_, i64>(1)?,
                        row.get::<_, Option<i64>>(2)?,
                    ))
                },
            )
            .unwrap();
        assert_eq!(face, (None, 0, None));
    }

    /// The §4.123 drain rebuild is the §4.26 manual rebuild: a claimed row
    /// re-dispatches the SAME row with the persisted text, and the send
    /// settlement completes it, clears the queue face, and leaves the
    /// history at exactly one row.
    #[test]
    fn outbox_claim_rebuilds_the_manual_retry_dispatch() {
        let (_temp, service) = service();
        let account = service
            .sync_accounts_from_numbers(
                &[("+15555550100".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap()
            .remove(0);
        let conversation = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        let pending_id = match service
            .prepare_send_text(
                &account.id,
                &conversation.id,
                "queued text",
                "req-outbox-1",
                None,
                None,
                None,
                None,
                None,
                None,
            )
            .unwrap()
        {
            PreparedSend::Dispatch { pending_id, .. } => pending_id,
            PreparedSend::Existing(_) => panic!("new request must dispatch"),
        };
        service
            .complete_send_failed_for_engine(&pending_id, &EngineError::ServerUnavailable)
            .unwrap();
        // Due-ify: claim past the 190 ms first beat (the schedule is
        // settle-time + 190 ms; the claim instant must stay inside the
        // 24 h window, so this is a real-clock +5 s, not an arbitrary
        // far-future stamp).
        let due_now = crate::link::now_ms() + 5_000;
        let claim = service.store_ref().claim_due_retries(due_now, 10).unwrap();
        assert_eq!(claim.len(), 1);
        let claim = &claim[0];
        assert_eq!(claim.message_id, pending_id);
        assert_eq!(claim.client_request_id, "req-outbox-1");
        let prepared = match service.prepare_outbox_retry_text(claim).unwrap() {
            PreparedSend::Dispatch {
                pending_id, params, ..
            } => {
                assert_eq!(pending_id, claim.message_id, "the same row re-dispatches");
                params
            }
            PreparedSend::Existing(_) => panic!("a claim rebuilds a dispatch, never an existing"),
        };
        assert_eq!(prepared["message"], json!("queued text"));
        assert_eq!(prepared["account"], json!("+15555550100"));
        // Settlement completes the SAME row and clears the queue face.
        let (sent, _) = service
            .complete_send_success(&pending_id, &account.id, &conversation.id, 777, None)
            .unwrap();
        assert_eq!(sent.status, "sent");
        let face = service
            .store_ref()
            .conn()
            .query_row(
                "SELECT status, first_send_attempted_at, retry_attempt_count,
                        next_attempt_at
                 FROM messages WHERE id=?1",
                params![pending_id],
                |row| {
                    Ok((
                        row.get::<_, String>(0)?,
                        row.get::<_, Option<i64>>(1)?,
                        row.get::<_, i64>(2)?,
                        row.get::<_, Option<i64>>(3)?,
                    ))
                },
            )
            .unwrap();
        assert_eq!(face, ("sent".into(), None, 0, None));
        let rows = service
            .list_messages(&account.id, &conversation.id, 10, None)
            .unwrap()
            .items;
        assert_eq!(
            rows.len(),
            1,
            "the history stays one row per logical message"
        );
    }

    /// §4.134: the captioned attachment send never enters the §4.123 queue —
    /// the eligibility gate reads the row's attachment face beside its body,
    /// so a caption no longer smuggles an attachment row into a rebuild that
    /// would resend the words without the bytes. A sibling text row enrolls
    /// beside it and the claim takes only that one.
    #[test]
    fn retry_queue_never_enrolls_an_attachment_caption_row() {
        let (_temp, service) = service();
        let account = service
            .sync_accounts_from_numbers(
                &[("+15555550100".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap()
            .remove(0);
        let conversation = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        let attachment_pending = match service
            .prepare_send_attachment(
                &account.id,
                &AttachmentSendTarget::Conversation(&conversation.id),
                "req-caption-1",
                "YXR0YWNobWVudCBieXRlcw==",
                16,
                Some("notes.txt"),
                Some("text/plain"),
                Some("see attachment"),
                None,
                false,
                false,
                None,
                false,
            )
            .unwrap()
        {
            PreparedSend::Dispatch { pending_id, .. } => pending_id,
            PreparedSend::Existing(_) => panic!("new request must dispatch"),
        };
        let text_pending = match service
            .prepare_send_text(
                &account.id,
                &conversation.id,
                "plain queued text",
                "req-caption-2",
                None,
                None,
                None,
                None,
                None,
                None,
            )
            .unwrap()
        {
            PreparedSend::Dispatch { pending_id, .. } => pending_id,
            PreparedSend::Existing(_) => panic!("new request must dispatch"),
        };
        // Both rows fail with the same retryable class; only the text row
        // may arm a schedule.
        service
            .complete_send_failed_for_engine(&attachment_pending, &EngineError::ServerUnavailable)
            .unwrap();
        service
            .complete_send_failed_for_engine(&text_pending, &EngineError::ServerUnavailable)
            .unwrap();
        let face = |service: &ConnectorService, id: &str| {
            service
                .store_ref()
                .conn()
                .query_row(
                    "SELECT status, first_send_attempted_at, retry_attempt_count, next_attempt_at
                     FROM messages WHERE id=?1",
                    params![id],
                    |row| {
                        Ok((
                            row.get::<_, String>(0)?,
                            row.get::<_, Option<i64>>(1)?,
                            row.get::<_, i64>(2)?,
                            row.get::<_, Option<i64>>(3)?,
                        ))
                    },
                )
                .unwrap()
        };
        assert_eq!(
            face(&service, &attachment_pending),
            ("failed".into(), None, 0, None),
            "the captioned attachment row settles plain-failed, schedule retired"
        );
        let (_, first, count, next) = face(&service, &text_pending);
        assert!(
            first.is_some() && count == 1 && next.is_some(),
            "the text row enrolls"
        );

        // The claim takes exactly the text row; the attachment row is not in
        // the queue and not flipped.
        let due_now = crate::link::now_ms() + 5_000;
        let claims = service.store_ref().claim_due_retries(due_now, 10).unwrap();
        assert_eq!(claims.len(), 1, "{claims:?}");
        assert_eq!(claims[0].message_id, text_pending);
        assert_eq!(face(&service, &attachment_pending).0, "failed");
    }

    /// §4.262 (contract revision 1.278): an attachment retry re-sends the
    /// ORIGINAL row — same id, same clientRequestId, one history row — with
    /// this request's faces, and the regular settlement lands on it. The
    /// failed row is rearmed, never deleted and never duplicated.
    #[test]
    fn retry_attachment_rearms_the_original_row_and_keeps_one_history_row() {
        let (_temp, service) = service();
        let account = service
            .sync_accounts_from_numbers(
                &[("+15555550100".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap()
            .remove(0);
        let conversation = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        let b64 = "YXR0YWNobWVudCBieXRlcw=="; // base64 of "attachment bytes"
        let row_count = |service: &ConnectorService| -> i64 {
            service
                .store_ref()
                .conn()
                .query_row(
                    "SELECT COUNT(*) FROM messages WHERE account_id=?1 AND conversation_id=?2",
                    params![account.id.as_str(), conversation.id.as_str()],
                    |row| row.get(0),
                )
                .unwrap()
        };
        let pending_id = match service
            .prepare_send_attachment(
                &account.id,
                &AttachmentSendTarget::Conversation(&conversation.id),
                "req-attach-retry",
                b64,
                16,
                Some("notes.txt"),
                Some("text/plain"),
                Some("first caption"),
                None,
                false,
                false,
                None,
                false,
            )
            .unwrap()
        {
            PreparedSend::Dispatch { pending_id, .. } => pending_id,
            PreparedSend::Existing(_) => panic!("a fresh request must dispatch"),
        };
        service
            .complete_send_failed_for_engine(&pending_id, &EngineError::ServerUnavailable)
            .unwrap();
        let failed = service
            .store_ref()
            .message_by_id(&account.id, &conversation.id, &pending_id)
            .unwrap()
            .unwrap();
        assert_eq!(failed.status, "failed");
        assert_eq!(row_count(&service), 1);

        let retried = service
            .prepare_retry_attachment(
                &account.id,
                &AttachmentSendTarget::Conversation(&conversation.id),
                "req-attach-retry",
                Some(b64),
                Some(16),
                Some("notes.txt"),
                Some("text/plain"),
                Some("retry caption"),
                None,
                false,
                false,
                None,
                false,
            )
            .unwrap();
        let PreparedSend::Dispatch {
            pending_id: retry_id,
            params,
            pending_sent_at,
            ..
        } = &retried
        else {
            panic!("a failed row must re-dispatch, not replay");
        };
        assert_eq!(retry_id, &pending_id, "the retry keeps the original row id");
        assert_eq!(
            *pending_sent_at, failed.sent_at,
            "the row keeps its original timeline stamp"
        );
        assert_eq!(params["message"], "retry caption");
        assert_eq!(
            params["attachments"][0].as_str().unwrap(),
            "data:text/plain;filename=notes.txt;base64,YXR0YWNobWVudCBieXRlcw==",
            "the retry carries the bytes again — the engine re-uploads them"
        );
        assert_eq!(row_count(&service), 1, "a retry never adds a row");
        let rearmed = service
            .store_ref()
            .message_by_id(&account.id, &conversation.id, &pending_id)
            .unwrap()
            .unwrap();
        assert_eq!(rearmed.status, "pending");
        assert_eq!(
            rearmed.client_request_id.as_deref(),
            Some("req-attach-retry")
        );
        assert_eq!(rearmed.text.as_deref(), Some("retry caption"));
        assert_eq!(rearmed.attachments.len(), 1);
        assert_eq!(
            rearmed.attachments[0].id, failed.attachments[0].id,
            "the descriptor id is the first attempt's own (same bytes slot)"
        );
        // The manual retry is a NEW job: the automatic face is retired with
        // the rearm (the §4.123 window never survives a manual retry).
        let schedule: (String, Option<i64>, i64, Option<i64>) = service
            .store_ref()
            .conn()
            .query_row(
                "SELECT status, first_send_attempted_at, retry_attempt_count, next_attempt_at
                 FROM messages WHERE id=?1",
                params![pending_id],
                |row| Ok((row.get(0)?, row.get(1)?, row.get(2)?, row.get(3)?)),
            )
            .unwrap();
        assert_eq!(schedule, ("pending".into(), None, 0, None));

        // Settlement completes the SAME row, so the history still holds one
        // row and the ledger row is the one the retry addressed.
        let (settled, _events) = service
            .complete_send_success(&pending_id, &account.id, &conversation.id, 424_242, None)
            .unwrap();
        assert_eq!(settled.id, pending_id);
        assert_eq!(settled.status, "sent");
        assert_eq!(row_count(&service), 1);
        let by_request = service
            .store_ref()
            .message_by_client_request(&account.id, "req-attach-retry")
            .unwrap()
            .unwrap();
        assert_eq!(by_request.id, pending_id);
        assert_eq!(by_request.status, "sent");
    }

    /// §4.262 guards: a row still in flight answers RETRY_IN_FLIGHT (never a
    /// second dispatch of the same row), and a row whose original send
    /// already completed answers the §4.172 idempotent replay untouched.
    #[test]
    fn retry_attachment_refuses_in_flight_and_replays_a_completed_row() {
        let (_temp, service) = service();
        let account = service
            .sync_accounts_from_numbers(
                &[("+15555550100".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap()
            .remove(0);
        let conversation = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        let b64 = "YXR0YWNobWVudCBieXRlcw==";
        let pending_id = match service
            .prepare_send_attachment(
                &account.id,
                &AttachmentSendTarget::Conversation(&conversation.id),
                "req-attach-inflight",
                b64,
                16,
                Some("notes.txt"),
                Some("text/plain"),
                Some("hello"),
                None,
                false,
                false,
                None,
                false,
            )
            .unwrap()
        {
            PreparedSend::Dispatch { pending_id, .. } => pending_id,
            PreparedSend::Existing(_) => panic!("a fresh request must dispatch"),
        };

        let error = service
            .prepare_retry_attachment(
                &account.id,
                &AttachmentSendTarget::Conversation(&conversation.id),
                "req-attach-inflight",
                Some(b64),
                Some(16),
                Some("notes.txt"),
                Some("text/plain"),
                None,
                None,
                false,
                false,
                None,
                false,
            )
            .unwrap_err();
        assert_eq!(error.into_api().code, "RETRY_IN_FLIGHT");
        let row = service
            .store_ref()
            .message_by_id(&account.id, &conversation.id, &pending_id)
            .unwrap()
            .unwrap();
        assert_eq!(row.status, "pending", "the refusal never rearmed a row");

        service
            .complete_send_success(&pending_id, &account.id, &conversation.id, 777, None)
            .unwrap();
        let replay = service
            .prepare_retry_attachment(
                &account.id,
                &AttachmentSendTarget::Conversation(&conversation.id),
                "req-attach-inflight",
                Some(b64),
                Some(16),
                Some("notes.txt"),
                Some("text/plain"),
                None,
                None,
                false,
                false,
                None,
                false,
            )
            .unwrap();
        let PreparedSend::Existing(row) = &replay else {
            panic!("a completed original must replay, never re-dispatch");
        };
        assert_eq!(row.id, pending_id);
        assert_eq!(row.status, "sent", "the replay answers the persisted row");
        assert_eq!(row.attachments.len(), 1);
    }

    /// §4.262 guards: this face re-sends attachments only — a text row
    /// (messages.retryText owns it) and an unknown clientRequestId refuse
    /// deterministically, and a plural row refuses CALLER-SUPPLIED bytes
    /// (contract 1.280, §4.264: one call cannot restate every entry's byte set;
    /// the plural row retries ids-only from its persisted group, see
    /// `retry_attachment_multi_ids_only_rebuilds_every_payload_same_row`).
    #[test]
    fn retry_attachment_refuses_text_and_multi_rows_and_a_missing_row() {
        let (_temp, service) = service();
        let account = service
            .sync_accounts_from_numbers(
                &[("+15555550100".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap()
            .remove(0);
        let conversation = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        let b64 = "YXR0YWNobWVudCBieXRlcw==";

        // A failed TEXT row: this face refuses it too (status settled, then no
        // attachment descriptor left); messages.retryText owns it.
        let text_pending = match service
            .prepare_send_text(
                &account.id,
                &conversation.id,
                "hello",
                "req-text-retry",
                None,
                None,
                None,
                None,
                None,
                None,
            )
            .unwrap()
        {
            PreparedSend::Dispatch { pending_id, .. } => pending_id,
            PreparedSend::Existing(_) => panic!("a fresh request must dispatch"),
        };
        service
            .complete_send_failed_for_engine(&text_pending, &EngineError::ServerUnavailable)
            .unwrap();
        let error = service
            .prepare_retry_attachment(
                &account.id,
                &AttachmentSendTarget::Conversation(&conversation.id),
                "req-text-retry",
                Some(b64),
                Some(16),
                None,
                Some("text/plain"),
                None,
                None,
                false,
                false,
                None,
                false,
            )
            .unwrap_err();
        assert_eq!(error.into_api().code, "RETRY_NOT_ALLOWED");

        // A failed MULTI-attachment row refuses caller bytes: one call cannot
        // restate every entry's byte set (its persisted group is the retry
        // source).
        let multi_pending = match service
            .prepare_send_attachment_multi(
                &account.id,
                &AttachmentSendTarget::Conversation(&conversation.id),
                "req-multi-retry",
                &[
                    MessagesSendAttachmentEntry {
                        data_base64: b64.into(),
                        size_bytes: 16,
                        filename: Some("one.txt".into()),
                        content_type: Some("text/plain".into()),
                        blur_hash: None,
                        gif: false,
                    },
                    MessagesSendAttachmentEntry {
                        data_base64: b64.into(),
                        size_bytes: 16,
                        filename: Some("two.txt".into()),
                        content_type: Some("text/plain".into()),
                        blur_hash: None,
                        gif: false,
                    },
                ],
                None,
                None,
            )
            .unwrap()
        {
            PreparedSend::Dispatch { pending_id, .. } => pending_id,
            PreparedSend::Existing(_) => panic!("a fresh request must dispatch"),
        };
        service
            .complete_send_failed_for_engine(&multi_pending, &EngineError::ServerUnavailable)
            .unwrap();
        let error = service
            .prepare_retry_attachment(
                &account.id,
                &AttachmentSendTarget::Conversation(&conversation.id),
                "req-multi-retry",
                Some(b64),
                Some(16),
                None,
                Some("text/plain"),
                None,
                None,
                false,
                false,
                None,
                false,
            )
            .unwrap_err();
        assert_eq!(error.into_api().code, "RETRY_NOT_ALLOWED");

        // No row at all: the original request never arrived.
        let error = service
            .prepare_retry_attachment(
                &account.id,
                &AttachmentSendTarget::Conversation(&conversation.id),
                "req-never-arrived",
                Some(b64),
                Some(16),
                None,
                Some("text/plain"),
                None,
                None,
                false,
                false,
                None,
                false,
            )
            .unwrap_err();
        assert_eq!(error.into_api().code, "MESSAGE_NOT_FOUND");
    }

    /// §4.262 守卫顺序：状态先判、描述符后判。一条 failed 的附件行如果已经没有
    /// 任何 descriptor，答案必须是「没有描述符可重建」，绝不是「这是文本消息，
    /// 请用 retryText」——它本来就是附件行，retryText 也会以同样的理由拒绝它。
    /// 行还在 pending 时同样先按状态答 RETRY_IN_FLIGHT，不会因为描述符缺席被
    /// 误判成文本。
    #[test]
    fn retry_attachment_without_descriptors_never_answers_as_a_text_send() {
        let (_temp, service) = service();
        let account = service
            .sync_accounts_from_numbers(
                &[("+15555550100".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap()
            .remove(0);
        let conversation = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        let b64 = "YXR0YWNobWVudCBieXRlcw==";
        let pending_id = match service
            .prepare_send_attachment(
                &account.id,
                &AttachmentSendTarget::Conversation(&conversation.id),
                "req-descriptor-less",
                b64,
                16,
                Some("notes.txt"),
                Some("text/plain"),
                None,
                None,
                false,
                false,
                None,
                false,
            )
            .unwrap()
        {
            PreparedSend::Dispatch { pending_id, .. } => pending_id,
            PreparedSend::Existing(_) => panic!("a fresh request must dispatch"),
        };
        // The row loses its descriptor face (a pre-1.15 attachment row, or one
        // whose attachment face was erased).
        service
            .store_ref()
            .conn()
            .execute(
                "UPDATE messages SET attachments_json=NULL WHERE id=?1",
                params![pending_id],
            )
            .unwrap();

        // Status first: an in-flight retry is answered by its state.
        let error = service
            .prepare_retry_attachment(
                &account.id,
                &AttachmentSendTarget::Conversation(&conversation.id),
                "req-descriptor-less",
                None,
                None,
                None,
                None,
                None,
                None,
                false,
                false,
                None,
                false,
            )
            .unwrap_err()
            .into_api();
        assert_eq!(error.code, "RETRY_IN_FLIGHT");
        assert!(
            !error.message.contains("text send"),
            "an in-flight attachment row is never answered as a text send: {}",
            error.message
        );

        service
            .complete_send_failed_for_engine(&pending_id, &EngineError::ServerUnavailable)
            .unwrap();
        let error = service
            .prepare_retry_attachment(
                &account.id,
                &AttachmentSendTarget::Conversation(&conversation.id),
                "req-descriptor-less",
                None,
                None,
                None,
                None,
                None,
                None,
                false,
                false,
                None,
                false,
            )
            .unwrap_err()
            .into_api();
        assert_eq!(error.code, "RETRY_NOT_ALLOWED");
        assert!(
            error.message.contains("attachment descriptors"),
            "a descriptor-less failed attachment answers about its descriptors: {}",
            error.message
        );
        assert!(
            !error.message.contains("text send"),
            "a descriptor-less failed attachment is never answered as a text send: {}",
            error.message
        );

        // The rejection leaves the row exactly as it was: still failed, still
        // one row, still one clientRequestId.
        let row = service
            .store_ref()
            .message_by_id(&account.id, &conversation.id, &pending_id)
            .unwrap()
            .unwrap();
        assert_eq!(row.status, "failed");
        assert!(row.attachments.is_empty());
        assert_eq!(
            row.client_request_id.as_deref(),
            Some("req-descriptor-less")
        );
    }

    /// §4.262: the payload is validated before the store is touched, so a
    /// rejected retry leaves the failed row exactly as it was — still
    /// retryable, never half-rearmed.
    #[test]
    fn retry_attachment_rejects_a_bad_payload_without_touching_the_row() {
        let (_temp, service) = service();
        let account = service
            .sync_accounts_from_numbers(
                &[("+15555550100".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap()
            .remove(0);
        let conversation = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        let b64 = "YXR0YWNobWVudCBieXRlcw==";
        let pending_id = match service
            .prepare_send_attachment(
                &account.id,
                &AttachmentSendTarget::Conversation(&conversation.id),
                "req-attach-bad-retry",
                b64,
                16,
                Some("notes.txt"),
                Some("text/plain"),
                Some("hello"),
                None,
                false,
                false,
                None,
                false,
            )
            .unwrap()
        {
            PreparedSend::Dispatch { pending_id, .. } => pending_id,
            PreparedSend::Existing(_) => panic!("a fresh request must dispatch"),
        };
        service
            .complete_send_failed_for_engine(&pending_id, &EngineError::ServerUnavailable)
            .unwrap();

        // A size mismatch is the first send's own rejection class.
        let error = service
            .prepare_retry_attachment(
                &account.id,
                &AttachmentSendTarget::Conversation(&conversation.id),
                "req-attach-bad-retry",
                Some(b64),
                Some(15),
                Some("notes.txt"),
                Some("text/plain"),
                None,
                None,
                false,
                false,
                None,
                false,
            )
            .unwrap_err();
        assert_eq!(error.into_api().code, "INVALID_REQUEST");
        let row = service
            .store_ref()
            .message_by_id(&account.id, &conversation.id, &pending_id)
            .unwrap()
            .unwrap();
        assert_eq!(row.status, "failed", "a rejected retry changes nothing");
        assert_eq!(
            row.client_request_id.as_deref(),
            Some("req-attach-bad-retry")
        );

        // The same id still retries once the payload is well-formed.
        let recovered = service
            .prepare_retry_attachment(
                &account.id,
                &AttachmentSendTarget::Conversation(&conversation.id),
                "req-attach-bad-retry",
                Some(b64),
                Some(16),
                Some("notes.txt"),
                Some("text/plain"),
                None,
                None,
                false,
                false,
                None,
                false,
            )
            .unwrap();
        assert!(matches!(
            recovered,
            PreparedSend::Dispatch { pending_id: ref retried_id, .. } if retried_id == &pending_id
        ));
    }

    /// §4.263 (contract 1.279): the first send persists its original data URI,
    /// a failure keeps it across a store reopen, and the retry may omit
    /// dataBase64/sizeBytes — it restores the same bytes on the same row id.
    /// Success deletes the payload.
    #[test]
    fn retry_attachment_reuses_the_persisted_payload_after_a_store_reopen() {
        let (temp, service) = service();
        let account = service
            .sync_accounts_from_numbers(
                &[("+15555550100".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap()
            .remove(0);
        let conversation = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        let b64 = "YXR0YWNobWVudCBieXRlcw==";
        let data_uri = "data:text/plain;filename=notes.txt;base64,YXR0YWNobWVudCBieXRlcw==";
        let client_request_id = "req-attach-payload";
        let pending_id = match service
            .prepare_send_attachment(
                &account.id,
                &AttachmentSendTarget::Conversation(&conversation.id),
                client_request_id,
                b64,
                16,
                Some("notes.txt"),
                Some("text/plain"),
                Some("hello"),
                None,
                false,
                false,
                None,
                false,
            )
            .unwrap()
        {
            PreparedSend::Dispatch { pending_id, .. } => pending_id,
            PreparedSend::Existing(_) => panic!("a fresh request must dispatch"),
        };
        assert_eq!(
            service
                .store_ref()
                .outgoing_attachment_payload(&account.id, client_request_id, 0)
                .unwrap()
                .as_deref(),
            Some(data_uri),
            "the first send persists the original data URI"
        );
        // A repeated first send under the same clientRequestId is the
        // idempotent replay: it answers the existing row and never overwrites
        // the persisted payload with the newer request's bytes.
        let replay = service
            .prepare_send_attachment(
                &account.id,
                &AttachmentSendTarget::Conversation(&conversation.id),
                client_request_id,
                "b3RoZXIgYnl0ZXM=",
                11,
                Some("other.bin"),
                Some("application/octet-stream"),
                None,
                None,
                false,
                false,
                None,
                false,
            )
            .unwrap();
        assert!(matches!(replay, PreparedSend::Existing(_)));
        assert_eq!(
            service
                .store_ref()
                .outgoing_attachment_payload(&account.id, client_request_id, 0)
                .unwrap()
                .as_deref(),
            Some(data_uri),
            "the idempotent replay preserves the original payload"
        );
        service
            .complete_send_failed_for_engine(&pending_id, &EngineError::ServerUnavailable)
            .unwrap();
        assert_eq!(
            service
                .store_ref()
                .outgoing_attachment_payload(&account.id, client_request_id, 0)
                .unwrap()
                .as_deref(),
            Some(data_uri),
            "a definitively failed send keeps the payload"
        );

        // The desktop refreshed/restarted: only the persisted store survives.
        drop(service);
        let store = Store::open(temp.path(), Some(StoreKey::from_bytes([0x5A; 32]))).unwrap();
        assert_eq!(
            store
                .outgoing_attachment_payload(&account.id, client_request_id, 0)
                .unwrap()
                .as_deref(),
            Some(data_uri),
            "a new store instance still reads the payload"
        );
        let service = ConnectorService::new(Arc::new(store));

        let retried = service
            .prepare_retry_attachment(
                &account.id,
                &AttachmentSendTarget::Conversation(&conversation.id),
                client_request_id,
                None,
                None,
                None,
                None,
                None,
                None,
                false,
                false,
                None,
                false,
            )
            .unwrap();
        let PreparedSend::Dispatch {
            pending_id: retry_id,
            params,
            ..
        } = &retried
        else {
            panic!("a failed row must re-dispatch, not replay");
        };
        assert_eq!(retry_id, &pending_id, "the retry keeps the original row id");
        assert_eq!(
            params["attachments"][0].as_str(),
            Some(data_uri),
            "the retry rebuilds the original bytes from the persisted payload"
        );
        assert_eq!(
            params["message"].as_str(),
            Some("hello"),
            "ids-only retry restores the original caption from the row"
        );

        let (settled, _events) = service
            .complete_send_success(&pending_id, &account.id, &conversation.id, 515_151, None)
            .unwrap();
        assert_eq!(settled.id, pending_id);
        assert_eq!(
            service
                .store_ref()
                .outgoing_attachment_payload(&account.id, client_request_id, 0)
                .unwrap(),
            None,
            "success deletes the payload"
        );
    }

    /// §4.264 (contract revision 1.280): a plural send persists one payload row
    /// per attachment index. A failed multi-attachment row is therefore retried
    /// ids-only after a restart: the connector rebuilds EVERY entry's bytes from
    /// its own index, re-dispatches the plural shape under the SAME row id, and a
    /// successful settlement clears the whole group.
    #[test]
    fn retry_attachment_multi_ids_only_rebuilds_every_payload_same_row() {
        let (temp, service) = service();
        let account = service
            .sync_accounts_from_numbers(
                &[("+15555550100".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap()
            .remove(0);
        let conversation = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        let client_request_id = "req-multi-payload";
        // "attachment bytes" / "second attachment"
        let first_uri = "data:text/plain;filename=one.txt;base64,YXR0YWNobWVudCBieXRlcw==";
        let second_uri = "data:application/octet-stream;gif=true;filename=two.bin;base64,c2Vjb25kIGF0dGFjaG1lbnQ=";
        let pending_id = match service
            .prepare_send_attachment_multi(
                &account.id,
                &AttachmentSendTarget::Conversation(&conversation.id),
                client_request_id,
                &[
                    MessagesSendAttachmentEntry {
                        data_base64: "YXR0YWNobWVudCBieXRlcw==".into(),
                        size_bytes: 16,
                        filename: Some("one.txt".into()),
                        content_type: Some("text/plain".into()),
                        blur_hash: None,
                        gif: false,
                    },
                    MessagesSendAttachmentEntry {
                        data_base64: "c2Vjb25kIGF0dGFjaG1lbnQ=".into(),
                        size_bytes: 17,
                        filename: Some("two.bin".into()),
                        content_type: Some("application/octet-stream".into()),
                        blur_hash: None,
                        gif: true,
                    },
                ],
                Some("first caption"),
                None,
            )
            .unwrap()
        {
            PreparedSend::Dispatch { pending_id, .. } => pending_id,
            PreparedSend::Existing(_) => panic!("a fresh request must dispatch"),
        };
        assert_eq!(
            service
                .store_ref()
                .outgoing_attachment_payloads(&account.id, client_request_id)
                .unwrap(),
            vec![(0, first_uri.to_string()), (1, second_uri.to_string())],
            "the plural send persists every entry at its own index"
        );
        service
            .complete_send_failed_for_engine(&pending_id, &EngineError::ServerUnavailable)
            .unwrap();
        let failed = service
            .store_ref()
            .message_by_id(&account.id, &conversation.id, &pending_id)
            .unwrap()
            .unwrap();
        assert_eq!(failed.status, "failed");
        assert_eq!(failed.attachments.len(), 2);
        let descriptor_ids: Vec<String> = failed
            .attachments
            .iter()
            .map(|entry| entry.id.clone())
            .collect();
        assert_eq!(
            service
                .store_ref()
                .outgoing_attachment_payloads(&account.id, client_request_id)
                .unwrap()
                .len(),
            2,
            "a failed plural send keeps its whole payload group"
        );

        // The desktop refreshed/restarted: only the persisted store survives.
        drop(service);
        let store = Store::open(temp.path(), Some(StoreKey::from_bytes([0x5A; 32]))).unwrap();
        assert_eq!(
            store
                .outgoing_attachment_payloads(&account.id, client_request_id)
                .unwrap()
                .len(),
            2,
            "a new store instance still reads the whole group"
        );
        let service = ConnectorService::new(Arc::new(store));

        let retried = service
            .prepare_retry_attachment(
                &account.id,
                &AttachmentSendTarget::Conversation(&conversation.id),
                client_request_id,
                None,
                None,
                None,
                None,
                Some("retry caption"),
                None,
                false,
                false,
                None,
                false,
            )
            .unwrap();
        let PreparedSend::Dispatch {
            pending_id: retry_id,
            params,
            pending_sent_at,
            ..
        } = &retried
        else {
            panic!("a failed plural row must re-dispatch, not replay");
        };
        assert_eq!(retry_id, &pending_id, "the retry keeps the original row id");
        assert_eq!(
            *pending_sent_at, failed.sent_at,
            "the row keeps its timeline stamp"
        );
        let dispatched = params["attachments"].as_array().unwrap();
        assert_eq!(
            dispatched.len(),
            2,
            "the plural shape is re-dispatched whole, never one entry"
        );
        assert_eq!(dispatched[0].as_str(), Some(first_uri));
        assert_eq!(dispatched[1].as_str(), Some(second_uri));
        assert_eq!(params["message"], "retry caption");
        let rearmed = service
            .store_ref()
            .message_by_id(&account.id, &conversation.id, &pending_id)
            .unwrap()
            .unwrap();
        assert_eq!(rearmed.status, "pending");
        assert_eq!(
            rearmed
                .attachments
                .iter()
                .map(|entry| entry.id.clone())
                .collect::<Vec<_>>(),
            descriptor_ids,
            "every descriptor keeps the first attempt's own id (same byte slots)"
        );
        assert_eq!(rearmed.attachments[0].filename.as_deref(), Some("one.txt"));
        assert_eq!(
            rearmed.attachments[0].content_type.as_deref(),
            Some("text/plain")
        );
        assert_eq!(rearmed.attachments[1].filename.as_deref(), Some("two.bin"));
        assert!(
            rearmed.attachments[1].is_gif,
            "the stored gif marker rides the rebuild"
        );
        assert_eq!(rearmed.attachments[1].size, Some(17));
        let row_count: i64 = service
            .store_ref()
            .conn()
            .query_row(
                "SELECT COUNT(*) FROM messages WHERE account_id=?1 AND conversation_id=?2",
                params![account.id.as_str(), conversation.id.as_str()],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(row_count, 1, "a retry never adds a row");
        assert_eq!(
            service
                .store_ref()
                .outgoing_attachment_payloads(&account.id, client_request_id)
                .unwrap()
                .len(),
            2,
            "the rebuilt group is written back as the resend source"
        );

        let (settled, _events) = service
            .complete_send_success(&pending_id, &account.id, &conversation.id, 616_161, None)
            .unwrap();
        assert_eq!(settled.id, pending_id);
        assert_eq!(settled.status, "sent");
        assert!(
            service
                .store_ref()
                .outgoing_attachment_payloads(&account.id, client_request_id)
                .unwrap()
                .is_empty(),
            "success settles the row and clears the whole payload group"
        );
    }

    /// §4.264: the plural face refuses caller-supplied bytes (one call cannot
    /// restate every entry's byte set) and refuses an incomplete payload group —
    /// both before the rearm, so the failed row stays exactly as it was and stays
    /// retryable ids-only once the group is whole again.
    #[test]
    fn retry_attachment_multi_refuses_bytes_and_an_incomplete_payload_group() {
        let (_temp, service) = service();
        let account = service
            .sync_accounts_from_numbers(
                &[("+15555550100".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap()
            .remove(0);
        let conversation = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        let client_request_id = "req-multi-guard";
        let pending_id = match service
            .prepare_send_attachment_multi(
                &account.id,
                &AttachmentSendTarget::Conversation(&conversation.id),
                client_request_id,
                &[
                    MessagesSendAttachmentEntry {
                        data_base64: "YXR0YWNobWVudCBieXRlcw==".into(),
                        size_bytes: 16,
                        filename: Some("one.txt".into()),
                        content_type: Some("text/plain".into()),
                        blur_hash: None,
                        gif: false,
                    },
                    MessagesSendAttachmentEntry {
                        data_base64: "c2Vjb25kIGF0dGFjaG1lbnQ=".into(),
                        size_bytes: 17,
                        filename: Some("two.bin".into()),
                        content_type: Some("application/octet-stream".into()),
                        blur_hash: None,
                        gif: false,
                    },
                ],
                None,
                None,
            )
            .unwrap()
        {
            PreparedSend::Dispatch { pending_id, .. } => pending_id,
            PreparedSend::Existing(_) => panic!("a fresh request must dispatch"),
        };
        service
            .complete_send_failed_for_engine(&pending_id, &EngineError::ServerUnavailable)
            .unwrap();

        // Caller bytes on a plural row: refused, row untouched.
        let error = service
            .prepare_retry_attachment(
                &account.id,
                &AttachmentSendTarget::Conversation(&conversation.id),
                client_request_id,
                Some("YXR0YWNobWVudCBieXRlcw=="),
                Some(16),
                Some("one.txt"),
                Some("text/plain"),
                None,
                None,
                false,
                false,
                None,
                false,
            )
            .unwrap_err();
        assert_eq!(error.into_api().code, "RETRY_NOT_ALLOWED");
        let row = service
            .store_ref()
            .message_by_id(&account.id, &conversation.id, &pending_id)
            .unwrap()
            .unwrap();
        assert_eq!(row.status, "failed", "the refusal never rearmed the row");

        // A group missing one index is not a rebuildable generation.
        assert!(
            service
                .store_ref()
                .delete_outgoing_attachment_payload(&account.id, client_request_id, 1)
                .unwrap(),
            "the fixture drops the second entry's payload"
        );
        let error = service
            .prepare_retry_attachment(
                &account.id,
                &AttachmentSendTarget::Conversation(&conversation.id),
                client_request_id,
                None,
                None,
                None,
                None,
                None,
                None,
                false,
                false,
                None,
                false,
            )
            .unwrap_err();
        assert_eq!(error.into_api().code, "RETRY_NOT_ALLOWED");
        assert_eq!(
            service
                .store_ref()
                .message_by_id(&account.id, &conversation.id, &pending_id)
                .unwrap()
                .unwrap()
                .status,
            "failed"
        );

        // Restoring the missing index (per-index remember) makes it retryable.
        service
            .store_ref()
            .remember_outgoing_attachment_payload(
                &account.id,
                &conversation.id,
                client_request_id,
                1,
                "data:application/octet-stream;filename=two.bin;base64,c2Vjb25kIGF0dGFjaG1lbnQ=",
                crate::link::now_ms(),
            )
            .unwrap();
        let retried = service
            .prepare_retry_attachment(
                &account.id,
                &AttachmentSendTarget::Conversation(&conversation.id),
                client_request_id,
                None,
                None,
                None,
                None,
                None,
                None,
                false,
                false,
                None,
                false,
            )
            .unwrap();
        assert!(matches!(
            retried,
            PreparedSend::Dispatch { pending_id: ref retried_id, .. } if retried_id == &pending_id
        ));
    }

    /// §4.263: a retry without bytes needs the persisted payload. When the row
    /// is gone (legacy store, pruned, or never persisted) the retry answers
    /// RETRY_NOT_ALLOWED and leaves the failed row retryable with bytes; the
    /// caller-supplied arm restores the payload for the next refresh.
    #[test]
    fn retry_attachment_without_bytes_refuses_a_missing_payload() {
        let (_temp, service) = service();
        let account = service
            .sync_accounts_from_numbers(
                &[("+15555550100".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap()
            .remove(0);
        let conversation = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        let b64 = "YXR0YWNobWVudCBieXRlcw==";
        let data_uri = "data:text/plain;filename=notes.txt;base64,YXR0YWNobWVudCBieXRlcw==";
        let client_request_id = "req-attach-no-payload";
        let pending_id = match service
            .prepare_send_attachment(
                &account.id,
                &AttachmentSendTarget::Conversation(&conversation.id),
                client_request_id,
                b64,
                16,
                Some("notes.txt"),
                Some("text/plain"),
                None,
                None,
                false,
                false,
                None,
                false,
            )
            .unwrap()
        {
            PreparedSend::Dispatch { pending_id, .. } => pending_id,
            PreparedSend::Existing(_) => panic!("a fresh request must dispatch"),
        };
        service
            .complete_send_failed_for_engine(&pending_id, &EngineError::ServerUnavailable)
            .unwrap();
        assert!(
            service
                .store_ref()
                .delete_outgoing_attachment_payloads(&account.id, client_request_id)
                .unwrap()
                > 0,
            "the fixture removes the persisted payload"
        );

        let error = service
            .prepare_retry_attachment(
                &account.id,
                &AttachmentSendTarget::Conversation(&conversation.id),
                client_request_id,
                None,
                None,
                Some("notes.txt"),
                Some("text/plain"),
                None,
                None,
                false,
                false,
                None,
                false,
            )
            .unwrap_err();
        assert_eq!(error.into_api().code, "RETRY_NOT_ALLOWED");
        let row = service
            .store_ref()
            .message_by_id(&account.id, &conversation.id, &pending_id)
            .unwrap()
            .unwrap();
        assert_eq!(row.status, "failed", "the refusal never rearmed the row");

        let retried = service
            .prepare_retry_attachment(
                &account.id,
                &AttachmentSendTarget::Conversation(&conversation.id),
                client_request_id,
                Some(b64),
                Some(16),
                Some("notes.txt"),
                Some("text/plain"),
                None,
                None,
                false,
                false,
                None,
                false,
            )
            .unwrap();
        assert!(matches!(
            retried,
            PreparedSend::Dispatch { pending_id: ref retried_id, .. } if retried_id == &pending_id
        ));
        assert_eq!(
            service
                .store_ref()
                .outgoing_attachment_payload(&account.id, client_request_id, 0)
                .unwrap()
                .as_deref(),
            Some(data_uri),
            "caller-supplied bytes restore the persisted payload"
        );
    }

    /// §4.263: payload rows follow the same deletion cascades as the message
    /// they belong to — dropping the conversation or the account removes the
    /// original bytes too (the account deletion receipt counts them).
    #[test]
    fn attachment_payloads_follow_conversation_and_account_deletes() {
        let (_temp, service) = service();
        let account = service
            .sync_accounts_from_numbers(
                &[("+15555550100".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap()
            .remove(0);
        let conversation = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        let b64 = "YXR0YWNobWVudCBieXRlcw==";
        let client_request_id = "req-attach-cascade";
        let pending_id = match service
            .prepare_send_attachment(
                &account.id,
                &AttachmentSendTarget::Conversation(&conversation.id),
                client_request_id,
                b64,
                16,
                Some("notes.txt"),
                Some("text/plain"),
                None,
                None,
                false,
                false,
                None,
                false,
            )
            .unwrap()
        {
            PreparedSend::Dispatch { pending_id, .. } => pending_id,
            PreparedSend::Existing(_) => panic!("a fresh request must dispatch"),
        };
        service
            .complete_send_failed_for_engine(&pending_id, &EngineError::ServerUnavailable)
            .unwrap();
        assert!(
            service
                .store_ref()
                .outgoing_attachment_payload(&account.id, client_request_id, 0)
                .unwrap()
                .is_some()
        );
        assert!(
            service
                .store_ref()
                .delete_conversation(&account.id, &conversation.id, None, true)
                .unwrap()
                .is_some()
        );
        assert_eq!(
            service
                .store_ref()
                .outgoing_attachment_payload(&account.id, client_request_id, 0)
                .unwrap(),
            None,
            "the conversation delete takes the payload with it"
        );

        let other = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", "+15555550102", "Other")
            .unwrap();
        let account_request = "req-attach-account-cascade";
        let account_pending = match service
            .prepare_send_attachment(
                &account.id,
                &AttachmentSendTarget::Conversation(&other.id),
                account_request,
                b64,
                16,
                Some("notes.txt"),
                Some("text/plain"),
                None,
                None,
                false,
                false,
                None,
                false,
            )
            .unwrap()
        {
            PreparedSend::Dispatch { pending_id, .. } => pending_id,
            PreparedSend::Existing(_) => panic!("a fresh request must dispatch"),
        };
        service
            .complete_send_failed_for_engine(&account_pending, &EngineError::ServerUnavailable)
            .unwrap();
        assert!(
            service
                .store_ref()
                .delete_account_cascade(&account.id)
                .unwrap()
        );
        assert_eq!(
            service
                .store_ref()
                .outgoing_attachment_payload(&account.id, account_request, 0)
                .unwrap(),
            None,
            "the account delete takes the payload with it"
        );
        let receipt = service
            .store_ref()
            .account_delete_receipt(&account.id)
            .unwrap()
            .unwrap();
        assert_eq!(
            receipt.table_counts.get("outgoing_attachment_payloads"),
            Some(&1),
            "the deletion receipt counts the payload row"
        );
    }

    /// §4.264: an explicit delete cascades the WHOLE payload group — dropping
