    /// 契约 1.269（§4.253 · 批 Z14）：direct 语义的对端键词形闸——群
    /// master key base64 混进 kind=direct/contact 时 fail-closed（不 mint
    /// 怪 direct 行），UUID/电话键直通。附件 peer 臂同闸同词。
    #[test]
    fn send_by_peer_rejects_group_key_in_direct_semantics() {
        let (_temp, service) = service();
        let account = service
            .sync_accounts_from_numbers(
                &[("+15555550100".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap()
            .remove(0);

        // 群 key base64 拒收（文本面）。
        assert!(matches!(
            service.prepare_send_text_to_peer(
                &account.id,
                &PeerTarget {
                    kind: "contact",
                    peer_key: "D4DyutMEtvpawXahRoFH/5KPjE/z7ThINwByaAh7Zfw=",
                    peer_title: Some("Group Mistyped as Contact"),
                },
                "hello",
                "gate-req-1",
                None,
                None,
                None,
                None,
                None,
                None,
            ),
            Err(ServiceError::Api(ref api))
                if api.code == "INVALID_REQUEST"
        ));
        // 直聊行未被 mint。
        assert!(
            service
                .list_conversations(&account.id, 10, None)
                .unwrap()
                .items
                .is_empty()
        );

        // 附件 peer 臂同闸（payload 校验先于上行——INVALID_REQUEST 只能
        // 出自词形闸；若闸缺席会走 ensure mint 后才在附件描述符校验失败，
        // 行集断言兜底）。
        let peer = AttachmentSendTarget::Peer(PeerTarget {
            kind: "direct",
            peer_key: "D4DyutMEtvpawXahRoFH/5KPjE/z7ThINwByaAh7Zfw=",
            peer_title: None,
        });
        assert!(matches!(
            service.prepare_send_attachment(
                &account.id,
                &peer,
                "gate-req-2",
                "aGVsbG8=",
                5,
                Some("fixture.bin"),
                Some("application/octet-stream"),
                None,
                None,
                false,
                false,
                None,
                false,
            ),
            Err(ServiceError::Api(ref api))
                if api.code == "INVALID_REQUEST"
        ));
        assert!(
            service
                .list_conversations(&account.id, 10, None)
                .unwrap()
                .items
                .is_empty()
        );

        // 协议词形直通：ACI UUID 与 +电话键都放行（不 mint 判定走发送臂
        // 既有链，这里只断言闸不拒）。
        for key in ["0b7fca57-1234-4d0e-9b0f-4f6c1f8a2e10", "+15555550111"] {
            let probe = PeerTarget {
                kind: "contact",
                peer_key: key,
                peer_title: None,
            };
            // 附件臂文件缺失先于上游——不落到 mint 判定即证明过了词形闸；
            // 若词形闸误拒会返回 INVALID_REQUEST（同 code），故以文本面
            // prepare 的 Dispatch 形为准。
            let prepared = service.prepare_send_text_to_peer(
                &account.id,
                &probe,
                "shape probe",
                &format!("gate-req-{key}"),
                None,
                None,
                None,
                None,
                None,
                None,
            );
            assert!(
                matches!(&prepared, Ok(PreparedSend::Dispatch { .. })),
                "protocol-shaped key {key} must pass the gate"
            );
        }
    }

    #[test]
    fn send_by_peer_creates_conversation_once_and_reuses_it() {
        let (_temp, service) = service();
        let account = service
            .sync_accounts_from_numbers(
                &[("+15555550100".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap()
            .remove(0);

        let first = match service
            .prepare_send_text_to_peer(
                &account.id,
                &PeerTarget {
                    kind: "contact",
                    peer_key: "+15555550109",
                    peer_title: Some("New Peer"),
                },
                "hello peer",
                "peer-req-1",
                None,
                None,
                None,
                None,
                None,
                None,
            )
            .unwrap()
        {
            PreparedSend::Dispatch {
                conversation_id,
                params,
                ..
            } => {
                assert_eq!(params["recipient"], json!(["+15555550109"]));
                conversation_id
            }
            PreparedSend::Existing(_) => panic!("first peer send must dispatch"),
        };
        // The conversation appears with the peer title only alongside this send.
        let conversations = service.list_conversations(&account.id, 10, None).unwrap();
        assert_eq!(conversations.items.len(), 1);
        assert_eq!(conversations.items[0].id, first);
        assert_eq!(conversations.items[0].title, "New Peer");

        // A new client request to the same peer reuses the same conversation.
        let second = match service
            .prepare_send_text_to_peer(
                &account.id,
                &PeerTarget {
                    kind: "direct",
                    peer_key: "+15555550109",
                    peer_title: None,
                },
                "hello again",
                "peer-req-2",
                None,
                None,
                None,
                None,
                None,
                None,
            )
            .unwrap()
        {
            PreparedSend::Dispatch {
                conversation_id, ..
            } => conversation_id,
            PreparedSend::Existing(_) => panic!("new client request must dispatch"),
        };
        assert_eq!(second, first);
        assert_eq!(
            service
                .list_conversations(&account.id, 10, None)
                .unwrap()
                .items
                .len(),
            1
        );

        // A repeated client request is idempotent regardless of the target form.
        assert!(matches!(
            service
                .prepare_send_text_to_peer(
                    &account.id,
                    &PeerTarget {
                        kind: "contact",
                        peer_key: "+15555550109",
                        peer_title: None,
                    },
                    "hello peer",
                    "peer-req-1",
                    None,
                    None,
                    None,
                    None,
                    None,
                    None,
                )
                .unwrap(),
            PreparedSend::Existing(_)
        ));
        assert!(matches!(
            service
                .prepare_send_text(
                    &account.id,
                    &first,
                    "hello peer",
                    "peer-req-1",
                    None,
                    None,
                    None,
                    None,
                    None,
                    None,
                )
                .unwrap(),
            PreparedSend::Existing(_)
        ));
    }

