    /// `messages.edit` preparation: an outgoing sent row resolves to
    /// engine `editMessage` params (contract 1.105 — the wire key is
    /// `targetTimestamp`, the edited row's protocol timestamp); settlement
    /// rewrites the body and stamps editedAt.
    #[test]
    fn prepare_edit_targets_sent_row_and_settlement_rewrites_it() {
        let (_temp, mut service) = service();
        let (account, conversation) = linked_account_and_conversation(&mut service);
        let pending = seed_outgoing_sent(&mut service, &account.id, &conversation.id, 430);

        let prepared = service
            .prepare_edit(&account.id, &conversation.id, &pending, "edited body")
            .unwrap();
        assert_eq!(
            prepared.params["targetTimestamp"], 430,
            "upstream edit targets the sent row's protocol timestamp"
        );
        assert_eq!(prepared.params["message"], "edited body");

        let record = service
            .complete_edit_success(&account.id, &conversation.id, &pending, "edited body")
            .unwrap()
            .expect("settlement of a sent row returns the updated record");
        assert_eq!(record.text.as_deref(), Some("edited body"));
        assert!(record.edited_at.is_some());
        assert_eq!(record.status, "sent");

        // An incoming row is not editable by us.
        let incoming = NormalizedReceive {
            required_protocol_version: None,
            timestamp: Some(440),
            content_kind: "dataMessage",
            direction: "incoming",
            account_present: true,
            account: Some("+15555550100".into()),
            source: Some("+15555550101".into()),
            source_uuid: None,
            peer_name: None,
            group_id: None,
            text: Some("peer says".into()),
            text_bytes: Some(9),
            text_truncated: false,
            quote: None,
            attachments: Vec::new(),
            rich: None,
            sticker: None,
            expire_seconds: None,
            expire_start_at: None,
            control: None,
            server_guid: None,
            reporting_token: None,
            server_timestamp: None,
        };
        service
            .ingest_receive(incoming, crate::DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let incoming_id = service
            .list_messages(&account.id, &conversation.id, 10, None)
            .unwrap()
            .items
            .into_iter()
            .find(|row| row.direction == "incoming")
            .unwrap()
            .id;
        let error = service
            .prepare_edit(&account.id, &conversation.id, &incoming_id, "nope")
            .unwrap_err();
        assert_eq!(error.into_api().code, "MESSAGE_NOT_FOUND");
    }

    /// Inbound quote + attachment metadata ride the message row end to end:
    /// ingest persists them, list_messages returns them verbatim.
    #[test]
    fn inbound_quote_and_attachment_metadata_roundtrip_through_the_store() {
        let (_temp, mut service) = service();
        let (account, conversation) = linked_account_and_conversation(&mut service);
        let receive = NormalizedReceive {
            required_protocol_version: None,
            timestamp: Some(360),
            content_kind: "dataMessage",
            direction: "incoming",
            account_present: true,
            account: Some("+15555550100".into()),
            source: Some("+15555550101".into()),
            source_uuid: None,
            peer_name: None,
            group_id: None,
            text: Some("replying with a file".into()),
            text_bytes: Some(20),
            text_truncated: false,
            quote: Some(NormalizedQuote {
                id: 350,
                author: "+15555550100".into(),
                text: "the original".into(),
                attachments: vec![NormalizedQuoteAttachment {
                    content_type: Some("image/png".into()),
                    filename: Some("quoted.png".into()),
                    thumbnail: Some(NormalizedAttachment {
                        id: "quote-thumb".into(),
                        content_type: Some("image/jpeg".into()),
                        filename: None,
                        size: Some(1024),
                        width: Some(64),
                        height: Some(64),
                        is_voice_note: false,
                        caption: None,
                        blur_hash: None,
                        incremental_mac: None,
                        chunk_size: None,
                        is_borderless: false,
                        is_gif: false,
                        waveform: None,
                        duration: None,
                        locator: None,
                    }),
                }],
            }),
            attachments: vec![NormalizedAttachment {
                id: "att-1".into(),
                content_type: Some("image/png".into()),
                filename: Some("shot.png".into()),
                size: Some(2048),
                width: Some(64),
                height: Some(32),
                is_voice_note: false,
                caption: None,
                blur_hash: None,
                incremental_mac: None,
                chunk_size: None,
                is_borderless: false,
                is_gif: false,
                locator: None,
                waveform: None,
                duration: None,
            }],
            rich: None,
            sticker: None,
            expire_seconds: None,
            expire_start_at: None,
            control: None,
            server_guid: None,
            reporting_token: None,
            server_timestamp: None,
        };
        service
            .ingest_receive(receive, crate::DEFAULT_PROXY_GROUP_ID)
            .unwrap();

        let row = service
            .list_messages(&account.id, &conversation.id, 10, None)
            .unwrap()
            .items
            .into_iter()
            .next()
            .unwrap();
        let quote = row
            .quote_snapshot
            .expect("quote snapshot survives the roundtrip");
        assert_eq!(quote.id, 350);
        assert_eq!(quote.author, "+15555550100");
        assert_eq!(quote.text, "the original");
        // The quoted-attachment metadata rides the same snapshot verbatim
        // (contract 1.100, §4.81 D4); the thumbnail's locator half stays
        // internal and never round-trips.
        assert_eq!(quote.attachments.len(), 1);
        let quoted = &quote.attachments[0];
        assert_eq!(quoted.content_type.as_deref(), Some("image/png"));
        assert_eq!(quoted.filename.as_deref(), Some("quoted.png"));
        let thumb = quoted.thumbnail.as_ref().expect("thumbnail survives");
        assert_eq!(thumb.id, "quote-thumb");
        assert_eq!(thumb.size, Some(1024));
        assert_eq!(thumb.locator, None);
        assert_eq!(row.attachments.len(), 1);
        assert_eq!(row.attachments[0].id, "att-1");
        assert_eq!(row.attachments[0].filename.as_deref(), Some("shot.png"));
        assert_eq!(row.attachments[0].size, Some(2048));
    }

    /// Contract 1.259 (§4.243, batch Z1 · S14), the receive seam: an
    /// inbound envelope whose contacts-hit peer key (the number) differs
    /// from the envelope ACI writes the bridge binding and — when a
    /// number-keyed shell row sits beside the ACI-keyed row — folds the
    /// pair. The just-landed row re-keys with its conversation (its id never
    /// changes), the A5 notice (the official gate minted one) and the
    /// `conversation.merged` frame ride after the landed frames, and the
    /// folded shell answers no trailing summary.
    #[test]
    fn ingest_receive_folds_the_discovered_double_row_and_reroutes_the_landed_row() {
        let (_temp, mut service) = service();
        let account = service
            .sync_accounts_from_numbers(
                &[("+15555550100".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap()
            .remove(0);
        const PEER_ACI: &str = "22222222-2222-4222-8222-222222222222";
        let peer_number = "+15555550101";
        let receive = |source: Option<&str>,
                       source_uuid: Option<&str>,
                       text: &str,
                       peer_name: Option<&str>,
                       ts: u64| {
            NormalizedReceive {
                required_protocol_version: None,
                timestamp: Some(ts),
                content_kind: "dataMessage",
                direction: "incoming",
                account_present: true,
                account: Some("+15555550100".into()),
                source: source.map(str::to_string),
                source_uuid: source_uuid.map(str::to_string),
                peer_name: peer_name.map(str::to_string),
                group_id: None,
                text: Some(text.into()),
                text_bytes: Some(text.len() as u32),
                text_truncated: false,
                quote: None,
                attachments: Vec::new(),
                rich: None,
                sticker: None,
                expire_seconds: None,
                expire_start_at: None,
                control: None,
                server_guid: None,
                reporting_token: None,
                server_timestamp: None,
            }
        };
        // The ACI-keyed live row first (the sealed-sender world: the
        // engine's peer resolution fell to sourceUuid, so the envelope's
        // source IS the ACI — the ingest keys the row on it and the binding
        // write skips its degenerate face).
        service
            .ingest_receive(
                receive(Some(PEER_ACI), Some(PEER_ACI), "live hello", None, 1_000),
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap();
        // The number-keyed shell row (the send-by-number / legacy world).
        service
            .ingest_receive(
                receive(
                    Some(peer_number),
                    None,
                    "shell hello",
                    Some("Shell Peer"),
                    2_000,
                ),
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap();
        let shell = service
            .store_ref()
            .conversation_by_peer(&account.id, "direct", peer_number)
            .unwrap()
            .expect("the shell row exists pre-fold");
        let live = service
            .store_ref()
            .conversation_by_peer(&account.id, "direct", PEER_ACI)
            .unwrap()
            .expect("the ACI row exists pre-fold");
        assert_ne!(shell.id, live.id);

        let events = service
            .ingest_receive(
                receive(
                    Some(peer_number),
                    Some(PEER_ACI),
                    "fold hello",
                    Some("Shell Peer"),
                    3_000,
                ),
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap();

        // The landed row rides the canonical conversation id.
        let landed = events
            .iter()
            .find_map(|event| match event {
                HostSideEvent::MessageUpserted(record)
                    if record.text.as_deref() == Some("fold hello") =>
                {
                    Some(record)
                }
                _ => None,
            })
            .expect("the landed row upserts");
        assert_eq!(
            landed.conversation_id, live.id,
            "the landed row re-keys with its conversation"
        );
        // The fold's frames: the A5 notice (both sides had messages, the
        // shell title useful) and the merged frame naming shell → canonical.
        let notice = events
            .iter()
            .find_map(|event| match event {
                HostSideEvent::MessageUpserted(record) if record.direction == "system" => {
                    Some(record)
                }
                _ => None,
            })
            .expect("the A5 notice rides its own upserted frame");
        let merge = notice
            .rich
            .as_ref()
            .and_then(|rich| rich.conversation_merge.as_ref())
            .expect("the notice carries the conversationMerge face");
        assert_eq!(
            merge.obsolete_conversation_title.as_deref(),
            Some("Shell Peer")
        );
        assert_eq!(
            merge.obsolete_conversation_number.as_deref(),
            Some(peer_number)
        );
        let merged = events
            .iter()
            .find_map(|event| match event {
                HostSideEvent::ConversationMerged {
                    account_id,
                    from_conversation_id,
                    to_conversation,
                } => Some((account_id, from_conversation_id, to_conversation)),
                _ => None,
            })
            .expect("the merged frame rides");
        assert_eq!(merged.0, &account.id);
        assert_eq!(merged.1, &shell.id);
        assert_eq!(merged.2.id, live.id);
        // No trailing summary frame for the folded shell.
        assert!(events.iter().all(|event| match event {
            HostSideEvent::ConversationChanged(summary) => summary.id != shell.id,
            _ => true,
        }));
        // The store: the shell is gone, the canonical row holds the union
        // (two seeded rows plus the landed one plus the minted notice).
        let store = service.store_ref();
        assert!(
            store
                .conversation_by_peer(&account.id, "direct", peer_number)
                .unwrap()
                .is_none()
        );
        let count: i64 = store
            .conn()
            .query_row(
                "SELECT COUNT(*) FROM messages WHERE conversation_id=?1",
                params![live.id],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(count, 4);
        let shell_leftovers: i64 = store
            .conn()
            .query_row(
                "SELECT COUNT(*) FROM messages WHERE conversation_id=?1",
                params![shell.id],
                |row| row.get(0),
            )
            .unwrap();
        assert_eq!(shell_leftovers, 0);
    }

    /// Contract 1.259 (§4.243), the sync seam: `apply_sync_contacts` runs
    /// the fold sweep after its passive write face — a number-keyed shell
    /// beside the record's ACI-keyed row folds, the shell's changed frame
    /// filters, the merged frame carries the fresh canonical summary, and
    /// the ladder's title upgrade lands on the surviving row.
    #[test]
    fn sync_contacts_folds_the_discovered_double_row_and_frames_the_merge() {
        let (_temp, mut service) = service();
        let account = service
            .sync_accounts_from_numbers(
                &[("+15555550100".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap()
            .remove(0);
        const PEER_ACI: &str = "33333333-3333-4333-8333-333333333333";
        let peer_number = "+15555550101";
        let receive = |source: Option<&str>,
                       source_uuid: Option<&str>,
                       text: &str,
                       peer_name: Option<&str>| {
            NormalizedReceive {
                required_protocol_version: None,
                timestamp: Some(1_000),
                content_kind: "dataMessage",
                direction: "incoming",
                account_present: true,
                account: Some("+15555550100".into()),
                source: source.map(str::to_string),
                source_uuid: source_uuid.map(str::to_string),
                peer_name: peer_name.map(str::to_string),
                group_id: None,
                text: Some(text.into()),
                text_bytes: Some(text.len() as u32),
                text_truncated: false,
                quote: None,
                attachments: Vec::new(),
                rich: None,
                sticker: None,
                expire_seconds: None,
                expire_start_at: None,
                control: None,
                server_guid: None,
                reporting_token: None,
                server_timestamp: None,
            }
        };
        service
            .ingest_receive(
                receive(Some(PEER_ACI), Some(PEER_ACI), "live hello", None),
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap();
        service
            .ingest_receive(
                receive(Some(peer_number), None, "shell hello", Some("+1555***101")),
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap();
        let shell = service
            .store_ref()
            .conversation_by_peer(&account.id, "direct", peer_number)
            .unwrap()
            .expect("the shell row exists pre-fold");
        let live = service
            .store_ref()
            .conversation_by_peer(&account.id, "direct", PEER_ACI)
            .unwrap()
            .expect("the ACI row exists pre-fold");

        let account_row = service
            .store_ref()
            .account_by_id(&account.id)
            .unwrap()
            .expect("the synced account row");
        let events = service
            .apply_sync_contacts(
                &account_row,
                &[crate::engine::SyncContactRecord {
                    aci: PEER_ACI.into(),
                    number: Some(peer_number.into()),
                    name: Some("Sync Peer".into()),
                }],
                false,
            )
            .unwrap();

        let merged = events
            .iter()
            .find_map(|event| match event {
                HostSideEvent::ConversationMerged {
                    from_conversation_id,
                    to_conversation,
                    ..
                } => Some((from_conversation_id, to_conversation)),
                _ => None,
            })
            .expect("the merged frame rides");
        assert_eq!(merged.0, &shell.id);
        assert_eq!(merged.1.id, live.id);
        // The A5 notice fires here: the sync's passive write face upgraded
        // the shell's masked title to the sync's real name BEFORE the fold
        // sweep read it, so the official titleIsUseful gate reads a useful
        // title at merge time — the official order (write face, then merge,
        // then the notice reads the obsolete row's title).
        let notice = events
            .iter()
            .find_map(|event| match event {
                HostSideEvent::MessageUpserted(record) if record.direction == "system" => {
                    Some(record)
                }
                _ => None,
            })
            .expect("the sync's title upgrade makes the shell title useful: the notice fires");
        let merge_face = notice
            .rich
            .as_ref()
            .and_then(|rich| rich.conversation_merge.as_ref())
            .expect("the notice carries the conversationMerge face");
        assert_eq!(
            merge_face.obsolete_conversation_title.as_deref(),
            Some("Sync Peer")
        );
        assert_eq!(
            merge_face.obsolete_conversation_number.as_deref(),
            Some(peer_number)
        );
        // The surviving row's own title is never copied (the official pick
        // list carries no title key); the display material self-heals
        // through the §4.229 read face — the summary's systemName probes the
        // contacts row by the identity set.
        let folded_summary = &merged.1;
        assert_eq!(folded_summary.system_name.as_deref(), Some("Sync Peer"));
        // No changed frame names the folded shell.
        assert!(events.iter().all(|event| match event {
            HostSideEvent::ConversationChanged(summary) => summary.id != shell.id,
            _ => true,
        }));
        let store = service.store_ref();
        assert!(
            store
                .conversation_by_peer(&account.id, "direct", peer_number)
                .unwrap()
                .is_none()
        );
        // The surviving row keeps its own title (nothing copied); the sync's
        // real name rides the §4.229 systemName face asserted above.
        let folded = store
            .conversation_summary(&account.id, &live.id)
            .unwrap()
            .unwrap();
        assert_eq!(folded.title, "333***33");
    }

    /// The engine's P14 metadata faces (contract 1.107, §4.88) ride the
    /// message end to end: the descriptor's caption/blurHash/integrity
    /// pair/flag booleans and the rich `expireTimerVersion`/preview date
    /// persist on the row and carry the same values on the emitted
    /// `message.upserted` record — the wire face the desktop consumes.
    #[test]
    fn ingest_receive_p14_metadata_rides_row_and_event() {
        let (_temp, mut service) = service();
        let (account, conversation) = linked_account_and_conversation(&mut service);
        let receive = NormalizedReceive {
            required_protocol_version: None,
            timestamp: Some(400),
            content_kind: "dataMessage",
            direction: "incoming",
            account_present: true,
            account: Some("+15555550100".into()),
            source: Some("+15555550101".into()),
            source_uuid: None,
            peer_name: None,
            group_id: None,
            text: Some("with media".into()),
            text_bytes: Some(10),
            text_truncated: false,
            quote: None,
            attachments: vec![NormalizedAttachment {
                id: "att-p14".into(),
                content_type: Some("image/png".into()),
                filename: Some("sunset.png".into()),
                size: Some(4096),
                width: Some(640),
                height: Some(480),
                is_voice_note: false,
                caption: Some("a sunset".into()),
                blur_hash: Some("LEHV6nWB2yk8pyo0adR*.7kCMdnj".into()),
                incremental_mac: Some("AQIDBA==".into()),
                chunk_size: Some(8192),
                is_borderless: true,
                is_gif: false,
                locator: None,
                waveform: None,
                duration: None,
            }],
            rich: Some(NormalizedRich {
                previews: vec![NormalizedPreview {
                    url: "https://example.com/a".into(),
                    title: None,
                    description: None,
                    date: Some(1_600_000_000_000),
                    image: None,
                }],
                expire_timer_version: Some(3),
                ..Default::default()
            }),
            sticker: None,
            expire_seconds: None,
            expire_start_at: None,
            control: None,
            server_guid: None,
            reporting_token: None,
            server_timestamp: None,
        };
        let events = service
            .ingest_receive(receive, crate::DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let upserted = events
            .iter()
            .find_map(|event| match event {
                HostSideEvent::MessageUpserted(record) => Some(record),
                _ => None,
            })
            .expect("one message.upserted event");
        let descriptor = &upserted.attachments[0];
        assert_eq!(descriptor.caption.as_deref(), Some("a sunset"));
        assert_eq!(
            descriptor.blur_hash.as_deref(),
            Some("LEHV6nWB2yk8pyo0adR*.7kCMdnj")
        );
        assert_eq!(descriptor.incremental_mac.as_deref(), Some("AQIDBA=="));
        assert_eq!(descriptor.chunk_size, Some(8192));
        assert!(descriptor.is_borderless);
        assert!(!descriptor.is_gif);
        let rich = upserted.rich.as_ref().expect("rich rides the event");
        assert_eq!(rich.expire_timer_version, Some(3));
        assert_eq!(rich.previews[0].date, Some(1_600_000_000_000));

        let row = service
            .list_messages(&account.id, &conversation.id, 10, None)
            .unwrap()
            .items
            .into_iter()
            .next()
            .unwrap();
        let stored = &row.attachments[0];
        assert_eq!(stored.caption.as_deref(), Some("a sunset"));
        assert_eq!(stored.chunk_size, Some(8192));
        assert!(stored.is_borderless);
        let stored_rich = row.rich.as_ref().expect("rich round-trips");
        assert_eq!(stored_rich.expire_timer_version, Some(3));
        assert_eq!(stored_rich.previews[0].date, Some(1_600_000_000_000));
    }

    /// Post-relink defense: the restored row arrives with no descriptors;
    /// the later live echo of the same message must repair them (synthetic id
    /// included, because the engine emits an empty id for a pointer without a
    /// client uuid). The repaired row must then pass the exact
    /// `attachments.download` descriptor lookup instead of answering the
    /// INVALID_REQUEST miss.
    #[test]
    fn duplicate_live_receive_repairs_restored_attachment_descriptors() {
        let (_temp, mut service) = media_service();
        let account = service
            .store_ref()
            .upsert_account_from_signal("+15555550100", None, crate::DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let conversation = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        let peer_sender = crate::ids::stable_hash_id(&[&account.id, "direct", "+15555550101"]);
        let mut restored =
            expire_record_fixture(&account.id, &conversation.id, "m-restored-attachment");
        restored.sender_id = peer_sender.clone();
        restored.sent_at = 700;
        service
            .store_ref()
            .insert_message(&restored, None, Some("body"), false)
            .unwrap();
        // The reported failure, reproduced deterministically: the restored
        // row resolves and the index is legal, but the descriptor cell is
        // empty, so the download guard answers the exact miss.
        let miss = service
            .prepare_attachment_download(&account.id, &conversation.id, "m-restored-attachment", 0)
            .unwrap_err()
            .into_api();
        assert_eq!(miss.code, "INVALID_REQUEST");
        assert_eq!(
            miss.message,
            "attachmentIndex does not name an attachment of this message"
        );

        let face = crate::store::HistoryAttachmentLocator {
            key: Some("q83vLNoechoM6CiZ+hr3P5ePE3YGAibLE4bAl1jv20Y=".into()),
            cdn_key: Some("live-restored".into()),
            cdn_number: Some(0),
            upload_timestamp: Some(1_700_000_000_000),
            digest: Some("ZGl-nonsense".into()),
            plaintext_hash: None,
        };
        let receive = NormalizedReceive {
            required_protocol_version: None,
            timestamp: Some(700),
            content_kind: "dataMessage",
            direction: "incoming",
            account_present: true,
            account: Some("+15555550100".into()),
            source: Some("+15555550101".into()),
            source_uuid: None,
            peer_name: None,
            group_id: None,
            text: Some("body".into()),
            text_bytes: Some(4),
            text_truncated: false,
            quote: None,
            attachments: vec![NormalizedAttachment {
                id: String::new(),
                content_type: Some("image/png".into()),
                filename: Some("restored.png".into()),
                size: Some(12),
                width: None,
                height: None,
                is_voice_note: false,
                caption: None,
                blur_hash: None,
                incremental_mac: None,
                chunk_size: None,
                is_borderless: false,
                is_gif: false,
                locator: Some(face.clone()),
                waveform: None,
                duration: None,
            }],
            rich: None,
            sticker: None,
            expire_seconds: None,
            expire_start_at: None,
            control: None,
            server_guid: None,
            reporting_token: None,
            server_timestamp: None,
        };
        let events = service
            .ingest_receive(receive, crate::DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        assert!(events.is_empty(), "the duplicate stays event-silent");

        let row = service
            .store_ref()
            .message_by_id(&account.id, &conversation.id, "m-restored-attachment")
            .unwrap()
            .expect("restored row");
        assert_eq!(row.attachments.len(), 1, "descriptor repaired");
        assert_eq!(
            row.attachments[0].id,
            crate::ids::stable_hash_id(&["live-attachment", "m-restored-attachment", "0"])
        );
        let prepared = service
            .prepare_attachment_download(&account.id, &conversation.id, "m-restored-attachment", 0)
            .expect("the descriptor resolves instead of the miss");
        let PreparedHistoryDownload::Ready {
            locator,
            descriptor_size,
            ..
        } = prepared
        else {
            panic!("an un-downloaded pointer answers the ready arm");
        };
        assert_eq!(descriptor_size, Some(12));
        assert_eq!(locator, face);
    }

    /// §4.178 live face: the receive arm resolves the just-landed row's
    /// quote snapshot against the store BEFORE the upsert event mints, so
    /// the desktop's jump and warning strip see the same answer a later
    /// `messages.list` read would give. An unresolvable snapshot stays
    /// honestly absent on the event face too — the official
    /// `referencedMessageNotFound` posture the desktop renders as the
    /// quote warning strip.
    #[test]
    fn live_receive_resolves_quote_snapshot_before_the_upsert_event() {
        let (_temp, mut service) = service();
        let (account, conversation) = linked_account_and_conversation(&mut service);
        // The peer's original at t=300, stored with the peer's envelope hash.
        let peer_sender_id = crate::ids::stable_hash_id(&[&account.id, "direct", "+15555550101"]);
        let mut original = expire_record_fixture(&account.id, &conversation.id, "m-original");
        original.sender_id = peer_sender_id;
        original.sent_at = 300;
        service
            .store_ref()
            .insert_message(&original, None, None, false)
            .unwrap();

        let mut receive = NormalizedReceive {
            required_protocol_version: None,
            timestamp: Some(500),
            content_kind: "dataMessage",
            direction: "incoming",
            account_present: true,
            account: Some("+15555550100".into()),
            source: Some("+15555550101".into()),
            source_uuid: None,
            peer_name: None,
            group_id: None,
            text: Some("quoting you".into()),
            text_bytes: Some(11),
            text_truncated: false,
            quote: Some(NormalizedQuote {
                id: 300,
                author: "+15555550101".into(),
                text: "the original".into(),
                attachments: Vec::new(),
            }),
            attachments: Vec::new(),
            rich: None,
            sticker: None,
            expire_seconds: None,
            expire_start_at: None,
            control: None,
            server_guid: None,
            reporting_token: None,
            server_timestamp: None,
        };
        let events = service
            .ingest_receive(receive.clone(), crate::DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let upserted = events
            .iter()
            .find_map(|event| match event {
                HostSideEvent::MessageUpserted(record) => Some(record),
                _ => None,
            })
            .expect("one message.upserted event");
        assert_eq!(
            upserted.quote_message_id.as_deref(),
            Some("m-original"),
            "the live event carries the resolved deep link"
        );

        // A quote naming a timestamp nobody holds stays unresolved on the
        // event face — the honest absent face, never a guessed pointer.
        receive.timestamp = Some(600);
        receive.quote = Some(NormalizedQuote {
            id: 9_999,
            author: "+15555550101".into(),
            text: "into the void".into(),
            attachments: Vec::new(),
        });
        let events = service
            .ingest_receive(receive, crate::DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let upserted = events
            .iter()
            .find_map(|event| match event {
                HostSideEvent::MessageUpserted(record) => Some(record),
                _ => None,
            })
            .expect("one message.upserted event");
        assert_eq!(
            upserted.quote_message_id, None,
            "an unresolvable snapshot stays honestly absent"
        );
    }

    /// The sent mirror's transcript faces (contract 1.107, §4.88) persist on
    /// the outgoing mirror row: the recipient-update bit, the sealed-sender
    /// statuses and the story distribution state ride `syncMessage.sentMessage`
    /// → rich → row verbatim, with an event-less inbound row unaffected.
    #[test]
    fn sent_mirror_transcript_faces_persist_on_the_mirror_row() {
        let (_temp, mut service) = service();
        let (account, conversation) = linked_account_and_conversation(&mut service);
        let receive = NormalizedReceive {
            required_protocol_version: None,
            timestamp: Some(500),
            content_kind: "syncMessage",
            direction: "outgoing",
            account_present: true,
            account: Some("+15555550100".into()),
            source: Some("+15555550101".into()),
            source_uuid: None,
            peer_name: None,
            group_id: None,
            text: Some("from the phone".into()),
            text_bytes: Some(14),
            text_truncated: false,
            quote: None,
            attachments: Vec::new(),
            rich: Some(NormalizedRich {
                is_recipient_update: true,
                unidentified_status: vec![NormalizedUnidentifiedStatus {
                    destination_uuid: Some("PNI:00000000-0000-0000-0000-000000000001".into()),
                    unidentified: Some(true),
                    destination_pni_identity_key: None,
                }],
                story_message_recipients: vec![NormalizedStoryRecipient {
                    destination_uuid: Some("11111111-2222-4333-8444-555555555555".into()),
                    distribution_list_ids: vec!["00000000-0000-0000-0000-000000000000".into()],
                    is_allowed_to_reply: Some(false),
                }],
                ..Default::default()
            }),
            sticker: None,
            expire_seconds: None,
            expire_start_at: None,
            control: None,
            server_guid: None,
            reporting_token: None,
            server_timestamp: None,
        };
        let events = service
            .ingest_receive(receive, crate::DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let upserted = events
            .iter()
            .find_map(|event| match event {
                HostSideEvent::MessageUpserted(record) => Some(record),
                _ => None,
            })
            .expect("one mirror row event");
        let rich = upserted.rich.as_ref().expect("transcript rich");
        assert!(rich.is_recipient_update);
        assert_eq!(rich.unidentified_status.len(), 1);
        assert_eq!(
            rich.unidentified_status[0].destination_uuid.as_deref(),
            Some("PNI:00000000-0000-0000-0000-000000000001")
        );
        assert_eq!(rich.story_message_recipients.len(), 1);
        assert_eq!(
            rich.story_message_recipients[0].distribution_list_ids,
            ["00000000-0000-0000-0000-000000000000"]
        );

        let row = service
            .list_messages(&account.id, &conversation.id, 10, None)
            .unwrap()
            .items
            .into_iter()
            .next()
            .unwrap();
        let stored_rich = row.rich.as_ref().expect("transcript rich round-trips");
        assert!(stored_rich.is_recipient_update);
        assert_eq!(stored_rich.unidentified_status[0].unidentified, Some(true));
        assert_eq!(
            stored_rich.story_message_recipients[0].is_allowed_to_reply,
            Some(false)
        );
    }

    // ---- Media ingest (ADR 0004) -------------------------------------

    /// A service with the media backing armed over an engine-shaped data
    /// directory. The flat `<data>/attachments/` directory keeps the legacy
    /// read path exercised; account-scoped tests use [`account_media_dir`].
    fn media_service() -> (TempDir, ConnectorService) {
        let temp = TempDir::new().unwrap();
        let store = Store::open(temp.path(), Some(StoreKey::from_bytes([0x5A; 32]))).unwrap();
        let data_dir = temp.path().join("signal-data");
        std::fs::create_dir_all(data_dir.join("attachments")).unwrap();
        let handles = Arc::new(MediaHandleTable::new());
        (
            temp,
            ConnectorService::with_media(
                Arc::new(store),
                Some(MediaIngest::new(data_dir, handles)),
            ),
        )
    }

    /// `[KT 适配]` (audit §9.10): the per-account write bucket the governor
    /// must use, created by the first write.
    fn account_media_dir(temp: &TempDir, account_id: &str) -> PathBuf {
        temp.path()
            .join("signal-data")
            .join("media")
            .join(account_id)
            .join("attachments")
    }

    /// Addressing rows for one account, mirroring the media-open test setup:
    /// account → direct conversation → one completed outgoing message.
    fn addressed_message(
        service: &ConnectorService,
        number: &str,
        peer: &str,
        request_id: &str,
    ) -> (String, String, String) {
        let account = service
            .store_ref()
            .upsert_account_from_signal(number, None, crate::DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let direct = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", peer, "Peer")
            .unwrap();
        let message_id = match service
            .prepare_send_text(
                &account.id,
                &direct.id,
                "has attachment",
                request_id,
                None,
                None,
                None,
                None,
                None,
                None,
            )
            .unwrap()
        {
            PreparedSend::Dispatch { pending_id, .. } => pending_id,
            PreparedSend::Existing(_) => panic!("new client request must dispatch"),
        };
        service
            .complete_send_success(&message_id, &account.id, &direct.id, 800, None)
            .unwrap();
        (account.id, direct.id, message_id)
    }

    /// §4.183 (contract revision 1.183): the send arm stashes the outgoing
    /// plaintext under the descriptor's own id — the official
    /// outgoing-attachment local-retention semantics — and the download arm
    /// serves the stash before any pointer-face check: an outgoing row has
    /// no locator at all, and after settlement its download answers the
    /// measured size instead of the old no-pointer INVALID_REQUEST.
    #[test]
    fn outbound_send_stashes_bytes_and_download_serves_them_without_a_pointer() {
        let (temp, service) = media_service();
        let account = service
            .store_ref()
            .upsert_account_from_signal("+15555550100", None, crate::DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let direct = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        let bytes = b"outbound stash bytes".to_vec();
        let prepared = service
            .prepare_send_attachment(
                &account.id,
                &AttachmentSendTarget::Conversation(&direct.id),
                "req-stash-1",
                &base64_encode(&bytes),
                bytes.len() as u64,
                Some("notes.txt"),
                Some("text/plain"),
                Some("caption"),
                None,
                false,
                false,
                None,
                false,
            )
            .unwrap();
        let PreparedSend::Dispatch { pending_id, .. } = prepared else {
            panic!("new client request must dispatch");
        };
        let row = service
            .store_ref()
            .message_by_client_request(&account.id, "req-stash-1")
            .unwrap()
            .unwrap();
        let stashed = account_media_dir(&temp, &account.id).join(&row.attachments[0].id);
        assert_eq!(
            std::fs::read(&stashed).unwrap(),
            bytes,
            "the send arm stashes the exact plaintext under the descriptor id"
        );

        service
            .complete_send_success(&pending_id, &account.id, &direct.id, 900, None)
            .unwrap();
        let PreparedHistoryDownload::AlreadyPresent { size_bytes } = service
            .prepare_attachment_download(&account.id, &direct.id, &pending_id, 0)
            .unwrap()
        else {
            panic!("a stashed outgoing row answers the local-hit arm, never a network chain");
        };
        assert_eq!(size_bytes, bytes.len() as u64);
    }

    /// `[KT 适配]` migration face: a pre-isolation stash lives in the flat
    /// `<data>/attachments/` directory. The download arm still answers the
    /// local-hit size instead of failing the no-pointer arm, so an outgoing
    /// row written before the per-account layout keeps its bytes face.
    #[test]
    fn outbound_download_still_serves_a_legacy_flat_stash() {
        let (temp, service) = media_service();
        let account = service
            .store_ref()
            .upsert_account_from_signal("+15555550100", None, crate::DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let direct = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        let bytes = b"legacy stash bytes".to_vec();
        let prepared = service
            .prepare_send_attachment(
                &account.id,
                &AttachmentSendTarget::Conversation(&direct.id),
                "req-stash-legacy",
                &base64_encode(&bytes),
                bytes.len() as u64,
                Some("notes.txt"),
                Some("text/plain"),
                None,
                None,
                false,
                false,
                None,
                false,
            )
            .unwrap();
        let PreparedSend::Dispatch { pending_id, .. } = prepared else {
            panic!("new client request must dispatch");
        };
        service
            .complete_send_success(&pending_id, &account.id, &direct.id, 900, None)
            .unwrap();
        let row = service
            .store_ref()
            .message_by_client_request(&account.id, "req-stash-legacy")
            .unwrap()
            .unwrap();
        // Simulate the pre-isolation layout: move the stash into the flat
        // shared directory the old connector wrote.
        let stashed = account_media_dir(&temp, &account.id).join(&row.attachments[0].id);
        let legacy = temp
            .path()
            .join("signal-data/attachments")
            .join(&row.attachments[0].id);
        std::fs::rename(&stashed, &legacy).unwrap();

        let PreparedHistoryDownload::AlreadyPresent { size_bytes } = service
            .prepare_attachment_download(&account.id, &direct.id, &pending_id, 0)
            .unwrap()
        else {
            panic!("a legacy local stash must still answer the local-hit arm");
        };
        assert_eq!(size_bytes, bytes.len() as u64);
        assert!(legacy.is_file());
    }

    /// §4.183: a stash the governor evicted (the 7-day TTL arm is used
    /// here, backdating the file's mtime) is gone for real — the download
    /// arm falls through to the pointer-face check and answers the same
    /// honest no-pointer INVALID_REQUEST an upload-only outgoing row always
    /// did. Eviction never invents bytes, and the miss never invents a
    /// pointer.
    #[test]
    fn outbound_download_after_stash_eviction_keeps_the_honest_no_pointer_face() {
        let (temp, service) = media_service();
        let account = service
            .store_ref()
            .upsert_account_from_signal("+15555550100", None, crate::DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let direct = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        let bytes = b"evict me".to_vec();
        let prepared = service
            .prepare_send_attachment(
                &account.id,
                &AttachmentSendTarget::Conversation(&direct.id),
                "req-stash-2",
                &base64_encode(&bytes),
                bytes.len() as u64,
                Some("notes.txt"),
                Some("text/plain"),
                None,
                None,
                false,
                false,
                None,
                false,
            )
            .unwrap();
        let PreparedSend::Dispatch { pending_id, .. } = prepared else {
            panic!("new client request must dispatch");
        };
        service
            .complete_send_success(&pending_id, &account.id, &direct.id, 900, None)
            .unwrap();
        let row = service
            .store_ref()
            .message_by_client_request(&account.id, "req-stash-2")
            .unwrap()
            .unwrap();
        let stashed = account_media_dir(&temp, &account.id).join(&row.attachments[0].id);
        assert!(stashed.is_file());
        // Backdate past the MEDIA_TTL and let one governor pass evict the
        // stash — the same retention machine inbound media answers to.
        let stale = std::time::SystemTime::now() - std::time::Duration::from_secs(8 * 24 * 60 * 60);
        std::fs::File::options()
            .write(true)
            .open(&stashed)
            .unwrap()
            .set_modified(stale)
            .unwrap();
        let stats = service.media.as_ref().unwrap().governor().run_pass();
        assert_eq!(stats.deleted, 1);
        assert!(!stashed.exists());

        let error = service
            .prepare_attachment_download(&account.id, &direct.id, &pending_id, 0)
            .unwrap_err()
            .into_api();
        assert_eq!(error.code, "INVALID_REQUEST");
        assert!(!error.retryable);
    }

    /// Batch U S8 (ledger §29.63): the archive-import row keeps the full
    /// attachment pointer — `attachments.download` answers the Ready arm
    /// with the locator intact for an imported outgoing voice row, the
    /// exact face the batch-T evidence saw as the no-pointer INVALID_REQUEST
    /// (locator ladder live∪history empty). The pointer source is the
    /// engine's v2 NDJSON (compat §5 附件指针投影面): the importer lands it
    /// index-aligned in the internal column and the download ladder resolves
    /// it through the history arm without any live-echo repair.
    #[test]
    fn imported_outgoing_row_downloads_through_its_preserved_pointer() {
        let temp = TempDir::new().unwrap();
        let store =
            Arc::new(Store::open(temp.path(), Some(StoreKey::from_bytes([0x5A; 32]))).unwrap());
        let data_dir = temp.path().join("signal-data");
        std::fs::create_dir_all(data_dir.join("attachments")).unwrap();
        let service = ConnectorService::with_media(
            Arc::clone(&store),
            Some(MediaIngest::new(
                data_dir,
                Arc::new(MediaHandleTable::new()),
            )),
        );
        let account = store
            .upsert_account_from_signal("+15555550100", None, crate::DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        // Engine-shaped v2 archive: one direct chat, one outgoing voice row
        // carrying the complete transit pointer (the batch-T evidence face).
        let key_b64 = "q83vLNoechoM6CiZ+hr3P5ePE3YGAibLE4bAl1jv20Y=";
        let hash_hex = "a".repeat(64);
        let archive = temp.path().join("history-import.ndjson");
        let lines = [
            serde_json::json!({
                "type": "recipient", "id": 1, "kind": "contact", "name": "Peer",
                "aci": "6e08f0b6-1c2d-4e5f-8a9b-0c1d2e3f4a5b", "e164": "+15550000001"
            })
            .to_string(),
            serde_json::json!({"type": "chat", "id": 10, "recipientId": 1}).to_string(),
            serde_json::json!({
                "type": "message", "chatId": 10, "authorId": 1, "dateSent": 700,
                "direction": "outgoing", "text": "voice note",
                "attachments": [{
                    "contentType": "audio/aac", "fileName": "voice.aac", "flag": 1,
                    "size": 267_000u64, "width": 0u64, "height": 0u64,
                    "locator": {
                        "key": key_b64, "cdnKey": "t1a2b3c", "cdnNumber": 0,
                        "uploadTimestamp": 1_700_000_000_000u64,
                        "plaintextHash": hash_hex
                    }
                }]
            })
            .to_string(),
        ];
        std::fs::write(&archive, format!("{}\n", lines.join("\n"))).unwrap();

        let counters = crate::history_import::run_import(
            &store,
            &account.id,
            "+15555550100",
            &archive,
            &std::sync::atomic::AtomicBool::new(false),
        )
        .unwrap();
        assert_eq!(counters.imported, 1, "the outgoing voice row imports");

        let conversation = crate::ids::stable_hash_id(&[&account.id, "direct", "+15550000001"]);
        let row = service
            .list_messages(&account.id, &conversation, 10, None)
            .unwrap()
            .items
            .into_iter()
            .next()
            .expect("the imported row lists");

        let prepared = service
            .prepare_attachment_download(&account.id, &conversation, &row.id, 0)
            .expect("the preserved pointer answers the ready arm, not the miss");
        let PreparedHistoryDownload::Ready {
            locator,
            descriptor_size,
            ..
        } = prepared
        else {
            panic!("an imported pointer-complete row is downloadable");
        };
        assert_eq!(descriptor_size, Some(267_000));
        // Contract 1.254: the media face rides the wire descriptor too —
        // Some(0) is a stated archive value, never dropped into absence.
        assert_eq!(row.attachments.len(), 1);
        assert_eq!(row.attachments[0].width, Some(0));
        assert_eq!(row.attachments[0].height, Some(0));
        assert_eq!(locator.key.as_deref(), Some(key_b64));
        assert_eq!(locator.cdn_key.as_deref(), Some("t1a2b3c"));
        assert_eq!(locator.cdn_number, Some(0), "CDN0 stays a legal face");
        assert_eq!(locator.upload_timestamp, Some(1_700_000_000_000));
        assert_eq!(locator.plaintext_hash.as_deref(), Some(hash_hex.as_str()));
        assert!(locator.digest.is_none(), "the oneof integrity stays one-of");
    }

    /// §4.183: the stash is best-effort — when the attachments directory
    /// cannot be written (here a regular file occupies the
    /// `<data>/attachments` name, so the fallback create fails), the send
    /// still dispatches unchanged and leaves the row behind. The failure
    /// class is logged, never the id or path.
    #[test]
    fn outbound_stash_failure_does_not_block_the_send() {
        let (temp, service) = media_service();
        let account = service
            .store_ref()
            .upsert_account_from_signal("+15555550100", None, crate::DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let direct = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        // Occupy the account's media write path: `<data>/media/<account-id>`
        // is a regular file, so the per-account create_dir_all fails and the
        // stash reports its class.
        let media_root = temp.path().join("signal-data/media");
        std::fs::create_dir_all(&media_root).unwrap();
        std::fs::write(media_root.join(&account.id), b"occupied").unwrap();

        let bytes = b"unsaved bytes".to_vec();
        let prepared = service
            .prepare_send_attachment(
                &account.id,
                &AttachmentSendTarget::Conversation(&direct.id),
                "req-stash-3",
                &base64_encode(&bytes),
                bytes.len() as u64,
                Some("notes.txt"),
                Some("text/plain"),
                None,
                None,
                false,
                false,
                None,
                false,
            )
            .unwrap();
        assert!(
            matches!(prepared, PreparedSend::Dispatch { .. }),
            "a stash failure never changes the send outcome"
        );
        assert!(
            service
                .store_ref()
                .message_by_client_request(&account.id, "req-stash-3")
                .unwrap()
                .is_some(),
            "the pending row exists even though the stash failed"
        );
    }

    /// §4.183: multi-attachment sends stash every entry under its own
    /// descriptor id — one file per entry, exact bytes each, index-aligned
    /// with the row's descriptor order.
    #[test]
    fn outbound_multi_send_stashes_every_entry_under_its_own_descriptor_id() {
        let (temp, service) = media_service();
        let account = service
            .store_ref()
            .upsert_account_from_signal("+15555550100", None, crate::DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let direct = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        let first = b"first entry".to_vec();
        let second = b"second entry!".to_vec();
        let entries = vec![
            MessagesSendAttachmentEntry {
                data_base64: base64_encode(&first),
                size_bytes: first.len() as u64,
                filename: Some("a.txt".into()),
                content_type: Some("text/plain".into()),
                blur_hash: None,
                gif: false,
            },
            MessagesSendAttachmentEntry {
                data_base64: base64_encode(&second),
                size_bytes: second.len() as u64,
                filename: Some("b.txt".into()),
                content_type: Some("text/plain".into()),
                blur_hash: None,
                gif: false,
            },
        ];
        let prepared = service
            .prepare_send_attachment_multi(
                &account.id,
                &AttachmentSendTarget::Conversation(&direct.id),
                "req-stash-multi",
                &entries,
                None,
                None,
            )
            .unwrap();
        let PreparedSend::Dispatch { pending_id, .. } = prepared else {
            panic!("new client request must dispatch");
        };
        service
            .complete_send_success(&pending_id, &account.id, &direct.id, 900, None)
            .unwrap();
        let row = service
            .store_ref()
            .message_by_client_request(&account.id, "req-stash-multi")
            .unwrap()
            .unwrap();
        assert_eq!(row.attachments.len(), 2);
        for (descriptor, want) in row.attachments.iter().zip([first, second]) {
            let stashed = account_media_dir(&temp, &account.id).join(&descriptor.id);
            assert_eq!(
                std::fs::read(&stashed).unwrap(),
                want,
                "every multi entry stashes its own bytes"
            );
            let PreparedHistoryDownload::AlreadyPresent { size_bytes } = service
                .prepare_attachment_download(
                    &account.id,
                    &direct.id,
                    &pending_id,
                    row.attachments
                        .iter()
                        .position(|d| d.id == descriptor.id)
                        .unwrap(),
                )
                .unwrap()
            else {
                panic!("each stashed entry answers the local-hit arm");
            };
            assert_eq!(size_bytes, want.len() as u64);
        }
    }

    /// §4.183: view-once sends stash like any other send (the sender's own
    /// bubble renders across restarts), and the §4.37 burn erases the stash
    /// with the same id discipline as every other media channel.
    #[test]
    fn outbound_view_once_stash_is_burned_with_the_message() {
        let (temp, service) = media_service();
        let account = service
            .store_ref()
            .upsert_account_from_signal("+15555550100", None, crate::DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let direct = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        let bytes = b"view once bytes".to_vec();
        let prepared = service
            .prepare_send_attachment(
                &account.id,
                &AttachmentSendTarget::Conversation(&direct.id),
                "req-stash-vo",
                &base64_encode(&bytes),
                bytes.len() as u64,
                None,
                Some("image/png"),
                None,
                None,
                false,
                true,
                None,
                false,
            )
            .unwrap();
        let PreparedSend::Dispatch { pending_id, .. } = prepared else {
            panic!("new client request must dispatch");
        };
        service
            .complete_send_success(&pending_id, &account.id, &direct.id, 900, None)
            .unwrap();
        let row = service
            .store_ref()
            .message_by_client_request(&account.id, "req-stash-vo")
            .unwrap()
            .unwrap();
        let stashed = account_media_dir(&temp, &account.id).join(&row.attachments[0].id);
        assert_eq!(std::fs::read(&stashed).unwrap(), bytes);

        // The §4.37 burn face erases the stash exactly like the other media
        // channels of the burned message.
        service
            .prepare_mark_view_once_opened(&MessagesMarkViewOnceOpenedParams {
                account_id: account.id.clone(),
                conversation_id: direct.id.clone(),
                message_id: pending_id,
            })
            .unwrap();
        assert!(!stashed.exists(), "the burn erases the stashed bytes too");
    }

    /// Without the launcher opt-in (`ConnectorService::new`), all three
    /// media methods answer the shared capability gate before any other
    /// check — the pre-PoC contract (ADR 0004 acceptance gate 5).
    #[test]
    fn media_methods_are_capability_gated_without_the_opt_in() {
        let (_temp, service) = service();
        for error in [
            service
                .open_media_handle("a", "c", "m", "att-1")
                .unwrap_err(),
            service.read_media_chunk("handle", 0).unwrap_err(),
            service.close_media_handle("handle").unwrap_err(),
        ] {
            let api = error.into_api();
            assert_eq!(api.code, "CAPABILITY_UNAVAILABLE");
            assert!(!api.retryable);
        }
    }

    /// Security gate (ADR 0004 acceptance gate 3): traversal-shaped ids —
    /// `../x`, absolute paths, backslashes, and the sanitize survivors
    /// `.` / `..` — answer INVALID_REQUEST before the filesystem is touched.
    /// The decoy file makes the check real: a naive path join would resolve
    /// it (and answer a handle or UPSTREAM_ERROR), never INVALID_REQUEST.
    #[test]
    fn media_open_rejects_traversal_ids_before_touching_the_filesystem() {
        let (_temp, service) = media_service();
        let (account_id, conversation_id, message_id) =
            addressed_message(&service, "+15555550100", "+15555550101", "req-media-trav");
        // Exactly where a naive `attachments/` join of "../escape.dat" and
        // "../../escape.dat" would land.
        std::fs::write(
            _temp.path().join("signal-data").join("escape.dat"),
            b"escaped",
        )
        .unwrap();

        for attachment_id in [
            "../escape.dat",
            "..",
            ".",
            "/etc/passwd",
            "a\\b.dat",
            "C:\\temp\\att.dat",
            "sub/../../escape.dat",
        ] {
            let error = service
                .open_media_handle(&account_id, &conversation_id, &message_id, attachment_id)
                .unwrap_err()
                .into_api();
            assert_eq!(error.code, "INVALID_REQUEST", "{attachment_id}");
            assert!(!error.retryable, "{attachment_id}");
        }
    }

    /// The happy path end to end: a downloaded file resolves, `open` reports
    /// the local size and the chunk bound, the read loop delivers the exact
    /// bytes through sequential offsets, and `closeHandle` is idempotent.
    #[test]
    fn media_open_streams_a_downloaded_file_through_sequential_chunks() {
        let (_temp, service) = media_service();
        let (account_id, conversation_id, message_id) =
            addressed_message(&service, "+15555550100", "+15555550101", "req-media-open");
        let body: Vec<u8> = (0..8192_u32).map(|i| (i % 251) as u8).collect();
        let attachment_dir = account_media_dir(&_temp, &account_id);
        std::fs::create_dir_all(&attachment_dir).unwrap();
        std::fs::write(attachment_dir.join("a1b2c3.dat"), &body).unwrap();

        let view = service
            .open_media_handle(&account_id, &conversation_id, &message_id, "a1b2c3.dat")
            .unwrap();
        assert_eq!(view.size_bytes, body.len() as u64);
        assert_eq!(view.chunk_bytes, 262_144);

        let mut assembled: Vec<u8> = Vec::with_capacity(body.len());
        let mut offset = 0_u64;
        let mut chunks = 0;
        loop {
            let chunk = service
                .read_media_chunk(&view.media_handle, offset)
                .unwrap();
            let mut decoded = Vec::with_capacity(chunk.size_bytes as usize);
            base64_decode_to_vec(&chunk.data_base64, &mut decoded)
                .expect("chunk base64 must be canonical");
            assert_eq!(decoded.len() as u64, chunk.size_bytes);
            assembled.extend_from_slice(&decoded);
            offset += chunk.size_bytes;
            chunks += 1;
            if chunk.eof {
                break;
            }
        }
        assert_eq!(assembled, body);
        assert_eq!(chunks, 1, "8 KiB fits one chunk; eof must be immediate");

        assert!(
            service
                .close_media_handle(&view.media_handle)
                .unwrap()
                .released
        );
        // Idempotent close, and a closed handle is unreadable.
        assert!(
            !service
                .close_media_handle(&view.media_handle)
                .unwrap()
                .released
        );
        let error = service
            .read_media_chunk(&view.media_handle, offset)
            .unwrap_err()
            .into_api();
        assert_eq!(error.code, "INVALID_REQUEST");
    }

    /// A missing file answers UPSTREAM_ERROR: not-downloaded and
    /// governor-deleted are indistinguishable (ADR 0004).
    #[test]
    fn media_open_answers_upstream_error_when_the_file_is_absent() {
        let (_temp, service) = media_service();
        let (account_id, conversation_id, message_id) = addressed_message(
            &service,
            "+15555550100",
            "+15555550101",
            "req-media-missing",
        );
        let error = service
            .open_media_handle(
                &account_id,
                &conversation_id,
                &message_id,
                "never-downloaded.dat",
            )
            .unwrap_err()
            .into_api();
        assert_eq!(error.code, "UPSTREAM_ERROR");
        assert!(error.retryable);
    }

    /// Non-sequential offsets fail closed at the service boundary with the
    /// shared INVALID_REQUEST answer.
    #[test]
    fn media_read_chunk_rejects_non_sequential_offsets() {
        let (_temp, service) = media_service();
        let (account_id, conversation_id, message_id) =
            addressed_message(&service, "+15555550100", "+15555550101", "req-media-seq");
        let attachment_dir = account_media_dir(&_temp, &account_id);
        std::fs::create_dir_all(&attachment_dir).unwrap();
        std::fs::write(attachment_dir.join("seq.dat"), [0_u8; 4096]).unwrap();
        let view = service
            .open_media_handle(&account_id, &conversation_id, &message_id, "seq.dat")
            .unwrap();

        let error = service
            .read_media_chunk(&view.media_handle, 1)
            .unwrap_err()
            .into_api();
        assert_eq!(error.code, "INVALID_REQUEST");
        // The first read is still at offset 0 after the refusal.
        service
            .read_media_chunk(&view.media_handle, 0)
            .expect("a refused offset must not advance the stream");
    }

    /// Releasing an account's handles (the deleteLocalData hook) must not
    /// touch another account's live streams.
    #[test]
    fn media_handles_release_per_account_without_cross_account_effects() {
        let (_temp, service) = media_service();
        let (account_a, conversation_a, message_a) =
            addressed_message(&service, "+15555550100", "+15555550191", "req-media-a");
        let (account_b, conversation_b, message_b) =
            addressed_message(&service, "+15555550101", "+15555550192", "req-media-b");
        let media_a = account_media_dir(&_temp, &account_a);
        let media_b = account_media_dir(&_temp, &account_b);
        std::fs::create_dir_all(&media_a).unwrap();
        std::fs::create_dir_all(&media_b).unwrap();
        std::fs::write(media_a.join("a.dat"), [1_u8; 64]).unwrap();
        let b_file = media_b.join("b.dat");
        std::fs::write(&b_file, [2_u8; 64]).unwrap();
        let handle_a = service
            .open_media_handle(&account_a, &conversation_a, &message_a, "a.dat")
            .unwrap()
            .media_handle;
        let handle_b = service
            .open_media_handle(&account_b, &conversation_b, &message_b, "b.dat")
            .unwrap()
            .media_handle;

        service.clear_media_for_account(&account_a);

        assert_eq!(
            service
                .read_media_chunk(&handle_a, 0)
                .unwrap_err()
                .into_api()
                .code,
            "INVALID_REQUEST"
        );
        // The other account's stream is untouched: single-origin by account.
        let chunk_b = service.read_media_chunk(&handle_b, 0).unwrap();
        assert_eq!(chunk_b.size_bytes, 64);
        assert!(chunk_b.eof);
        // Audit §9.10: the deleteLocalData hook also removes the deleted
        // account's media subtree and nothing else.
        assert!(!media_a.exists());
        assert!(b_file.exists());
    }

    /// Audit §9.10: media access is account-scoped end to end. B's file is
    /// on disk under B's bucket, but A's row addressing must not resolve it.
    #[test]
    fn media_open_never_resolves_another_accounts_file() {
        let (_temp, service) = media_service();
        let (account_a, conversation_a, message_a) = addressed_message(
            &service,
            "+15555550100",
            "+15555550191",
            "req-media-scope-a",
        );
        let (account_b, _conversation_b, _message_b) = addressed_message(
            &service,
            "+15555550101",
            "+15555550192",
            "req-media-scope-b",
        );
        let media_b = account_media_dir(&_temp, &account_b);
        std::fs::create_dir_all(&media_b).unwrap();
        std::fs::write(media_b.join("shared-name.dat"), b"b's bytes").unwrap();

        let error = service
            .open_media_handle(&account_a, &conversation_a, &message_a, "shared-name.dat")
            .unwrap_err()
            .into_api();
        assert_eq!(error.code, "UPSTREAM_ERROR");
        assert!(error.retryable);
    }

    /// Audit §9.10: a view-once burn erases only the addressed account's
    /// copy; another account's identical attachment id keeps its bytes.
    #[test]
    fn view_once_burn_never_deletes_another_accounts_same_id_file() {
        let (temp, service) = media_service();
        let account = service
            .store_ref()
            .upsert_account_from_signal("+15555550100", None, crate::DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let direct = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        let other = service
            .store_ref()
            .upsert_account_from_signal("+15555550101", None, crate::DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let bytes = b"view once bytes".to_vec();
        let prepared = service
            .prepare_send_attachment(
                &account.id,
                &AttachmentSendTarget::Conversation(&direct.id),
                "req-stash-vo-scope",
                &base64_encode(&bytes),
                bytes.len() as u64,
                None,
                Some("image/png"),
                None,
                None,
                false,
                true,
                None,
                false,
            )
            .unwrap();
        let PreparedSend::Dispatch { pending_id, .. } = prepared else {
            panic!("new client request must dispatch");
        };
        service
            .complete_send_success(&pending_id, &account.id, &direct.id, 900, None)
            .unwrap();
        let row = service
            .store_ref()
            .message_by_client_request(&account.id, "req-stash-vo-scope")
            .unwrap()
            .unwrap();
        let own = account_media_dir(&temp, &account.id).join(&row.attachments[0].id);
        assert!(own.is_file());
        // The same file name under a different account must survive the burn.
        let foreign_dir = account_media_dir(&temp, &other.id);
        std::fs::create_dir_all(&foreign_dir).unwrap();
        let foreign = foreign_dir.join(&row.attachments[0].id);
        std::fs::write(&foreign, b"not mine").unwrap();

        service
            .prepare_mark_view_once_opened(&MessagesMarkViewOnceOpenedParams {
                account_id: account.id.clone(),
                conversation_id: direct.id.clone(),
                message_id: pending_id,
            })
            .unwrap();

        assert!(!own.exists());
        assert!(foreign.is_file());
        assert_eq!(std::fs::read(&foreign).unwrap(), b"not mine");
    }

    /// The encoder emits the exact canonical form the upstream
    /// java.util.Base64 produces (RFC 4648 vectors), and every encoding
    /// round-trips through the decoder that guards attachment sends.
    #[test]
    fn base64_encode_matches_the_canonical_alphabet_and_round_trips() {
        for (raw, expected) in [
            (&b""[..], ""),
            (b"f".as_slice(), "Zg=="),
            (b"fo".as_slice(), "Zm8="),
            (b"foo".as_slice(), "Zm9v"),
            (b"foob".as_slice(), "Zm9vYg=="),
            (b"fooba".as_slice(), "Zm9vYmE="),
            (b"foobar".as_slice(), "Zm9vYmFy"),
        ] {
            assert_eq!(base64_encode(raw), expected, "{raw:?}");
        }
        // A full chunk's encoding is bounded exactly as the contract claims.
        assert_eq!(base64_encode(&[0_u8; 262_144]).len(), 349_528);
        // Random round-trip through the independent decoder.
        let mut value = [0_u8; 1000];
        use rand::RngCore;
        rand::rng().fill_bytes(&mut value);
        let mut decoded = Vec::new();
        base64_decode_to_vec(&base64_encode(&value), &mut decoded).unwrap();
        assert_eq!(decoded, value);
    }

    // ---- Contract 1.42 (§4.41); group route re-cut by contract 1.45 (§4.44) ----

    /// The upstream payload follows the engine face verbatim — a direct
    /// conversation carries `setExpirationTimer {expirationInSeconds}`, a
    /// group routes `updateGroup {account, groupId, expiration}` — after
    /// bounds, account, and conversation resolution. An unknown conversation
    /// answers CONVERSATION_NOT_FOUND, and an out-of-face value answers
    /// INVALID_REQUEST.
    #[test]
    fn set_expire_timer_preparation_shapes_upstream_by_conversation_kind() {
        let (_temp, service) = service();
        let account = service
            .sync_accounts_from_numbers(
                &[("+15555550100".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap()
            .remove(0);
        let direct = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        let group = service
            .store_ref()
            .ensure_conversation(&account.id, "group", "group-id-1", "group")
            .unwrap();

        let (direct_method, direct_payload, seconds) = service
            .prepare_conversations_set_expire_timer(&account.id, &direct.id, 86_400)
            .unwrap();
        assert_eq!(direct_method, "setExpirationTimer");
        assert_eq!(seconds, 86_400);
        assert_eq!(
            direct_payload,
            json!({
                "account": "+15555550100",
                "recipient": "+15555550101",
                "expirationInSeconds": 86_400,
            })
        );

        // Group route (§4.44): updateGroup.
        let (group_method, group_payload, group_seconds) = service
            .prepare_conversations_set_expire_timer(&account.id, &group.id, 3600)
            .unwrap();
        assert_eq!(group_method, "updateGroup");
        assert_eq!(group_seconds, 3600);
        assert_eq!(
            group_payload,
            json!({
                "account": "+15555550100",
                "groupId": "group-id-1",
                "expiration": 3600,
            })
        );

        let missing = service
            .prepare_conversations_set_expire_timer(&account.id, "conv-absent", 60)
            .unwrap_err();
        assert!(matches!(
            missing,
            ServiceError::Store(StoreError::ConversationNotFound)
        ));

        let oversized = service
            .prepare_conversations_set_expire_timer(
                &account.id,
                &direct.id,
                MAX_EXPIRE_TIMER_SECONDS + 1,
            )
            .unwrap_err();
        assert!(matches!(oversized, ServiceError::Api(ref api) if api.code == "INVALID_REQUEST"));
    }

    /// A timer notice mirrors the conversation's new timer state before the
    /// row lands (the conversation.changed summary already carries it), the
    /// notice row itself never sweeps (its expire columns stay empty), and a
    /// regular row carries the envelope-stated timer verbatim. The close
    /// form — no stated value — reads the state off.
    #[test]
    fn ingest_timer_change_mirrors_state_and_lands_a_nonsweeping_row() {
        let (_temp, mut service) = service();
        let timer_change = NormalizedReceive {
            required_protocol_version: None,
            timestamp: Some(1727000000000),
            content_kind: "dataMessage",
            direction: "system",
            account_present: true,
            account: Some("+15555550100".into()),
            source: Some("+15555550101".into()),
            source_uuid: None,
            peer_name: Some("Peer".into()),
            group_id: None,
            text: Some("已更新消息定时消失：86400 秒".into()),
            text_bytes: None,
            text_truncated: false,
            quote: None,
            attachments: Vec::new(),
            rich: Some(crate::engine::NormalizedRich {
                is_expiration_update: true,
                ..Default::default()
            }),
            sticker: None,
            expire_seconds: Some(86_400),
            expire_start_at: None,
            control: None,
            server_guid: None,
            reporting_token: None,
            server_timestamp: None,
        };
        let events = service
            .ingest_receive(timer_change.clone(), crate::DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let upserted = events
            .iter()
            .find_map(|event| match event {
                HostSideEvent::MessageUpserted(message) => Some(message),
                _ => None,
            })
            .expect("timer notice row");
        assert_eq!(upserted.direction, "system");
        let changed = events
            .iter()
            .find_map(|event| match event {
                HostSideEvent::ConversationChanged(summary) => Some(summary),
                _ => None,
            })
            .expect("state mirror event");
        assert_eq!(changed.expire_timer_seconds, Some(86_400));

        let account = service
            .sync_accounts_from_numbers(
                &[("+15555550100".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap()
            .remove(0);
        let conversation = service
            .store_ref()
            .list_conversations(&account.id, 10, None)
            .unwrap()
            .items
            .remove(0);
        let rows = service
            .store_ref()
            .list_messages(&account.id, &conversation.id, 10, None)
            .unwrap();
        assert_eq!(rows.items.len(), 1);
        assert_eq!(rows.items[0].expire_seconds, None);
        assert_eq!(rows.items[0].expire_start_at, None);

        // The close form mirrors the off state and lands the closed copy (a
        // distinct protocol timestamp: signal identity dedup would otherwise
        // swallow the second notice).
        let close = NormalizedReceive {
            timestamp: Some(1727000000001),
            text: Some("已更新消息定时消失：已关闭".into()),
            expire_seconds: None,
            server_guid: None,
            reporting_token: None,
            server_timestamp: None,
            ..timer_change
        };
        let events = service
            .ingest_receive(close, crate::DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let changed = events
            .iter()
            .find_map(|event| match event {
                HostSideEvent::ConversationChanged(summary) => Some(summary),
                _ => None,
            })
            .expect("close mirror event");
        assert_eq!(changed.expire_timer_seconds, Some(0));
    }

    // ---- Contract 1.45 (§4.44): group management write face ----

    /// The groups.update refusal ladder answers before any upstream call:
    /// empty change sets, explicit empty member arrays, oversized strings
    /// and rosters, bad enums, direct addressing, unknown conversations, a
    /// malformed operationId.
    #[test]
    fn groups_update_preparation_refuses_the_gaps() {
        let (_temp, service) = service();
        let account = service
            .sync_accounts_from_numbers(
                &[("+15555550100".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap()
            .remove(0);
        let group = service
            .store_ref()
            .ensure_conversation(&account.id, "group", "group-id-1", "group")
            .unwrap();
        let direct = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        let base = |conversation_id: &str| GroupsUpdateParams {
            account_id: account.id.clone(),
            conversation_id: conversation_id.into(),
            group_name: None,
            group_description: None,
            add_members: None,
            remove_members: None,
            promote_admins: None,
            demote_admins: None,
            ban_members: None,
            unban_members: None,
            link_state: None,
            reset_link: None,
            permission_add_member: None,
            permission_edit_details: None,
            permission_send_messages: None,
            permission_member_label: None,
            member_label: None,
            member_label_emoji: None,
            avatar: AvatarUpdate::Keep,
            operation_id: None,
        };

        // The refusal ladder — each before any upstream call.
        let refused = |params: GroupsUpdateParams| {
            let error = service.prepare_groups_update(&params).unwrap_err();
            assert!(
                matches!(error, ServiceError::Api(ref api) if api.code == "INVALID_REQUEST"),
                "expected INVALID_REQUEST"
            );
        };
        refused(GroupsUpdateParams {
            group_name: Some(String::new()),
            ..base(&group.id)
        });
        refused(GroupsUpdateParams {
            group_name: None,
            ..base(&group.id)
        }); // no change at all
        refused(GroupsUpdateParams {
            reset_link: Some(false),
            ..base(&group.id)
        }); // false is absence, not a change
        refused(GroupsUpdateParams {
            add_members: Some(Vec::new()),
            ..base(&group.id)
        }); // explicit empty member array
        refused(GroupsUpdateParams {
            add_members: Some(vec!["+15555550101".into(); MAX_GROUP_MEMBERS + 1]),
            ..base(&group.id)
        });
        refused(GroupsUpdateParams {
            add_members: Some(vec!["x".repeat(MAX_GROUP_MEMBER_ID_CHARS + 1)]),
            ..base(&group.id)
        });
        refused(GroupsUpdateParams {
            group_name: Some("長".repeat(GROUP_NAME_MAX_BYTES / 3 + 1)),
            ..base(&group.id)
        });
        refused(GroupsUpdateParams {
            group_description: Some("d".repeat(GROUP_DESCRIPTION_MAX_BYTES + 1)),
            ..base(&group.id)
        });
        refused(GroupsUpdateParams {
            member_label: Some("".into()),
            ..base(&group.id)
        });
        refused(GroupsUpdateParams {
            member_label_emoji: Some("👍👍".into()),
            ..base(&group.id)
        });
        refused(GroupsUpdateParams {
            link_state: Some("open".into()),
            ..base(&group.id)
        });
        refused(GroupsUpdateParams {
            permission_send_messages: Some("nobody".into()),
            ..base(&group.id)
        });
        refused(GroupsUpdateParams {
            operation_id: Some("".into()),
            ..base(&group.id)
        });
        // Direct addressing and unknown conversations answer their ladder
        // steps, not the group payload.
        refused(GroupsUpdateParams {
            conversation_id: direct.id.clone(),
            group_name: Some("New Name".into()),
            ..base(&group.id)
        });
        let missing = service
            .prepare_groups_update(&GroupsUpdateParams {
                conversation_id: "conv-absent".into(),
                group_name: Some("New Name".into()),
                ..base(&group.id)
            })
            .unwrap_err();
        assert!(matches!(
            missing,
            ServiceError::Store(StoreError::ConversationNotFound)
        ));
    }

    /// The wired engine face (contract 1.115, §4.96): a change set carried
    /// by the engine subset folds onto the updateGroup payload verbatim
    /// (groupName→title, the member arrays, the avatar tri-state, the link
    /// access word); any change key outside the subset answers
    /// CAPABILITY_UNAVAILABLE (retryable=false) naming the offending keys
    /// after the local validation — the honest whole-call refusal, never a
    /// partial application — while an invalid one keeps its
    /// INVALID_REQUEST. groups.quit produces the leaveGroup {account,
    /// groupId} payload.
    #[test]
    fn groups_update_and_quit_fold_onto_the_engine_face() {
        let (_temp, service) = service();
        let account = service
            .sync_accounts_from_numbers(
                &[("+15555550100".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap()
            .remove(0);
        let group = service
            .store_ref()
            .ensure_conversation(&account.id, "group", "group-id-1", "group")
            .unwrap();
        let base = |group_name: Option<String>,
                    group_description: Option<String>,
                    add_members: Option<Vec<String>>,
                    remove_members: Option<Vec<String>>,
                    link_state: Option<String>| GroupsUpdateParams {
            account_id: account.id.clone(),
            conversation_id: group.id.clone(),
            group_name,
            group_description,
            add_members,
            remove_members,
            promote_admins: None,
            demote_admins: None,
            ban_members: None,
            unban_members: None,
            link_state,
            reset_link: None,
            permission_add_member: None,
            permission_edit_details: None,
            permission_send_messages: None,
            permission_member_label: None,
            member_label: None,
            member_label_emoji: None,
            avatar: AvatarUpdate::Keep,
            operation_id: None,
        };
        let payload = service
            .prepare_groups_update(&base(
                Some("New Name".into()),
                None,
                Some(vec!["+15555550101".into()]),
                Some(vec!["+15555550102".into()]),
                Some("enabled-with-approval".into()),
            ))
            .unwrap();
        assert_eq!(
            payload,
            json!({
                "account": "+15555550100",
                "groupId": "group-id-1",
                "title": "New Name",
                "addMembers": ["+15555550101"],
                "removeMembers": ["+15555550102"],
                "addFromInviteLinkAccess": "ADMINISTRATOR"
            })
        );
        // Any key outside the engine subset refuses the whole call, naming
        // the offenders.
        let error = service
            .prepare_groups_update(&base(
                Some("New Name".into()),
                Some("KT ops group".into()),
                None,
                None,
                None,
            ))
            .unwrap_err();
        assert!(matches!(error, ServiceError::Api(ref api)
                if api.code == "CAPABILITY_UNAVAILABLE"
                    && !api.retryable
                    && api.message.contains("groupDescription")));
        // Validation outranks the capability gate: the empty change set.
        let error = service
            .prepare_groups_update(&base(None, None, None, None, None))
            .unwrap_err();
        assert!(matches!(error, ServiceError::Api(ref api) if api.code == "INVALID_REQUEST"));

        let quit = GroupsQuitParams {
            account_id: account.id.clone(),
            conversation_id: group.id.clone(),
            operation_id: None,
        };
        let payload = service.prepare_groups_quit(&quit).unwrap();
        assert_eq!(
            payload,
            json!({
                "account": "+15555550100",
                "groupId": "group-id-1"
            })
        );
    }

    /// The groups.update resetLink fold (contract 1.180, §4.180): the
    /// official refreshGroupLink — a fresh 16-byte CSPRNG password minted
    /// connector-side (the official client's own posture,
    /// conversations.preload.ts:4793-4795) riding the engine's
    /// inviteLinkPassword arm as standard base64. Two calls never mint the
    /// same password; the payload never carries a `resetLink` key (the
    /// engine face has none); the fold composes with the link-access word
    /// in the same atomic change set.
    #[test]
    fn groups_update_reset_link_folds_a_fresh_password() {
        let (_temp, service) = service();
        let account = service
            .sync_accounts_from_numbers(
                &[("+15555550100".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap()
            .remove(0);
        let group = service
            .store_ref()
            .ensure_conversation(&account.id, "group", "group-id-1", "group")
            .unwrap();
        let params = |reset_link: Option<bool>, link_state: Option<String>| GroupsUpdateParams {
            account_id: account.id.clone(),
            conversation_id: group.id.clone(),
            group_name: None,
            group_description: None,
            add_members: None,
            remove_members: None,
            promote_admins: None,
            demote_admins: None,
            ban_members: None,
            unban_members: None,
            link_state,
            reset_link,
            permission_add_member: None,
            permission_edit_details: None,
            permission_send_messages: None,
            permission_member_label: None,
            member_label: None,
            member_label_emoji: None,
            avatar: AvatarUpdate::Keep,
            operation_id: None,
        };
        let first = service
            .prepare_groups_update(&params(Some(true), None))
            .unwrap();
        let second = service
            .prepare_groups_update(&params(Some(true), None))
            .unwrap();
        let password_of = |payload: &Value| -> String {
            let password = payload.get("inviteLinkPassword").and_then(Value::as_str);
            assert!(password.is_some(), "payload carries inviteLinkPassword");
            let password = password.expect("checked above");
            // Standard base64 of exactly 16 bytes: 24 chars, ending in the
            // two-char padding of the 16-byte tail block (the official
            // GROUP_INVITE_LINK_PASSWORD_LENGTH material).
            assert_eq!(password.len(), 24);
            assert!(password.ends_with("=="));
            assert!(password.bytes().all(|byte| byte.is_ascii_alphanumeric()
                || byte == b'+'
                || byte == b'/'
                || byte == b'='));
            password.to_string()
        };
        let first_password = password_of(&first);
        let second_password = password_of(&second);
        assert_ne!(first_password, second_password, "each mint is fresh");
        assert!(
            first.get("resetLink").is_none(),
            "the engine face carries no resetLink key"
        );
        // The fold composes with the link-access word in one atomic set.
        let mixed = service
            .prepare_groups_update(&params(Some(true), Some("enabled-without-approval".into())))
            .unwrap();
        assert_eq!(mixed.get("addFromInviteLinkAccess"), Some(&json!("ANY")));
        let mixed_password = password_of(&mixed);
        assert_ne!(mixed_password, first_password);
        // resetLink: false keeps its absent semantics (1.45) — no change,
        // the empty-set refusal.
        let error = service
            .prepare_groups_update(&params(Some(false), None))
            .unwrap_err();
        assert!(matches!(error, ServiceError::Api(ref api) if api.code == "INVALID_REQUEST"));
    }

    /// The announcements-only write fold (contract 1.188, §4.188): the host
    /// vocabulary keeps the official permission word pair, the engine fold
    /// maps it onto the engine's own `announcementsOnly` bool (its
    /// updateGroup arm, engine `8ea56f6` — the official
    /// modifyAnnouncementsOnly group change action). Both values are real
    /// write intents: only-admins is the announcements-only group,
    /// every-member lifts it. The other refused keys keep their whole-call
    /// CAPABILITY_UNAVAILABLE — the engine face still does not carry them.
    #[test]
    fn groups_update_announcements_only_folds_onto_engine_face() {
        let (_temp, service) = service();
        let account = service
            .sync_accounts_from_numbers(
                &[("+15555550100".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap()
            .remove(0);
        let group = service
            .store_ref()
            .ensure_conversation(&account.id, "group", "group-id-1", "group")
            .unwrap();
        let params = |permission: Option<String>| GroupsUpdateParams {
            account_id: account.id.clone(),
            conversation_id: group.id.clone(),
            group_name: None,
            group_description: None,
            add_members: None,
            remove_members: None,
            promote_admins: None,
            demote_admins: None,
            ban_members: None,
            unban_members: None,
            link_state: None,
            reset_link: None,
            permission_add_member: None,
            permission_edit_details: None,
            permission_send_messages: permission,
            permission_member_label: None,
            member_label: None,
            member_label_emoji: None,
            avatar: AvatarUpdate::Keep,
            operation_id: None,
        };
        // only-admins → announcementsOnly true.
        let payload = service
            .prepare_groups_update(&params(Some("only-admins".into())))
            .unwrap();
        assert_eq!(
            payload,
            json!({
                "account": "+15555550100",
                "groupId": "group-id-1",
                "announcementsOnly": true
            })
        );
        // every-member → announcementsOnly false (lifting is a real write,
        // not an absent key).
        let payload = service
            .prepare_groups_update(&params(Some("every-member".into())))
            .unwrap();
        assert_eq!(
            payload,
            json!({
                "account": "+15555550100",
                "groupId": "group-id-1",
                "announcementsOnly": false
            })
        );
        // The fold composes with the other carried keys in one atomic
        // engine change set.
        let mixed = service
            .prepare_groups_update(&GroupsUpdateParams {
                group_name: Some("Renamed".into()),
                ..params(Some("only-admins".into()))
            })
            .unwrap();
        assert_eq!(mixed["title"], json!("Renamed"));
        assert_eq!(mixed["announcementsOnly"], json!(true));
        // Contract 1.252 (§4.238): the access-control arms fold onto the
        // engine words (every-member = MEMBER, only-admins = ADMINISTRATOR)
        // — the whole-call refusal they used to answer is gone.
        let folded = service
            .prepare_groups_update(&GroupsUpdateParams {
                permission_add_member: Some("only-admins".into()),
                permission_edit_details: Some("every-member".into()),
                permission_member_label: Some("only-admins".into()),
                ..params(None)
            })
            .unwrap();
        assert_eq!(folded["membersPermission"], json!("ADMINISTRATOR"));
        assert_eq!(folded["attributesPermission"], json!("MEMBER"));
        assert_eq!(folded["memberLabelPermission"], json!("ADMINISTRATOR"));
        // The folds compose with the other carried keys in one atomic
        // engine change set (the single-Actions broadcast discipline).
        let mixed_access = service
            .prepare_groups_update(&GroupsUpdateParams {
                permission_member_label: Some("every-member".into()),
                ..params(Some("only-admins".into()))
            })
            .unwrap();
        assert_eq!(mixed_access["memberLabelPermission"], json!("MEMBER"));
        assert_eq!(mixed_access["announcementsOnly"], json!(true));
        // The description write key keeps its refusal too — the engine's
        // updateGroup carries no description arm (the §4.188 recorded gap;
        // the local validation ladder still runs ahead of the seam).
        let error = service
            .prepare_groups_update(&GroupsUpdateParams {
                group_description: Some("no engine arm yet".into()),
                ..params(None)
            })
            .unwrap_err();
        assert!(matches!(error, ServiceError::Api(ref api)
                if api.code == "CAPABILITY_UNAVAILABLE"
                    && !api.retryable
                    && api.message.contains("groupDescription")));
        // Mixing a folded access arm with an unsupported key still refuses
        // the whole call naming the unsupported host key — never a partial
        // application (the engine commits the set as one change broadcast).
        let error = service
            .prepare_groups_update(&GroupsUpdateParams {
                group_description: Some("no engine arm yet".into()),
                permission_member_label: Some("only-admins".into()),
                ..params(None)
            })
            .unwrap_err();
        assert!(matches!(error, ServiceError::Api(ref api)
                if api.code == "CAPABILITY_UNAVAILABLE"
                    && !api.retryable
                    && api.message.contains("groupDescription")
                    && !api.message.contains("permissionMemberLabel")));
        // An invalid send-messages word keeps its INVALID_REQUEST (the
        // params ladder outranks the fold).
        let error = service
            .prepare_groups_update(&params(Some("nobody".into())))
            .unwrap_err();
        assert!(matches!(error, ServiceError::Api(ref api) if api.code == "INVALID_REQUEST"));
    }

    /// The groups.update avatar tri-state (contract 1.89; the engine face
    /// wired by 1.115): the wire deserialization keeps the three states
    /// distinct (the dedicated `AvatarUpdate` — an explicit null is
    /// `Remove`, never folded into absence); the data-URI shape refusals
    /// answer INVALID_REQUEST before any gate; a lone explicit-null or lone
    /// data-URI call is a real change (it produces the updateGroup payload
    /// with the avatar member, not the empty-set INVALID_REQUEST). Zero
    /// local writes on every branch.
    #[test]
    fn groups_update_avatar_tri_state_shapes_and_payload() {
        // The wire deserialization: absent → Keep, explicit null → Remove,
        // string → Replace, any other JSON type → the params-shape
        // INVALID_REQUEST (the host's blanket refusal).
        let deserialized = |value: Value| {
            serde_json::from_value::<GroupsUpdateParams>(json!({
                "accountId": "a", "conversationId": "c", "avatar": value
            }))
        };
        let kept: GroupsUpdateParams =
            serde_json::from_value(json!({ "accountId": "a", "conversationId": "c" })).unwrap();
        assert_eq!(kept.avatar, AvatarUpdate::Keep);
        assert_eq!(
            deserialized(json!(null)).unwrap().avatar,
            AvatarUpdate::Remove
        );
        assert_eq!(
            deserialized(json!("data:image/png;base64,YQ=="))
                .unwrap()
                .avatar,
            AvatarUpdate::Replace("data:image/png;base64,YQ==".into())
        );
        assert!(deserialized(json!(7)).is_err());
        assert!(deserialized(json!(["data:image/png;base64,YQ=="])).is_err());

        let (_temp, service) = service();
        let account = service
            .sync_accounts_from_numbers(
                &[("+15555550100".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap()
            .remove(0);
        let group = service
            .store_ref()
            .ensure_conversation(&account.id, "group", "group-id-1", "group")
            .unwrap();
        let base = |avatar: AvatarUpdate| GroupsUpdateParams {
            account_id: account.id.clone(),
            conversation_id: group.id.clone(),
            group_name: None,
            group_description: None,
            add_members: None,
            remove_members: None,
            promote_admins: None,
            demote_admins: None,
            ban_members: None,
            unban_members: None,
            link_state: None,
            reset_link: None,
            permission_add_member: None,
            permission_edit_details: None,
            permission_send_messages: None,
            permission_member_label: None,
            member_label: None,
            member_label_emoji: None,
            avatar,
            operation_id: None,
        };
        // The data-URI shape refusals: a non-image family, a non-canonical
        // base64 payload, and a decode beyond the 10 MiB budget —
        // INVALID_REQUEST, ahead of the capability gate (the fourth
        // shape refusal, a non-string avatar, answered at the params
        // deserialization above).
        let over_budget = format!(
            "data:image/png;base64,{}",
            "QUJD".repeat(MAX_AVATAR_BYTES / 3 + 1)
        );
        for shape in [
            "data:text/html;base64,YQ==",
            "data:image/png;base64,YQ",
            over_budget.as_str(),
        ] {
            let error = service
                .prepare_groups_update(&base(AvatarUpdate::Replace(shape.into())))
                .unwrap_err();
            assert!(
                matches!(error, ServiceError::Api(ref api)
                    if api.code == "INVALID_REQUEST" && !api.retryable),
                "shape {shape} must refuse INVALID_REQUEST"
            );
        }

        // The exact 10 MiB decoded budget passes the shape gate and lands
        // the updateGroup payload with the avatar member verbatim.
        let at_bound = format!(
            "data:image/png;base64,{}",
            "QUJD".repeat(MAX_AVATAR_BYTES / 3)
        );
        let payload = service
            .prepare_groups_update(&base(AvatarUpdate::Replace(at_bound.clone())))
            .unwrap();
        assert_eq!(
            payload,
            json!({
                "account": "+15555550100",
                "groupId": "group-id-1",
                "avatar": at_bound
            })
        );

        // A lone explicit-null call produces the payload with the Remove
        // form — the payload (not the empty-set INVALID_REQUEST) proves the
        // Remove form counts as the change set's avatar member.
        let payload = service
            .prepare_groups_update(&base(AvatarUpdate::Remove))
            .unwrap();
        assert_eq!(
            payload,
            json!({
                "account": "+15555550100",
                "groupId": "group-id-1",
                "avatar": null
            })
        );

        // The avatar member rides beside a text change in one payload —
        // one updateGroup dispatch, one change broadcast.
        let payload = service
            .prepare_groups_update(&GroupsUpdateParams {
                group_name: Some("New Name".into()),
                avatar: AvatarUpdate::Replace("data:image/png;base64,YQ==".into()),
                ..base(AvatarUpdate::Keep)
            })
            .unwrap();
        assert_eq!(
            payload,
            json!({
                "account": "+15555550100",
                "groupId": "group-id-1",
                "title": "New Name",
                "avatar": "data:image/png;base64,YQ=="
            })
        );

        // A keep (the key absent) is no avatar change at all: a call with no
        // other change is the §4.44 empty set, refused before the gates.
        let error = service
            .prepare_groups_update(&base(AvatarUpdate::Keep))
            .unwrap_err();
        assert!(matches!(error, ServiceError::Api(ref api)
                if api.code == "INVALID_REQUEST"
                    && api.message.contains("at least one group change")));
    }

