    /// Contract 1.70 (§4.58 consume batch) + 1.253 (§4.239 row legs): the
    /// message-request response sync consumption. An ACCEPT mirror stamps the
    /// authoritative factor on the resolved direct conversation (the ACI
    /// ladder: raw ACI → the recorded ACI→peer-key mapping), rides
    /// `conversation.changed` with the accepted state, and lands the
    /// §4.239 timeline system row (the official MRR_SYNC mint, gate
    /// didResponseChange); a non-ACCEPT member (DELETE) stamps the terminal
    /// not-accepted and mints no row (the official DELETE has no mint arm);
    /// a mirror naming nothing local converges nothing; a group-threaded
    /// mirror is refused (groups carry no request).
    #[test]
    fn ingest_message_request_response_stamps_the_authoritative_factor() {
        let (_temp, mut service) = service();
        let account = service
            .sync_accounts_from_numbers(
                &[("+15555550100".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap()
            .remove(0);
        let direct = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        let mut incoming = expire_record_fixture(&account.id, &direct.id, "mrr-in");
        incoming.sent_at = 10;
        service
            .store_ref()
            .insert_message(&incoming, None, None, false)
            .unwrap();
        let base = NormalizedReceive {
            required_protocol_version: None,
            timestamp: Some(1727000000000),
            content_kind: "control",
            direction: "incoming",
            account_present: true,
            account: Some("+15555550100".into()),
            source: None,
            source_uuid: None,
            server_guid: None,
            reporting_token: None,
            server_timestamp: None,
            peer_name: None,
            group_id: None,
            text: None,
            text_bytes: None,
            text_truncated: false,
            quote: None,
            attachments: Vec::new(),
            rich: None,
            sticker: None,
            expire_seconds: None,
            expire_start_at: None,
            control: Some(ControlReceive::MessageRequestResponse {
                response_type: 1,
                thread_aci: Some("0b7fca57-1234-4d0e-9b0f-4f6c1f8a2e10".into()),
                group_id: None,
                timestamp: None,
            }),
        };

        // Before the mirror: the incoming-only row is pending (the honest
        // no-stamp derivation). The mirror keys its thread by the peer's ACI,
        // so the §4.37 mapping that resolution walks is recorded up front —
        // the same shape a real receive chain leaves behind.
        service
            .store_ref()
            .upsert_peer_identity(
                &account.id,
                "0b7fca57-1234-4d0e-9b0f-4f6c1f8a2e10",
                "+15555550101",
            )
            .unwrap();
        let before = service
            .store_ref()
            .conversation_summary(&account.id, &direct.id)
            .unwrap()
            .unwrap();
        assert!(!before.message_request_accepted);

        // The ACCEPT mirror flips it through conversation.changed and the
        // store state both.
        let events = service
            .ingest_receive(base.clone(), crate::DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        // §4.239: the mirror mints the bodyless system row beside the stamp
        // (the official MRR_SYNC mint — row first, then the summary).
        let upserted = events
            .iter()
            .filter_map(|event| match event {
                HostSideEvent::MessageUpserted(row) => Some(row),
                _ => None,
            })
            .collect::<Vec<_>>();
        assert_eq!(
            upserted.len(),
            1,
            "exactly the §4.239 row rides: {events:?}"
        );
        assert_eq!(upserted[0].direction, "system");
        assert_eq!(upserted[0].status, "system");
        assert_eq!(
            upserted[0]
                .rich
                .as_ref()
                .and_then(|rich| rich.message_request_response_event.as_deref()),
            Some("ACCEPT")
        );
        assert!(upserted[0].text.is_none(), "the official row is bodyless");
        let changed = events
            .iter()
            .find_map(|event| match event {
                HostSideEvent::ConversationChanged(summary) => Some(summary),
                _ => None,
            })
            .expect("the stamp rides conversation.changed");
        assert_eq!(changed.id, direct.id);
        assert!(changed.message_request_accepted);
        let after = service
            .store_ref()
            .conversation_summary(&account.id, &direct.id)
            .unwrap()
            .unwrap();
        assert!(after.message_request_accepted);

        // The DELETE twin (member 2) stamps the terminal not-accepted back.
        let delete = NormalizedReceive {
            control: Some(ControlReceive::MessageRequestResponse {
                response_type: 2,
                thread_aci: Some("0b7fca57-1234-4d0e-9b0f-4f6c1f8a2e10".into()),
                group_id: None,
                timestamp: None,
            }),
            ..base.clone()
        };
        let events = service
            .ingest_receive(delete, crate::DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let changed = events
            .iter()
            .find_map(|event| match event {
                HostSideEvent::ConversationChanged(summary) => Some(summary),
                _ => None,
            })
            .expect("the delete stamp rides conversation.changed too");
        assert!(!changed.message_request_accepted);

        // The idempotent re-stamp: a same-value ACCEPT re-pushes the summary
        // (the GroupTimerUpdate convergence discipline).
        assert!(
            service
                .ingest_receive(base, crate::DEFAULT_PROXY_GROUP_ID)
                .unwrap()
                .iter()
                .any(|event| matches!(event, HostSideEvent::ConversationChanged(_)))
        );
        let stamped = service
            .store_ref()
            .conversation_summary(&account.id, &direct.id)
            .unwrap()
            .unwrap();
        assert!(stamped.message_request_accepted);

        // Nothing local (an unknown ACI) converges nothing.
        let unknown = NormalizedReceive {
            control: Some(ControlReceive::MessageRequestResponse {
                response_type: 1,
                thread_aci: Some("99999999-9999-9999-9999-999999999999".into()),
                group_id: None,
                timestamp: None,
            }),
            ..base_shape_for_unknown_test()
        };
        assert!(
            service
                .ingest_receive(unknown, crate::DEFAULT_PROXY_GROUP_ID)
                .unwrap()
                .is_empty()
        );

        // A group-threaded mirror is refused: the request family is 1:1 only.
        let group_mirror = NormalizedReceive {
            group_id: None,
            control: Some(ControlReceive::MessageRequestResponse {
                response_type: 1,
                thread_aci: None,
                group_id: Some("AAECAwQFBgcICQoLDA0ODxAREhMUFRYXGBkaGxwdHh8=".into()),
                timestamp: None,
            }),
            ..base_shape_for_unknown_test()
        };
        assert!(
            service
                .ingest_receive(group_mirror, crate::DEFAULT_PROXY_GROUP_ID)
                .unwrap()
                .is_empty(),
            "groups carry no request to accept"
        );
    }

    /// Contract 1.258 (§4.58 additive · batch X · S7②): the mirror row's
    /// clock is the projected sync moment — the row lands with
    /// `sent_at = timestamp` (+ the multi-arm offset), not the local wall
    /// clock. A control face without the additive key keeps the recorded
    /// local-clock degradation (covered by the sibling tests above, which
    /// assert shape only).
    #[test]
    fn ingest_message_request_response_row_sent_at_rides_projected_sync_moment() {
        let (_temp, mut service) = service();
        let account = service
            .sync_accounts_from_numbers(
                &[("+15555550100".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap()
            .remove(0);
        let direct = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        let mut incoming = expire_record_fixture(&account.id, &direct.id, "mrr-ts");
        incoming.sent_at = 10;
        service
            .store_ref()
            .insert_message(&incoming, None, None, false)
            .unwrap();
        service
            .store_ref()
            .upsert_peer_identity(
                &account.id,
                "0b7fca57-1234-4d0e-9b0f-4f6c1f8a2e10",
                "+15555550101",
            )
            .unwrap();
        let sync_moment = 1_700_000_000_123_u64;
        let stamped = NormalizedReceive {
            required_protocol_version: None,
            timestamp: Some(1_727_000_000_000),
            content_kind: "control",
            direction: "incoming",
            account_present: true,
            account: Some("+15555550100".into()),
            source: None,
            source_uuid: None,
            server_guid: None,
            reporting_token: None,
            server_timestamp: None,
            peer_name: None,
            group_id: None,
            text: None,
            text_bytes: None,
            text_truncated: false,
            quote: None,
            attachments: Vec::new(),
            rich: None,
            sticker: None,
            expire_seconds: None,
            expire_start_at: None,
            control: Some(ControlReceive::MessageRequestResponse {
                response_type: 1,
                thread_aci: Some("0b7fca57-1234-4d0e-9b0f-4f6c1f8a2e10".into()),
                group_id: None,
                timestamp: Some(sync_moment),
            }),
        };
        let events = service
            .ingest_receive(stamped, crate::DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let row = events
            .iter()
            .find_map(|event| match event {
                HostSideEvent::MessageUpserted(row) => Some(row),
                _ => None,
            })
            .expect("the mirror row rides");
        // The official MRR_SYNC mint: sent_at = the sync envelope's own
        // timestamp (responseInfo.timestamp), zero arms appended on a pure
        // ACCEPT face.
        assert_eq!(row.sent_at, sync_moment);
    }

    /// Batch X · S6①: the stale-avatar target classifier — a peer profile
    /// change resolves through the direct ladder and clears the cached
    /// entry; a group change batch gates on the official avatar member;
    /// non-avatar group changes and unresolvable ACIs queue nothing.
    #[test]
    fn stale_avatar_targets_classify_receive_batch_events() {
        assert!(group_avatar_change_present(
            &serde_json::json!([{"type": "avatar", "removed": false}])
        ));
        assert!(group_avatar_change_present(&serde_json::json!([
            {"type": "member-added"},
            {"type": "avatar", "removed": true}
        ])));
        assert!(!group_avatar_change_present(&serde_json::json!([
            {"type": "member-added"}
        ])));
        assert!(!group_avatar_change_present(
            &serde_json::json!({"type": "avatar"})
        ));
        assert!(!group_avatar_change_present(&serde_json::json!("avatar")));

        let (_temp, service) = service();
        let account = service
            .sync_accounts_from_numbers(
                &[("+15555550100".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap()
            .remove(0);
        let direct = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        service
            .store_ref()
            .upsert_conversation_avatar(
                &account.id,
                &direct.id,
                "data:image/png;base64,QQ==",
                1,
                crate::link::now_ms(),
            )
            .unwrap();
        service
            .store_ref()
            .upsert_peer_identity(
                &account.id,
                "0b7fca57-1234-4d0e-9b0f-4f6c1f8a2e10",
                "+15555550101",
            )
            .unwrap();
        let events = vec![HostSideEvent::ContactProfileUpdated {
            account_id: account.id.clone(),
            aci: "0b7fca57-1234-4d0e-9b0f-4f6c1f8a2e10".into(),
            timestamp: Some(1_727_000_000_000),
        }];
        let targets = service.stale_avatar_targets(&events);
        assert_eq!(
            targets,
            vec![(account.id.clone(), direct.id.clone())],
            "the profile change resolves to the direct row"
        );
        assert!(
            service
                .store_ref()
                .conversation_avatar(&account.id, &direct.id)
                .unwrap()
                .is_none(),
            "the stale cache entry cleared"
        );

        // An ACI nothing local resolves queues nothing.
        let unknown = vec![HostSideEvent::ContactProfileUpdated {
            account_id: account.id.clone(),
            aci: "99999999-9999-9999-9999-999999999999".into(),
            timestamp: None,
        }];
        assert!(service.stale_avatar_targets(&unknown).is_empty());

        // A group change with the avatar member targets its conversation;
        // a batch without it queues nothing.
        let group = service
            .store_ref()
            .ensure_conversation(
                &account.id,
                "group",
                "AAECAwQFBgcICQoLDA0ODxAREhMUFRYXGBkaGxwdHh8=",
                "Group",
            )
            .unwrap();
        let group_avatar = vec![HostSideEvent::GroupChanged {
            account_id: account.id.clone(),
            conversation_id: group.id.clone(),
            revision: 7,
            changes: serde_json::json!([{"type": "avatar", "removed": false}]),
            editor: None,
            expire_timer_seconds: None,
        }];
        assert_eq!(
            service.stale_avatar_targets(&group_avatar),
            vec![(account.id.clone(), group.id.clone())],
        );
        let group_other = vec![HostSideEvent::GroupChanged {
            account_id: account.id.clone(),
            conversation_id: group.id.clone(),
            revision: 8,
            changes: serde_json::json!([{"type": "member-added"}]),
            editor: None,
            expire_timer_seconds: None,
        }];
        assert!(service.stale_avatar_targets(&group_other).is_empty());
    }

    /// Contract 1.138 (§4.131): the BLOCK family verbs (3/4/6) stamp the
    /// conversation's blocked bit through the same consume batch — the
    /// refreshed summary rides conversation.changed with blocked true, the
    /// terminal not-accepted answer stays, and a non-BLOCK verb never
    /// touches the mask.
    #[test]
    fn ingest_message_request_response_block_family_stamps_blocked() {
        let (_temp, mut service) = service();
        let account = service
            .sync_accounts_from_numbers(
                &[("+15555550100".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap()
            .remove(0);
        let direct = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        service
            .store_ref()
            .upsert_peer_identity(
                &account.id,
                "0b7fca57-1234-4d0e-9b0f-4f6c1f8a2e10",
                "+15555550101",
            )
            .unwrap();
        // The seeded incoming row pins the window answer to pending (an
        // empty private conversation derives accepted, the official
        // empty-private-conversation weight) — the same material the 1.70
        // test reads.
        let mut incoming = expire_record_fixture(&account.id, &direct.id, "mrr-block");
        incoming.sent_at = 10;
        service
            .store_ref()
            .insert_message(&incoming, None, None, false)
            .unwrap();

        let block = NormalizedReceive {
            control: Some(ControlReceive::MessageRequestResponse {
                response_type: 3,
                thread_aci: Some("0b7fca57-1234-4d0e-9b0f-4f6c1f8a2e10".into()),
                group_id: None,
                timestamp: None,
            }),
            ..base_shape_for_unknown_test()
        };
        let events = service
            .ingest_receive(block, crate::DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let changed = events
            .iter()
            .find_map(|event| match event {
                HostSideEvent::ConversationChanged(summary) => Some(summary),
                _ => None,
            })
            .expect("the block stamp rides conversation.changed");
        assert!(changed.blocked);
        assert!(!changed.message_request_accepted);
        let after = service
            .store_ref()
            .conversation_summary(&account.id, &direct.id)
            .unwrap()
            .unwrap();
        assert!(after.blocked);

        // DELETE (2) closes the request without touching the mask.
        let delete = NormalizedReceive {
            control: Some(ControlReceive::MessageRequestResponse {
                response_type: 2,
                thread_aci: Some("0b7fca57-1234-4d0e-9b0f-4f6c1f8a2e10".into()),
                group_id: None,
                timestamp: None,
            }),
            ..base_shape_for_unknown_test()
        };
        service
            .ingest_receive(delete, crate::DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        let after = service
            .store_ref()
            .conversation_summary(&account.id, &direct.id)
            .unwrap()
            .unwrap();
        assert!(after.blocked, "a non-BLOCK verb never rewrites the mask");
    }

    /// 契约 1.253（§4.239）：mint 面钉形——行形态官方逐字
    /// （direction=system/status=system、无正文、事件词闭集、sender=会话
    /// peer_key）、事件对（MessageUpserted + ConversationChanged）、同刻重放
    /// 幂等（INSERT OR IGNORE 折叠）、未解析会话诚实 None、已读态不入未读。
    #[test]
    fn message_request_row_mint_faces_and_replay_idempotence() {
        let (_temp, mut service) = service();
        let (account, direct) = linked_account_and_conversation(&mut service);
        let store = service.store_ref();

        // The mint answers the row event alone — the caller owns the summary
        // push (the mirror arm stamps between the row and its changed).
        let row_event =
            store_land_message_request_row(store, &account.id, &direct.id, MrrRowEvent::Accept)
                .unwrap()
                .expect("the first mint lands");
        let HostSideEvent::MessageUpserted(row) = &row_event else {
            panic!("the mint answers the row upsert, got {row_event:?}");
        };
        assert_eq!(row.direction, "system");
        assert_eq!(row.status, "system");
        assert_eq!(row.sender_id, direct.peer_key, "the name-join face");
        assert!(row.text.is_none(), "the official row is bodyless");
        assert!(row.text_retrievable);
        assert_eq!(row.expire_seconds, None, "the notice never sweeps");
        assert_eq!(
            row.rich
                .as_ref()
                .and_then(|rich| rich.message_request_response_event.as_deref()),
            Some("ACCEPT")
        );

        // The same-clock replay folds onto the landed row (the INSERT OR
        // IGNORE idempotence): no second row, no events.
        let replay = store_land_message_request_row_at(
            store,
            &account.id,
            &direct.id,
            MrrRowEvent::Accept,
            row.sent_at,
        )
        .unwrap();
        assert!(replay.is_none(), "a same-stamp replay is a no-op");

        // The word list is the closed official family; each word rides its
        // own row at its own stamp.
        for (event, word) in [
            (MrrRowEvent::Block, "BLOCK"),
            (MrrRowEvent::Unblock, "UNBLOCK"),
            (MrrRowEvent::Spam, "SPAM"),
        ] {
            let minted = store_land_message_request_row_at(
                store,
                &account.id,
                &direct.id,
                event,
                row.sent_at + 1,
            )
            .unwrap()
            .expect("each distinct stamp mints");
            let HostSideEvent::MessageUpserted(minted_row) = &minted else {
                panic!("the mint answers the row upsert, got {minted:?}");
            };
            assert_eq!(
                minted_row
                    .rich
                    .as_ref()
                    .and_then(|rich| rich.message_request_response_event.as_deref()),
                Some(word)
            );
        }

        // The didUnblock mapping single-sources in the face: a blocked
        // conversation's accept mints the UNBLOCK word (the official
        // applyMessageRequestResponse arm), an unblocked one ACCEPT.
        store
            .set_conversation_blocked_factor(&account.id, &direct.id, true)
            .unwrap();
        let blocked_accept =
            store_land_message_request_row(store, &account.id, &direct.id, MrrRowEvent::Accept)
                .unwrap()
                .expect("the blocked accept still mints");
        let HostSideEvent::MessageUpserted(blocked_row) = &blocked_accept else {
            panic!("the mint answers the row upsert, got {blocked_accept:?}");
        };
        assert_eq!(
            blocked_row
                .rich
                .as_ref()
                .and_then(|rich| rich.message_request_response_event.as_deref()),
            Some("UNBLOCK")
        );
        store
            .set_conversation_blocked_factor(&account.id, &direct.id, false)
            .unwrap();
        let unblocked_accept =
            store_land_message_request_row(store, &account.id, &direct.id, MrrRowEvent::Accept)
                .unwrap()
                .expect("the unblocked accept mints too");
        let HostSideEvent::MessageUpserted(unblocked_row) = &unblocked_accept else {
            panic!("the mint answers the row upsert, got {unblocked_accept:?}");
        };
        assert_eq!(
            unblocked_row
                .rich
                .as_ref()
                .and_then(|rich| rich.message_request_response_event.as_deref()),
            Some("ACCEPT")
        );

        // An unknown conversation answers the honest None (no row, no lie).
        assert!(
            store_land_message_request_row(
                store,
                &account.id,
                "no-such-conversation",
                MrrRowEvent::Accept,
            )
            .unwrap()
            .is_none()
        );

        // The read-neutral landing: the notice never counts as unread (the
        // official readStatus=Read mint).
        let summary = store
            .conversation_summary(&account.id, &direct.id)
            .unwrap()
            .unwrap();
        assert_eq!(summary.unread_count, 0);
    }

    /// 契约 1.253（§4.239）：镜像臂的官方四闸逐字——didResponseChange（同值
    /// 重放不铸）、didUnblock（先态 blocked 的 ACCEPT → UNBLOCK 词）、
    /// didBlockChange（先态 blocked 的 BLOCK 臂不铸）、didSpamChange（先态
    /// spam 家族的 SPAM 臂不铸）、DELETE 无行（官方 DELETE 无铸行臂）、
    /// BLOCK_AND_SPAM 在 blocked 先态下只补 SPAM 臂。
    #[test]
    fn message_request_mirror_rows_follow_official_gates() {
        let (_temp, mut service) = service();
        let account = service
            .sync_accounts_from_numbers(
                &[("+15555550100".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap()
            .remove(0);
        let direct = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        service
            .store_ref()
            .upsert_peer_identity(
                &account.id,
                "0b7fca57-1234-4d0e-9b0f-4f6c1f8a2e10",
                "+15555550101",
            )
            .unwrap();
        let mut incoming = expire_record_fixture(&account.id, &direct.id, "mrr-rows");
        incoming.sent_at = 10;
        service
            .store_ref()
            .insert_message(&incoming, None, None, false)
            .unwrap();

        let mirror = |response_type: u8| NormalizedReceive {
            required_protocol_version: None,
            timestamp: Some(1727000000000),
            content_kind: "control",
            direction: "incoming",
            account_present: true,
            account: Some("+15555550100".into()),
            source: None,
            source_uuid: None,
            server_guid: None,
            reporting_token: None,
            server_timestamp: None,
            peer_name: None,
            group_id: None,
            text: None,
            text_bytes: None,
            text_truncated: false,
            quote: None,
            attachments: Vec::new(),
            rich: None,
            sticker: None,
            expire_seconds: None,
            expire_start_at: None,
            control: Some(ControlReceive::MessageRequestResponse {
                response_type,
                thread_aci: Some("0b7fca57-1234-4d0e-9b0f-4f6c1f8a2e10".into()),
                group_id: None,
                timestamp: None,
            }),
        };
        let words = |service: &mut ConnectorService| -> Vec<String> {
            // list_messages answers newest-first; the mint order is ascending
            // sent_at, so read the page oldest-first.
            let mut rows = service
                .list_messages(&account.id, &direct.id, 50, None)
                .unwrap()
                .items;
            rows.reverse();
            rows.iter()
                .filter_map(|row| {
                    row.rich
                        .as_ref()
                        .and_then(|rich| rich.message_request_response_event.clone())
                })
                .collect()
        };

        // didResponseChange: the fresh ACCEPT mints; the same-value replay
        // (the idempotent re-stamp posture) mints nothing.
        service
            .ingest_receive(mirror(1), crate::DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        assert_eq!(words(&mut service), vec!["ACCEPT"]);
        service
            .ingest_receive(mirror(1), crate::DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        assert_eq!(words(&mut service), vec!["ACCEPT"], "same member, no row");

        // didBlockChange: the BLOCK mirror on an unblocked conversation mints
        // the row and flips the mask (state → 3).
        service
            .ingest_receive(mirror(3), crate::DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        assert_eq!(words(&mut service), vec!["ACCEPT", "BLOCK"]);
        // The same-value BLOCK replay mints nothing (didResponseChange false;
        // the prior blocked bit would silence the BLOCK arm anyway).
        service
            .ingest_receive(mirror(3), crate::DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        assert_eq!(words(&mut service), vec!["ACCEPT", "BLOCK"]);

        // didUnblock: the ACCEPT on a blocked conversation (state 3 → 1, the
        // official block-then-accept composition) reads UNBLOCK — the gate
        // reads the prior bit before the stamps.
        service
            .ingest_receive(mirror(1), crate::DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        assert_eq!(words(&mut service), vec!["ACCEPT", "BLOCK", "UNBLOCK"]);

        // DELETE mints no row (the official DELETE has no mint arm), even
        // across a real member change.
        service
            .ingest_receive(mirror(2), crate::DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        assert_eq!(words(&mut service), vec!["ACCEPT", "BLOCK", "UNBLOCK"]);

        // BLOCK_AND_SPAM on a still-blocked conversation (DELETE never clears
        // the mask — 盖真不盖假): the BLOCK arm stays silent (no
        // didBlockChange) and the SPAM arm mints once.
        service
            .ingest_receive(mirror(6), crate::DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        assert_eq!(
            words(&mut service),
            vec!["ACCEPT", "BLOCK", "UNBLOCK", "SPAM"]
        );

        // didSpamChange: SPAM after a spam-family member mints nothing.
        service
            .ingest_receive(mirror(5), crate::DEFAULT_PROXY_GROUP_ID)
            .unwrap();
        assert_eq!(
            words(&mut service),
            vec!["ACCEPT", "BLOCK", "UNBLOCK", "SPAM"],
            "the spam family gate holds"
        );
    }

    /// Contract 1.138 (§4.130): the local draft write lane — bounds, the
    /// unknown-account/unknown-conversation refusals, and the refreshed
    /// summary the caller rides conversation.changed with.
    #[test]
    fn store_draft_faces_bound_resolve_and_stamp() {
        let (_temp, service) = service();
        let account = service
            .sync_accounts_from_numbers(
                &[("+15555550100".into(), None)],
                crate::DEFAULT_PROXY_GROUP_ID,
            )
            .unwrap()
            .remove(0);
        let direct = service
            .store_ref()
            .ensure_conversation(&account.id, "direct", "+15555550101", "Peer")
            .unwrap();
        let store = service.store_ref();

        // Bounds: empty id, oversize id, zero stamp, unknown account.
        assert!(matches!(
            store_save_conversation_draft(store, &account.id, "", 5),
            Err(ServiceError::Api(_))
        ));
        assert!(matches!(
            store_save_conversation_draft(store, &account.id, &"x".repeat(257), 5),
            Err(ServiceError::Api(_))
        ));
        assert!(matches!(
            store_save_conversation_draft(store, &account.id, &direct.id, 0),
            Err(ServiceError::Api(_))
        ));
        assert!(matches!(
            store_save_conversation_draft(store, "no-such-account", &direct.id, 5),
            Err(ServiceError::Store(StoreError::AccountNotFound))
        ));
        assert!(matches!(
            store_save_conversation_draft(store, &account.id, "no-such-conversation", 5),
            Err(ServiceError::Store(StoreError::ConversationNotFound))
        ));

        // The stamp lands and the summary carries it; the clear refreshes.
        let summary = store_save_conversation_draft(store, &account.id, &direct.id, 42).unwrap();
        assert_eq!(summary.draft_timestamp, Some(42));
        let summary = store_clear_conversation_draft(store, &account.id, &direct.id).unwrap();
        assert_eq!(summary.draft_timestamp, None);
    }

